				}
			}
			return hashSet;
		}
		private string GetCellValue(SpreadsheetDocument doc, Cell cell)
		{
			bool flag = cell == null || cell.CellValue == null;
			string result;
			if (flag)
			{
				result = "";
			}
			else
			{
				string text = cell.CellValue.Text;
				bool flag2 = cell.DataType != null && cell.DataType.Value == CellValues.SharedString;
				if (flag2)
				{
					SharedStringTablePart expr_5B = doc.WorkbookPart.SharedStringTablePart;
					SharedStringTable sharedStringTable = (expr_5B != null) ? expr_5B.SharedStringTable : null;
					int index = 0;
					bool flag3 = sharedStringTable != null && int.TryParse(text, out index);
					if (flag3)
					{
						SharedStringItem sharedStringItem = sharedStringTable.Elements<SharedStringItem>().ElementAtOrDefault(index);
						bool flag4 = sharedStringItem != null && sharedStringItem.InnerText.Length > 0;
						if (flag4)
						{
							text = sharedStringItem.InnerText;
						}
					}
				}
				result = text;
			}
			return result;
		}
