	public static class ResolveHelper
	{
		internal static Assembly ResolveAssembly(object sender, ResolveEventArgs args)
		{
			string text = null;
			MethodBase currentMethod = MethodBase.GetCurrentMethod();
			bool flag = currentMethod != null && currentMethod.DeclaringType != null;
			if (flag)
			{
				text = Path.GetDirectoryName(currentMethod.DeclaringType.Assembly.Location);
			}
			bool flag2 = text == null;
			Assembly result;
			if (flag2)
			{
				result = null;
			}
			else
			{
				string name = new AssemblyName(args.Name).Name;
				IEnumerable<string> enumerable = Directory.EnumerateFiles(text, "*.dll");
				foreach (string current in enumerable)
				{
					bool flag3 = name == Path.GetFileNameWithoutExtension(current);
					if (flag3)
					{
						result = Assembly.LoadFile(current);
						return result;
					}
				}
				result = null;
			}
			return result;
		}
	}
