	public class TSTVservice
	{
		public TriStateTreeView2 Tree
		{
			get;
			set;
		}
		public TSTVservice(string name, TableLayoutPanel tlp, Button btnNodeUp = null, Button btnNodeDown = null, int row = 0, int column = 0, int columnSpan = 1, int rowSpan = 1)
		{
			this.Tree = new TriStateTreeView2
			{
				Name = name
			};
			tlp.Controls.Add(this.Tree);
			tlp.SetCellPosition(this.Tree, new TableLayoutPanelCellPosition(column, row));
			tlp.SetColumnSpan(this.Tree, columnSpan);
			tlp.SetRowSpan(this.Tree, rowSpan);
			this.Tree.Dock = DockStyle.Fill;
			this.Tree.TabIndex = 0;
			this.Tree.AllowDrop = true;
			bool flag = btnNodeUp != null;
			if (flag)
			{
				btnNodeUp.Click += new EventHandler(this.BtnNodeUp_Click);
			}
			bool flag2 = btnNodeDown != null;
			if (flag2)
			{
				btnNodeDown.Click += new EventHandler(this.BtnNodeDown_Click);
			}
		}
		private void BtnNodeUp_Click(object sender, EventArgs e)
		{
			this.Tree.MoveSelectedNode(true);
		}
		private void BtnNodeDown_Click(object sender, EventArgs e)
		{
			this.Tree.MoveSelectedNode(false);
		}
	}
