	public class TriStateTreeView2 : TreeView
	{
		public enum CheckedState
		{
			Unchecked,
			Checked,
			Mixed
		}
		private List<TreeNode> _selectedNodes;
		private TreeView treeView1;
		private int IgnoreClickAction = 0;
		public List<TreeNode> SelectedNodes
		{
			get
			{
				return this._selectedNodes;
			}
			set
			{
				this.ClearSelectedNodes();
				bool flag = value != null;
				if (flag)
				{
					Debug.WriteLine("Выделенные элементы:");
					foreach (TreeNode current in value)
					{
						this.ToggleNode(current, true);
						Debug.WriteLine(current.Text.Split(new char[]
						{
							'-'
						})[0]);
					}
					this._selectedNodes = value;
				}
			}
		}
		public TriStateTreeView2()
		{
			base.StateImageList = new ImageList();
			this._selectedNodes = new List<TreeNode>();
			for (int i = 0; i < 3; i++)
			{
				Bitmap bitmap = new Bitmap(16, 16);
				Graphics g = Graphics.FromImage(bitmap);
				switch (i)
				{
				case 0:
					CheckBoxRenderer.DrawCheckBox(g, new System.Drawing.Point(0, 1), CheckBoxState.UncheckedNormal);
					break;
				case 1:
					CheckBoxRenderer.DrawCheckBox(g, new System.Drawing.Point(0, 1), CheckBoxState.CheckedNormal);
					break;
				case 2:
					CheckBoxRenderer.DrawCheckBox(g, new System.Drawing.Point(0, 1), CheckBoxState.MixedNormal);
					break;
				}
				base.StateImageList.Images.Add(bitmap);
			}
			base.ItemDrag += new ItemDragEventHandler(this.TvViewSheets_ItemDrag);
			base.DragEnter += new DragEventHandler(this.TvViewSheets_DragEnter);
			base.DragDrop += new DragEventHandler(this.TvViewSheets_DragDrop);
		}
		protected override void OnCreateControl()
		{
			base.OnCreateControl();
			base.CheckBoxes = false;
			this.IgnoreClickAction++;
			this.UpdateChildState(base.Nodes, 0, false, true);
			this.IgnoreClickAction--;
		}
		protected override void OnAfterCheck(TreeViewEventArgs e)
		{
			base.OnAfterCheck(e);
			bool flag = this.IgnoreClickAction > 0;
			if (!flag)
			{
				this.IgnoreClickAction++;
				TreeNode node = e.Node;
				node.StateImageIndex = (node.Checked ? 1 : 0);
				this.UpdateChildState(e.Node.Nodes, e.Node.StateImageIndex, e.Node.Checked, false);
				this.UpdateParentState(e.Node.Parent);
				this.IgnoreClickAction--;
			}
		}
		protected override void OnAfterExpand(TreeViewEventArgs e)
		{
			base.OnAfterExpand(e);
			this.IgnoreClickAction++;
			this.UpdateChildState(e.Node.Nodes, e.Node.StateImageIndex, e.Node.Checked, true);
			this.IgnoreClickAction--;
		}
		private void UpdateChildState(TreeNodeCollection nodes, int StateImageIndex, bool isChecked, bool changeUninitialisedNodesOnly)
		{
			foreach (TreeNode treeNode in nodes)
			{
				bool flag = !changeUninitialisedNodesOnly || treeNode.StateImageIndex == -1;
				if (flag)
				{
					treeNode.StateImageIndex = StateImageIndex;
					treeNode.Checked = isChecked;
					bool flag2 = treeNode.Nodes.Count > 0;
					if (flag2)
					{
						this.UpdateChildState(treeNode.Nodes, StateImageIndex, isChecked, changeUninitialisedNodesOnly);
					}
				}
			}
		}
		private void UpdateParentState(TreeNode tn)
		{
			bool flag = tn == null;
			if (!flag)
			{
				int stateImageIndex = tn.StateImageIndex;
				int num = 0;
				int num2 = 0;
				int num3 = 0;
				foreach (TreeNode treeNode in tn.Nodes)
				{
					bool flag2 = treeNode.StateImageIndex == 1;
					if (flag2)
					{
						num2++;
					}
					else
					{
						bool flag3 = treeNode.StateImageIndex == 2;
						if (flag3)
						{
							num3++;
							break;
						}
						num++;
					}
				}
				bool flag4 = num3 > 0;
				if (flag4)
				{
					tn.StateImageIndex = 2;
				}
				else
				{
					bool flag5 = num2 > 0 && num == 0;
					if (flag5)
					{
						tn.StateImageIndex = (tn.Checked ? 1 : 2);
					}
					else
					{
						bool flag6 = num2 > 0;
						if (flag6)
						{
							tn.StateImageIndex = 2;
						}
						else
						{
							tn.StateImageIndex = (tn.Checked ? 2 : 0);
						}
					}
				}
				bool flag7 = stateImageIndex != tn.StateImageIndex && tn.Parent != null;
				if (flag7)
				{
					this.UpdateParentState(tn.Parent);
				}
			}
		}
		protected override void OnKeyDown(KeyEventArgs e)
		{
			base.OnKeyDown(e);
			bool flag = e.KeyCode == Keys.Space;
			if (flag)
			{
				bool flag2 = this.SelectedNodes.Count < 1;
				if (!flag2)
				{
					bool @checked = !this.SelectedNodes[0].Checked;
					foreach (TreeNode current in this.SelectedNodes)
					{
						current.Checked = @checked;
					}
				}
			}
		}
		protected override void OnNodeMouseClick(TreeNodeMouseClickEventArgs e)
		{
			base.OnNodeMouseClick(e);
			List<TreeNode> list = new List<TreeNode>();
			TreeViewHitTestInfo treeViewHitTestInfo = base.HitTest(e.X, e.Y);
			bool flag = treeViewHitTestInfo == null || treeViewHitTestInfo.Location != TreeViewHitTestLocations.StateImage;
			if (flag)
			{
				bool flag2 = System.Windows.Forms.Control.ModifierKeys == Keys.Shift;
				if (flag2)
				{
					TreeNodeCollection nodes = e.Node.Parent.Nodes;
					int num = nodes.IndexOf(base.SelectedNode);
					int num2 = nodes.IndexOf(e.Node);
					bool flag3 = num < 0 || num2 < 0;
					if (!flag3)
					{
						bool flag4 = num2 < num;
						if (flag4)
						{
							int arg_AC_0 = num;
							num = num2;
							num2 = arg_AC_0;
						}
						for (int i = num; i <= num2; i++)
						{
							list.Add(nodes[i]);
						}
						this.SelectedNodes = list;
					}
				}
				else
				{
					bool flag5 = System.Windows.Forms.Control.ModifierKeys == Keys.Control;
					if (flag5)
					{
						list.AddRange(this.SelectedNodes);
					}
					list.Add(e.Node);
					this.SelectedNodes = list;
				}
			}
			else
			{
				bool flag6 = !this.SelectedNodes.Contains(e.Node);
				if (flag6)
				{
					e.Node.Checked = !e.Node.Checked;
				}
				else
				{
					bool flag7 = this.SelectedNodes.Count < 1;
					if (!flag7)
					{
						bool @checked = !this.SelectedNodes[0].Checked;
						foreach (TreeNode current in this.SelectedNodes)
						{
							current.Checked = @checked;
						}
					}
				}
			}
		}
		private void TvViewSheets_ItemDrag(object sender, ItemDragEventArgs e)
		{
			base.DoDragDrop(e.Item, DragDropEffects.Move);
		}
		private void TvViewSheets_DragEnter(object sender, DragEventArgs e)
		{
			e.Effect = DragDropEffects.Move;
		}
		private void TvViewSheets_DragDrop(object sender, DragEventArgs e)
		{
			base.TreeViewNodeSorter = null;
			base.Sorted = false;
			System.Drawing.Point pt = base.PointToClient(new System.Drawing.Point(e.X, e.Y));
			TreeNode treeNode = e.Data.GetData(typeof(TreeNode)) as TreeNode;
			bool flag = treeNode == null;
			if (!flag)
			{
				TreeNode nodeAt = base.GetNodeAt(pt);
				bool flag2 = nodeAt == null;
				if (!flag2)
				{
					bool flag3 = nodeAt == treeNode.Parent;
					if (flag3)
					{
						treeNode.Remove();
						nodeAt.Nodes.Insert(0, treeNode);
						base.SelectedNode = nodeAt.Nodes[0];
					}
					bool flag4 = nodeAt.Parent != treeNode.Parent || treeNode.Equals(nodeAt);
					if (!flag4)
					{
						treeNode.Remove();
						bool flag5 = nodeAt.Index == treeNode.Index - 1;
						if (flag5)
						{
							nodeAt.Parent.Nodes.Insert(nodeAt.Index, treeNode);
						}
						else
						{
							nodeAt.Parent.Nodes.Insert(nodeAt.Index + 1, treeNode);
						}
						base.SelectedNode = treeNode;
					}
				}
			}
		}
		public void MoveSelectedNode(bool isMoveUp)
		{
			bool flag = base.SelectedNode == null;
			if (!flag)
			{
				this.ClearSelectedNodes();
				base.TreeViewNodeSorter = null;
				base.Sorted = false;
				TreeNode selectedNode = base.SelectedNode;
				base.BeginUpdate();
				if (isMoveUp)
				{
					selectedNode.MoveUp();
				}
				else
				{
					selectedNode.MoveDown();
				}
				base.SelectedNode = selectedNode;
				base.EndUpdate();
				base.Focus();
				Debug.Print(string.Format("\r\nnode: {0} index {1}", selectedNode.Text, selectedNode.Index));
			}
		}
		private void ToggleNode(TreeNode node, bool bSelectNode)
		{
			if (bSelectNode)
			{
				base.SelectedNode = node;
				bool flag = !this.SelectedNodes.Contains(node);
				if (flag)
				{
					this.SelectedNodes.Add(node);
				}
				node.BackColor = SystemColors.Highlight;
				node.ForeColor = SystemColors.HighlightText;
			}
			else
			{
				this.SelectedNodes.Remove(node);
				node.BackColor = this.BackColor;
				node.ForeColor = this.ForeColor;
			}
		}
		private void HandleException(Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
		private void ClearSelectedNodes()
		{
			try
			{
				foreach (TreeNode current in this.SelectedNodes)
				{
					current.BackColor = this.BackColor;
					current.ForeColor = this.ForeColor;
				}
			}
			finally
			{
				this.SelectedNodes.Clear();
			}
		}
		private void InitializeComponent()
		{
			this.treeView1 = new TreeView();
			base.SuspendLayout();
			this.treeView1.LineColor = System.Drawing.Color.Empty;
			this.treeView1.Location = new System.Drawing.Point(0, 0);
			this.treeView1.Name = "treeView1";
			this.treeView1.Size = new Size(121, 97);
			this.treeView1.TabIndex = 0;
			this.treeView1.AfterSelect += new TreeViewEventHandler(this.treeView1_AfterSelect);
			base.ResumeLayout(false);
		}
		private void treeView1_AfterSelect(object sender, TreeViewEventArgs e)
		{
		}
	}
	internal class SurfaceExport2dContext : IExportContext2D, IExportContextBase, IExportContext
	{
		public List<Tuple<ElementId, List<IList<XYZ>>>> Result;
		private ElementId _currId;
		private List<IList<XYZ>> _segments;
		private readonly Type _t;
		public SurfaceExport2dContext(Type t)
		{
			this.Result = new List<Tuple<ElementId, List<IList<XYZ>>>>();
			this._currId = ElementId.InvalidElementId;
			this._t = t;
		}
		public void Finish()
		{
		}
		public bool IsCanceled()
		{
			return false;
		}
		public RenderNodeAction OnCurve(CurveNode node)
		{
			return RenderNodeAction.Proceed;
		}
		public RenderNodeAction OnElementBegin(ElementId elementId)
		{
			return RenderNodeAction.Proceed;
		}
		public RenderNodeAction OnElementBegin2D(ElementNode node)
		{
			Element element = node.Document.GetElement(node.ElementId);
			bool flag = element.GetType() == this._t;
			RenderNodeAction result;
			if (flag)
			{
				this._currId = node.ElementId;
				this._segments = new List<IList<XYZ>>();
				result = RenderNodeAction.Proceed;
			}
			else
			{
				result = RenderNodeAction.Skip;
			}
			return result;
		}
		public void OnElementEnd(ElementId elementId)
		{
		}
		public void OnElementEnd2D(ElementNode node)
		{
			bool flag = this._currId != ElementId.InvalidElementId && this._segments.Any<IList<XYZ>>();
			if (flag)
			{
				List<IList<XYZ>> list = new List<IList<XYZ>>();
				list.AddRange(this._segments);
				Tuple<ElementId, List<IList<XYZ>>> tuple = this.Result.Find((Tuple<ElementId, List<IList<XYZ>>> t) => object.Equals(t.Item1, this._currId));
				bool flag2 = tuple != null;
				if (flag2)
				{
					tuple.Item2.AddRange(list);
				}
				else
				{
					tuple = new Tuple<ElementId, List<IList<XYZ>>>(this._currId, list);
					this.Result.Add(tuple);
				}
				this._currId = ElementId.InvalidElementId;
				this._segments.Clear();
			}
		}
