	internal class ComboboxExt_Filter
	{
		private readonly System.Windows.Forms.ComboBox _cmb;
		private readonly List<ItemComment> _allItems;
		public ComboboxExt_Filter(System.Windows.Forms.ComboBox cmb, List<ItemComment> allItems)
		{
			this._cmb = cmb;
			this._allItems = new List<ItemComment>();
			this._allItems.AddRange(allItems);
			this._cmb.DropDownStyle = ComboBoxStyle.DropDown;
			this._cmb.DataSource = this._allItems;
			this._cmb.ValueMember = "Item";
			this._cmb.DisplayMember = "Comment";
			this._cmb.TextUpdate += new EventHandler(this.cmb_TextUpdate);
			this._cmb.SelectedIndex = -1;
		}
		private void cmb_TextUpdate(object sender, EventArgs e)
		{
			bool flag = this._cmb.Text == string.Empty;
			if (flag)
			{
				this._cmb.DataSource = this._allItems;
				this._cmb.ValueMember = "Item";
				this._cmb.DisplayMember = "Comment";
				this._cmb.SelectedIndex = -1;
			}
			else
			{
				string text = this._cmb.Text;
				bool flag2 = this._allItems != null;
				if (flag2)
				{
					List<ItemComment> dataSource = (
						from x in this._allItems
						where x.Comment.Contains(text, StringComparison.OrdinalIgnoreCase)
						select x).ToList<ItemComment>();
					this._cmb.DataSource = dataSource;
					this._cmb.ValueMember = "Item";
					this._cmb.DisplayMember = "Comment";
				}
				this._cmb.DroppedDown = true;
				Cursor.Current = Cursors.Default;
				this._cmb.SelectedIndex = -1;
				this._cmb.Text = text;
				this._cmb.Select(this._cmb.Text.Length, 0);
			}
		}
	}
	public class CheckboxColumn
	{
		private readonly CheckBox _chkCommon;
		private readonly DataGridView _dgv;
		private readonly System.Windows.Forms.Control _chkContainer;
		private readonly Label _lblTotal;
		private readonly int _shiftX = 0;
		private readonly int _size = 16;
		public DataGridViewCheckBoxColumn Column
		{
			get;
			set;
		}
		public int SelectedCount
		{
			get;
			private set;
		}
		public CheckboxColumn(DataGridView dgv, System.Windows.Forms.Control chkContainer, int colIndex, Label lblTotal, bool commonFirstChecked = false, int shiftX = 7)
		{
			bool flag = dgv == null || chkContainer == null;
			if (!flag)
			{
				this._dgv = dgv;
				this._chkContainer = chkContainer;
				this._lblTotal = lblTotal;
				this._shiftX = shiftX;
				this.Column = new DataGridViewCheckBoxColumn
				{
					Frozen = true,
					HeaderText = "",
					MinimumWidth = 6,
					Name = "colEnable",
					Width = 25
				};
				this._dgv.Columns.Insert(colIndex, this.Column);
				this._chkCommon = new CheckBox();
				this.CalcLocation();
				this._chkCommon.Width = this._size;
				this._chkCommon.Height = this._size;
				this._chkCommon.Checked = commonFirstChecked;
				chkContainer.Controls.Add(this._chkCommon);
				this._chkCommon.BringToFront();
				this._chkCommon.CheckedChanged += new EventHandler(this.chk_CheckedChanged);
				this._dgv.ColumnWidthChanged += new DataGridViewColumnEventHandler(this.ColumnWidthChanged);
				this._dgv.CurrentCellDirtyStateChanged += new EventHandler(this.dgv_CurrentCellDirtyStateChanged);
			}
		}
		private void CalcLocation()
		{
			int num = 0;
			for (int i = 0; i < this.Column.Index; i++)
			{
				DataGridViewColumn dataGridViewColumn = this._dgv.Columns[i];
				bool visible = dataGridViewColumn.Visible;
				if (visible)
				{
					num += dataGridViewColumn.Width;
				}
			}
			bool rowHeadersVisible = this._dgv.RowHeadersVisible;
			if (rowHeadersVisible)
			{
				num += this._dgv.RowHeadersWidth;
			}
			System.Windows.Forms.Control control = this._dgv;
			string name = this._dgv.FindForm().Name;
			int num2 = 0;
			int num3 = 0;
			while (control.Name != this._chkContainer.Name && control.Name != name)
			{
				num2 += control.Location.X;
				num3 += control.Location.Y;
				control = control.Parent;
			}
			int x = num2 + num + this._shiftX;
			int y = num3 + (this._dgv.ColumnHeadersHeight - this._size) / 2 + 1;
			this._chkCommon.Location = new System.Drawing.Point(x, y);
		}
		private void chk_CheckedChanged(object sender, EventArgs e)
		{
			this.SelectAll(this._chkCommon.Checked);
		}
		private void ColumnWidthChanged(object sender, DataGridViewColumnEventArgs e)
		{
			this.CalcLocation();
		}
		public void SelectAll(bool value)
		{
			this.SelectedCount = 0;
			foreach (DataGridViewRow dataGridViewRow in (IEnumerable)this._dgv.Rows)
			{
				DataGridViewCheckBoxCell dataGridViewCheckBoxCell = dataGridViewRow.Cells[this.Column.Index] as DataGridViewCheckBoxCell;
				bool flag = dataGridViewCheckBoxCell != null && !dataGridViewCheckBoxCell.ReadOnly;
				if (flag)
				{
					dataGridViewCheckBoxCell.Value = value;
					if (value)
					{
						int selectedCount = this.SelectedCount;
						this.SelectedCount = selectedCount + 1;
					}
				}
			}
			this.ShowTotal();
		}
		public void CalcTotal()
		{
			this.SelectedCount = 0;
			foreach (DataGridViewRow dataGridViewRow in (IEnumerable)this._dgv.Rows)
			{
				DataGridViewCheckBoxCell dataGridViewCheckBoxCell = dataGridViewRow.Cells[this.Column.Index] as DataGridViewCheckBoxCell;
				bool flag = dataGridViewCheckBoxCell.Value != null && (bool)dataGridViewCheckBoxCell.Value;
				if (flag)
				{
					int selectedCount = this.SelectedCount;
					this.SelectedCount = selectedCount + 1;
				}
			}
			this.ShowTotal();
		}
		public void ShowTotal()
		{
			bool flag = this._lblTotal != null;
			if (flag)
			{
				this._lblTotal.Text = string.Format("Всего: {0}", this.SelectedCount);
			}
		}
		private void dgv_CurrentCellDirtyStateChanged(object sender, EventArgs e)
		{
			bool isCurrentCellDirty = this._dgv.IsCurrentCellDirty;
			if (isCurrentCellDirty)
			{
				DataGridView dataGridView = (DataGridView)sender;
				int index = dataGridView.CurrentRow.Index;
				DataGridViewCheckBoxCell dataGridViewCheckBoxCell = dataGridView.Rows[index].Cells[this.Column.Index] as DataGridViewCheckBoxCell;
				bool flag = dataGridViewCheckBoxCell.Value != null;
				if (flag)
				{
					bool flag2 = (bool)dataGridViewCheckBoxCell.Value;
					if (flag2)
					{
						bool flag3 = this.SelectedCount > 0;
						if (flag3)
						{
							int selectedCount = this.SelectedCount;
							this.SelectedCount = selectedCount - 1;
						}
					}
					else
					{
						int selectedCount = this.SelectedCount;
						this.SelectedCount = selectedCount + 1;
					}
					this.ShowTotal();
				}
				this._dgv.CommitEdit(DataGridViewDataErrorContexts.Commit);
			}
		}
	}
