	public static class TreeViewExtensions
	{
		public static List<TreeNode> GetAllNodes(this TreeView tvw)
		{
			List<TreeNode> list = new List<TreeNode>();
			foreach (TreeNode node in tvw.Nodes)
			{
				list.AddRange(node.GetAllNodes());
			}
			return list;
		}
		public static List<TreeNode> GetAllNodes(this TreeNode node)
		{
			List<TreeNode> list = new List<TreeNode>
			{
				node
			};
			foreach (TreeNode node2 in node.Nodes)
			{
				list.AddRange(node2.GetAllNodes());
			}
			return list;
		}
		public static void MoveUp(this TreeNode node)
		{
			bool flag = node == null;
			if (!flag)
			{
				TreeNode parent = node.Parent;
				TreeView treeView = node.TreeView;
				bool flag2 = parent != null;
				if (flag2)
				{
					int index = node.Index;
					bool flag3 = index > 0;
					if (flag3)
					{
						parent.Nodes.RemoveAt(index);
						parent.Nodes.Insert(index - 1, node);
					}
				}
				else
				{
					bool flag4 = node.TreeView.Nodes.Contains(node);
					if (flag4)
					{
