		private XYZ GetCurveNormal(Curve curve)
		{
			IList<XYZ> list = curve.Tessellate();
			int count = list.Count;
			Debug.Assert(1 < count, "должно быть не менее двух точек тесселяции кривой");
			XYZ right = list[0];
			XYZ left = list[count - 1];
			XYZ xYZ = left - right;
			XYZ xYZ2 = null;
			bool flag = 2 == count;
			if (flag)
			{
				Debug.Assert(curve is Line, "в нелинейном элементе должно быть больше двух точек тесселяции");
				double num = Math.Abs(xYZ.X) + Math.Abs(xYZ.Y);
				XYZ source = (num > RUtil.TolPointOnPlane) ? XYZ.BasisZ : XYZ.BasisY;
				xYZ2 = xYZ.CrossProduct(source).Normalize();
			}
			else
			{
				int num2 = 0;
				while (++num2 < count - 1)
				{
					XYZ source = list[num2] - right;
					xYZ2 = xYZ.CrossProduct(source);
					bool flag2 = !xYZ2.IsZeroLength();
					if (flag2)
					{
						xYZ2 = xYZ2.Normalize();
						break;
					}
				}
				while (++num2 < count - 1)
				{
					XYZ source = list[num2] - right;
					XYZ xYZ3 = xYZ.CrossProduct(source);
					Debug.Assert(xYZ3.IsZeroLength() || xYZ3.AngleTo(xYZ2).IsZero(), "все точки кривой должны лежать в одной плоскости");
				}
			}
			return xYZ2;
		}
		public ModelLine CreateModelLine(XYZ p, XYZ q, double tolerance = 0.00256026455729167)
		{
			bool flag = p == null || q == null;
			ModelLine result;
			if (flag)
			{
				result = null;
			}
			else
			{
				bool flag2 = p.DistanceTo(q) < tolerance;
				if (flag2)
				{
					result = null;
				}
				else
				{
					XYZ xYZ = q - p;
					double num = Math.Abs(xYZ.X) + Math.Abs(xYZ.Y);
					XYZ source = (num > RUtil.TolPointOnPlane) ? XYZ.BasisZ : XYZ.BasisY;
					XYZ normal = xYZ.CrossProduct(source).Normalize();
					Plane plane = Plane.CreateByNormalAndOrigin(normal, p);
					SketchPlane sketchPlane = SketchPlane.Create(this.Doc, plane);
					Line geometryCurve = Line.CreateBound(p, q);
					ModelCurve modelCurve = this.Doc.IsFamilyDocument ? this.Doc.FamilyCreate.NewModelCurve(geometryCurve, sketchPlane) : this.Doc.Create.NewModelCurve(geometryCurve, sketchPlane);
					result = (modelCurve as ModelLine);
				}
			}
			return result;
		}
