		}
		private SketchPlane NewSketchPlanePassLine(Line line)
		{
			XYZ endPoint = line.GetEndPoint(0);
			XYZ endPoint2 = line.GetEndPoint(1);
			bool flag = endPoint.X == endPoint2.X;
			XYZ normal;
			if (flag)
			{
				normal = XYZ.BasisX;
			}
			else
			{
				bool flag2 = endPoint.Y == endPoint2.Y;
				if (flag2)
				{
					normal = XYZ.BasisY;
				}
				else
				{
					normal = XYZ.BasisZ;
				}
			}
			Plane plane = Plane.CreateByNormalAndOrigin(normal, endPoint);
			return SketchPlane.Create(this.Doc, plane);
		}
		private SketchPlane NewSketchPlaneContainCurve(Curve curve)
		{
			XYZ endPoint = curve.GetEndPoint(0);
			XYZ curveNormal = this.GetCurveNormal(curve);
			Plane plane = Plane.CreateByNormalAndOrigin(curveNormal, endPoint);
			bool flag = !(curve is Line);
			if (flag)
			{
				List<Curve> curves = new List<Curve>(1)
				{
					curve
				};
				CurveLoop curveLoop = CurveLoop.Create(curves);
				Plane plane2 = curveLoop.GetPlane();
				Debug.Assert(plane2.Normal.IsParallel(plane.Normal), "expected equal planes");
				Debug.Assert(plane2.SignedDistanceTo(plane.Origin).IsZero(), "expected equal planes");
			}
			return SketchPlane.Create(this.Doc, plane);
		}
