					{
						XYZ center2 = ellipse.Center;
						XYZ normal2 = ellipse.Normal;
						modelCurveArray.Append(this.CreateModelCurve(ellipse, center2, normal2));
						result = modelCurveArray;
					}
					else
					{
						IList<XYZ> source = curve.Tessellate();
						XYZ p = source.First<XYZ>();
						foreach (XYZ current in source.Skip(1))
						{
							modelCurveArray.Append(this.CreateModelLine(p, current, 0.00256026455729167));
							p = current;
						}
						result = modelCurveArray;
					}
				}
			}
			return result;
		}
