		public List<ModelCurve> DrawCurveLoop(CurveLoop loop)
		{
			List<ModelCurve> list = new List<ModelCurve>();
			CurveLoopIterator curveLoopIterator = loop.GetCurveLoopIterator();
			curveLoopIterator.Reset();
			while (curveLoopIterator.MoveNext())
			{
				Curve current = curveLoopIterator.Current;
				ModelCurveArray modelCurveArray = this.DrawCurve(current);
				foreach (ModelCurve item in modelCurveArray)
