		public void DrawFaceTriangleNormals(Face f)
		{
			Mesh mesh = f.Triangulate();
			int numTriangles = mesh.NumTriangles;
			Debug.Print("Треугольники сетки и вектора нормалей от {0} триангуляций грани:", new object[]
			{
				numTriangles
			});
			for (int i = 0; i < numTriangles; i++)
			{
				MeshTriangle meshTriangle = mesh.get_Triangle(i);
				XYZ xYZ = (meshTriangle.get_Vertex(0) + meshTriangle.get_Vertex(1) + meshTriangle.get_Vertex(2)) / 3.0;
				XYZ xYZ2 = meshTriangle.get_Vertex(1) - meshTriangle.get_Vertex(0);
				XYZ source = meshTriangle.get_Vertex(2) - meshTriangle.get_Vertex(0);
				XYZ xYZ3 = xYZ2.CrossProduct(source).Normalize();
				Debug.Print("{0} {1} --> {2}", new object[]
				{
					i,
					xYZ.Description(),
					xYZ3.Description()
				});
				this.CreateModelLine(xYZ, xYZ + xYZ3, 0.00256026455729167);
			}
		}
