		public TextNote PlanarFaceMarker2D(PlanarFace pf, TextNoteType textType, string msg)
		{
			Autodesk.Revit.DB.View activeView = this.Doc.ActiveView;
			Curve curve = null;
			double num = 0.0;
			foreach (CurveLoop current in pf.GetEdgesAsCurveLoops())
			{
				foreach (Curve current2 in current)
				{
					XYZ endPoint = current2.GetEndPoint(0);
					XYZ endPoint2 = current2.GetEndPoint(1);
					bool flag = (endPoint - endPoint2).IsPerpendicular(activeView.ViewDirection);
					if (flag)
					{
						double num2 = endPoint.DistanceTo(endPoint2);
						bool flag2 = curve == null || num2 > num;
						if (flag2)
						{
							curve = current2;
							num = num2;
						}
					}
				}
			}
			bool flag3 = curve == null;
			TextNote result;
			if (flag3)
			{
				Debug.Print("Не удалось найти верхнее ребро плоской поверхности");
				result = null;
			}
			else
			{
				double radius = 0.1;
				XYZ endPoint3 = curve.GetEndPoint(0);
				XYZ endPoint4 = curve.GetEndPoint(1);
				bool flag4 = pf.Area > 0.1;
				if (flag4)
				{
					this.CurveEndsMarker(curve, radius);
				}
				else
				{
					this.PointMarker_Circle2D((endPoint3 + endPoint4) / 2.0, endPoint3.DistanceTo(endPoint4));
				}
				XYZ position = pf.EdgeLoops.get_Item(0).Middle();
				XYZ xYZ = curve.GetEndPoint(0) - curve.GetEndPoint(1);
				double num3 = xYZ.AngleTo(activeView.RightDirection);
				bool flag5 = num3 > 1.5707963267948966;
				if (flag5)
				{
					num3 = 3.1415926535897931 - num3;
				}
				bool flag6 = (xYZ.Y > 0.0 && xYZ.X < 0.0) || (xYZ.Y < 0.0 && xYZ.X > 0.0);
				if (flag6)
				{
					num3 = -num3;
				}
				TextNoteOptions options = new TextNoteOptions(textType.Id)
				{
					KeepRotatedTextReadable = true,
					Rotation = num3
				};
				TextNote textNote = TextNote.Create(this.Doc, activeView.Id, position, msg, options);
				result = textNote;
			}
			return result;
		}
