		public List<DetailArc> CurveEndsMarker(Curve curve, double radius = 0.1)
		{
			XYZ endPoint = curve.GetEndPoint(0);
			XYZ endPoint2 = curve.GetEndPoint(1);
			XYZ xYZ = (endPoint2 - endPoint).Normalize() * radius;
			XYZ xYZ2 = xYZ.Normalize();
			XYZ yAxis = xYZ2.CrossProduct(this.Doc.ActiveView.ViewDirection);
			Arc geometryCurve = Arc.Create(endPoint + xYZ, radius, 2.0943951023931953, 4.1887902047863905, xYZ2, yAxis);
			DetailArc item = this.Doc.Create.NewDetailCurve(this.Doc.ActiveView, geometryCurve) as DetailArc;
			Arc geometryCurve2 = Arc.Create(endPoint2 - xYZ, radius, 2.0943951023931953, 4.1887902047863905, -xYZ2, yAxis);
			DetailArc item2 = this.Doc.Create.NewDetailCurve(this.Doc.ActiveView, geometryCurve2) as DetailArc;
			return new List<DetailArc>
			{
				item,
				item2
			};
		}
