		public List<ModelLine> PointMarker_Cross(XYZ point, double size = 0.2)
		{
			List<ModelLine> list = new List<ModelLine>();
			XYZ rightDirection = this.Doc.ActiveView.RightDirection;
			XYZ xYZ = rightDirection.CrossProduct(this.Doc.ActiveView.ViewDirection);
			XYZ p = point + rightDirection.Multiply(size) + xYZ.Multiply(size);
			XYZ q = point - rightDirection.Multiply(size) - xYZ.Multiply(size);
			XYZ p2 = point + rightDirection.Multiply(size) - xYZ.Multiply(size);
			XYZ q2 = point - rightDirection.Multiply(size) + xYZ.Multiply(size);
			list.Add(this.CreateModelLine(p, q, 0.00256026455729167));
			list.Add(this.CreateModelLine(p2, q2, 0.00256026455729167));
			return list;
		}
		public FilledRegion PointMarker_CircleFilled(XYZ point, FilledRegionType frt, double radius = 0.1)
		{
			bool flag = this.Doc == null || frt == null || point == null;
			FilledRegion result;
			if (flag)
			{
				result = null;
			}
			else
			{
				Autodesk.Revit.DB.View activeView = this.Doc.ActiveView;
				XYZ rightDirection = activeView.RightDirection;
				XYZ xYZ = rightDirection.CrossProduct(activeView.ViewDirection);
				Arc arc = Arc.Create(point, radius, 0.0, 3.1415926535897931, rightDirection, xYZ);
				XYZ endPoint = arc.GetEndPoint(0);
				XYZ endPoint2 = arc.GetEndPoint(1);
				Arc curve = Arc.Create(endPoint2, endPoint, point.Add(-xYZ.Multiply(radius)));
				List<CurveLoop> list = new List<CurveLoop>();
				CurveLoop curveLoop = new CurveLoop();
				curveLoop.Append(arc);
				curveLoop.Append(curve);
				list.Add(curveLoop);
				result = FilledRegion.Create(this.Doc, frt.Id, activeView.Id, list);
			}
			return result;
		}
