		public FilledRegion PointMarker_TriangleFilled(XYZ point, FilledRegionType frt, double radius = 0.1)
		{
			bool flag = this.Doc == null || frt == null || point == null;
			FilledRegion result;
			if (flag)
			{
				result = null;
			}
			else
			{
				Autodesk.Revit.DB.View activeView = this.Doc.ActiveView;
				XYZ xYZ = point.Add(XYZ.BasisY.Multiply(radius));
				XYZ xYZ2 = point.Subtract(new XYZ(1.0, 1.0, 0.0).Multiply(radius));
				XYZ xYZ3 = point.Add(new XYZ(1.0, -1.0, 0.0).Multiply(radius));
				Line curve = Line.CreateBound(xYZ, xYZ2);
				Line curve2 = Line.CreateBound(xYZ2, xYZ3);
				Line curve3 = Line.CreateBound(xYZ3, xYZ);
				List<CurveLoop> list = new List<CurveLoop>();
				CurveLoop curveLoop = new CurveLoop();
				curveLoop.Append(curve);
				curveLoop.Append(curve2);
				curveLoop.Append(curve3);
				list.Add(curveLoop);
				result = FilledRegion.Create(this.Doc, frt.Id, activeView.Id, list);
			}
