		public static Solid CreateSphere(XYZ center, double radius)
		{
			Frame coordinateFrame = new Frame(center, XYZ.BasisX, XYZ.BasisY, XYZ.BasisZ);
			List<CurveLoop> list = new List<CurveLoop>();
			CurveLoop curveLoop = new CurveLoop();
			Curve curve = Ellipse.CreateCurve(center, radius, radius, XYZ.BasisX, XYZ.BasisZ, -1.5707963267948966, 1.5707963267948966);
			curveLoop.Append(curve);
			curveLoop.Append(Line.CreateBound(new XYZ(center.X, center.Y, center.Z + radius), new XYZ(center.X, center.Y, center.Z - radius)));
			list.Add(curveLoop);
			return GeometryCreationUtilities.CreateRevolvedGeometry(coordinateFrame, list, -3.1415926535897931, 3.1415926535897931);
		}
	}
	public class WarningSwallower : IFailuresPreprocessor
	{
		private readonly FailureDefinitionId Id;
		public WarningSwallower(FailureDefinitionId ID)
		{
			this.Id = ID;
		}
		public FailureProcessingResult PreprocessFailures(FailuresAccessor a)
		{
			IList<FailureMessageAccessor> failureMessages = a.GetFailureMessages();
			foreach (FailureMessageAccessor current in failureMessages)
			{
				FailureDefinitionId failureDefinitionId = current.GetFailureDefinitionId();
				bool flag = this.Id == failureDefinitionId;
				if (flag)
				{
					a.DeleteWarning(current);
				}
			}
			return FailureProcessingResult.Continue;
		}
	}
