	public static class Helper
	{
		private static System.Windows.Forms.Form form;
		private static RichTextBox textBox;
		private static string tmpPath;
		public static void ShowForm()
		{
			Helper.form = new System.Windows.Forms.Form();
			Helper.InitForm();
			Helper.form.Show();
		}
		private static void InitForm()
		{
			Helper.form.Text = "Справка";
			Helper.form.Size = new Size(1100, 660);
			Helper.form.Resize += new EventHandler(Helper.ReadmeFormResize);
			int x = Screen.PrimaryScreen.Bounds.Left + 50;
			int y = Screen.PrimaryScreen.Bounds.Top + 50;
			Helper.form.Location = new System.Drawing.Point(x, y);
			Helper.textBox = new RichTextBox
			{
				Size = new Size(Helper.form.Width, Helper.form.Height - 40),
				Location = new System.Drawing.Point(0, 0),
				ShowSelectionMargin = false,
				ScrollBars = RichTextBoxScrollBars.Both,
				Text = Helper.GetProjInfo() + Resources.readme,
				ReadOnly = true
			};
			Helper.form.Controls.Add(Helper.textBox);
			Helper.textBox.Show();
		}
		private static void ReadmeFormResize(object sender, EventArgs e)
		{
			Helper.textBox.Height = Helper.form.Height - 40;
			Helper.textBox.Width = Helper.form.Width - 15;
			Helper.textBox.Update();
			Helper.textBox.Refresh();
		}
		public static void SaveAsTemp()
		{
			Helper.tmpPath = Path.GetTempFileName();
			Helper.SaveFile(Helper.tmpPath);
		}
		public static void SaveAsLocal()
		{
			string path = Directory.GetCurrentDirectory() + "\\readme.txt";
			Helper.SaveFile(path);
		}
		public static void OpenTempInNotepad()
		{
			bool flag = Helper.tmpPath != null;
			if (flag)
			{
				Process.Start("notepad.exe", Helper.tmpPath);
			}
		}
		private static string GetProjInfo()
		{
			Assembly executingAssembly = Assembly.GetExecutingAssembly();
			Version version = executingAssembly.GetName().Version;
			string name = executingAssembly.GetName().Name;
			return name + " \r\nВерсия " + version.ToString() + " beta.\r\n";
		}
		private static void SaveFile(string path)
		{
			bool flag = path == null || path == "";
			if (!flag)
			{
				byte[] bytes = Encoding.Default.GetBytes(Helper.GetProjInfo() + Resources.readme);
				MemoryStream memoryStream = new MemoryStream(bytes);
				try
				{
					FileStream fileStream = new FileStream(path, FileMode.OpenOrCreate);
					memoryStream.WriteTo(fileStream);
					fileStream.Close();
					memoryStream.Close();
				}
				catch (Exception ex)
				{
					Log.Write("Не удалось изменить файл " + path);
					Log.Write(ex);
				}
			}
		}
	}
	public static class Log
	{
		public static string PathToLog = "";
		public static string Filename = "";
		private static readonly object _sync = new object();
		private static string assemblyName;
		private static string assemblyFolder;
		public static void Write(Exception ex)
		{
			try
			{
				Log.Preparation();
				string contents = string.Format("[{0:dd.MM.yyy HH:mm:ss.fff}] [{1}.{2}()] {3} \r\n\t\t\tStackTrace:{4}\r\n\t\t\tInnerException:{5}\r\n", new object[]
