				object sync = Log._sync;
				lock (sync)
				{
					File.AppendAllText(Log.Filename, contents, Encoding.UTF8);
				}
			}
			catch
			{
			}
		}
		public static void Create()
		{
			Log.Preparation();
			File.AppendAllText(Log.Filename, "", Encoding.UTF8);
		}
		private static void Preparation()
		{
			Log.GetAssemblyProperties();
			Log.PathToLog = Log.assemblyFolder + "\\Log";
			bool flag = !Directory.Exists(Log.PathToLog);
			if (flag)
			{
				Directory.CreateDirectory(Log.PathToLog);
			}
			Log.Filename = Path.Combine(Log.PathToLog, string.Format("{0}_{1:dd.MM.yyy}.log", Log.assemblyName, DateTime.Now));
		}
		private static void Preparation(string anotherFolderPath)
		{
			Log.GetAssemblyProperties();
			Log.PathToLog = anotherFolderPath + "\\Log";
			bool flag = !Directory.Exists(Log.PathToLog);
			if (flag)
			{
				Directory.CreateDirectory(Log.PathToLog);
			}
			Log.Filename = Path.Combine(Log.PathToLog, string.Format("{0}_{1:dd.MM.yyy}.log", Log.assemblyName, DateTime.Now));
		}
		private static void GetAssemblyProperties()
		{
			Assembly executingAssembly = Assembly.GetExecutingAssembly();
			Log.assemblyFolder = Path.GetDirectoryName(executingAssembly.Location);
			Log.assemblyName = executingAssembly.GetName().Name;
		}
		public static void Delete(int iDays)
		{
			try
			{
				Log.Preparation();
				bool flag = Log.assemblyName == null;
				if (!flag)
				{
					object sync = Log._sync;
					lock (sync)
					{
						DateTime today = DateTime.Today;
						DirectoryInfo directoryInfo = new DirectoryInfo(Log.PathToLog);
						foreach (FileInfo current in directoryInfo.EnumerateFiles())
						{
							bool flag3 = current.Name.Length == Log.assemblyName.Length + 15 && current.Name.Substring(0, Log.assemblyName.Length) == Log.assemblyName;
							if (flag3)
							{
								string text = Path.GetFileNameWithoutExtension(current.Name);
								text = text.Substring(text.Length - 10);
								DateTime d;
								bool flag4 = DateTime.TryParseExact(text, "dd.MM.yyyy", null, DateTimeStyles.AssumeLocal, out d) && (today - d).Days > iDays;
								if (flag4)
								{
									current.Delete();
								}
							}
						}
					}
				}
			}
			catch
			{
			}
		}
	}
