				if (flag3)
				{
					result = false;
				}
				else
				{
					Autodesk.Revit.DB.Parameter parameter = (
						from par in element.Parameters.OfType<Autodesk.Revit.DB.Parameter>()
						where par.Id.GetValueLong() == rpd.ID
						select par).FirstOrDefault<Autodesk.Revit.DB.Parameter>();
					bool flag4 = parameter == null;
					if (flag4)
					{
						result = false;
					}
					else
					{
						st = parameter.StorageType;
						result = true;
					}
				}
			}
			return result;
		}
		public static StorageType GetStorageTypeByTempBinding(Autodesk.Revit.DB.Document doc, RevitParameterData rpd)
		{
			Element element = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_ProjectInformation).FirstElement();
			Element element2 = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Walls).WhereElementIsElementType().FirstElement();
			Autodesk.Revit.DB.Parameter parameter = null;
			CategorySet categorySet = new CategorySet();
			StorageType storageType = StorageType.None;
			bool flag = rpd.Def == null;
			StorageType result;
			if (flag)
			{
				result = storageType;
			}
			else
			{
				bool flag2 = rpd.Binding != null;
				if (flag2)
				{
					categorySet = rpd.Binding.Categories;
				}
				bool flag3 = categorySet.Contains(element.Category);
				if (flag3)
				{
					parameter = element.get_Parameter(rpd.Def);
					bool flag4 = parameter != null;
					if (flag4)
					{
						storageType = parameter.StorageType;
					}
					result = storageType;
				}
				else
				{
					using (Transaction transaction = new Transaction(doc, "Temporary"))
					{
						transaction.Start();
						string text;
						bool flag5 = rpd.AddBinding(doc, element.Category, out text);
						bool flag6 = flag5;
						if (flag6)
						{
							bool flag7 = !rpd.IsDefinitionValid();
							if (flag7)
							{
								rpd.Def = RUtil.GetDefinitionByName(doc, rpd.Name);
							}
							parameter = element.get_Parameter(rpd.Def);
							bool flag8 = parameter == null;
							if (flag8)
							{
								bool flag9 = !categorySet.Contains(element2.Category);
								if (flag9)
								{
									bool flag10 = rpd.AddBinding(doc, element2.Category, out text);
									if (flag10)
									{
										parameter = element2.get_Parameter(rpd.Def);
									}
								}
								else
								{
									parameter = element2.get_Parameter(rpd.Def);
								}
							}
							bool flag11 = parameter != null;
							if (flag11)
							{
								storageType = parameter.StorageType;
							}
						}
						else
						{
							bool flag12 = parameter != null;
							if (flag12)
							{
								storageType = parameter.StorageType;
							}
						}
						transaction.RollBack();
					}
					rpd.ReloadBinding(doc);
					result = storageType;
				}
			}
			return result;
		}
		public static ParamId GetParamData(Autodesk.Revit.DB.Parameter p)
		{
			BuiltInParameter builtInParameter = (p.Definition as InternalDefinition).BuiltInParameter;
			bool flag = builtInParameter != BuiltInParameter.INVALID;
			ParamId paramId;
			ParamId result;
			if (flag)
			{
				paramId = new ParamId(builtInParameter)
				{
					Comment = string.Format("встроенный: {0} {1}", (int)builtInParameter, builtInParameter)
				};
				bool flag2 = paramId.Name == "";
				if (flag2)
				{
					result = null;
					return result;
				}
			}
			else
			{
				bool isShared = p.IsShared;
				if (isShared)
				{
					paramId = new ParamId(p.GUID, p.Definition.Name)
					{
						Comment = "общий GUID: " + p.GUID.ToString()
					};
				}
				else
				{
					paramId = new ParamId(p.Definition.Name)
					{
						Comment = "параметр проекта"
					};
				}
			}
			result = paramId;
			return result;
		}
