		public static double ToleranceAngular2Linear(double angularTol)
		{
			XYZ xYZ = new XYZ(1.0, 0.0, 0.0);
			XYZ source = new XYZ(Math.Cos(angularTol), Math.Sin(angularTol), 0.0);
			XYZ xYZ2 = xYZ.CrossProduct(source);
			return Math.Max(Math.Abs(xYZ2.X), Math.Max(Math.Abs(xYZ2.Y), Math.Abs(xYZ2.Z)));
		}
