		public static string ElementsDescription(IEnumerable<Element> elems, int lineCount = 1)
		{
			if (elems == null || !elems.Any<Element>())
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder();
			var grouped = elems.GroupBy(e => e.Category?.Name ?? "Р‘РµР· РєР°С‚РµРіРѕСЂРёРё")
							   .Select(g => new { CatName = g.Key, Count = g.Count<Element>() })
							   .OrderByDescending(g => g.Count)
							   .ToList();
			int num = elems.Count<Element>();
			string text = num.ToString();
			if (num == 1)
			{
				text += " СЌР»РµРјРµРЅС‚";
			}
			else if (num < 5)
			{
				text += " СЌР»РµРјРµРЅС‚Р°";
			}
			else
			{
				text += " СЌР»РµРјРµРЅС‚РѕРІ";
			}
			int num2 = grouped.Count;
			string str = (num2 == 1) ? ("РєР°С‚РµРіРѕСЂРёРё '" + grouped[0].CatName + "'.") : string.Format("РёР· {0} РєР°С‚РµРіРѕСЂРёР№:", num2);
			stringBuilder.AppendLine("Р’С‹Р±СЂР°РЅРѕ " + text + " " + str);
			if (num2 == 1)
			{
				return stringBuilder.ToString();
			}
			if (lineCount == 0 || num2 <= lineCount - 1)
			{
				foreach (var current in grouped)
				{
					stringBuilder.AppendLine(string.Format("{0}: {1}", current.CatName, current.Count));
				}
			}
			else
			{
				for (int i = 0; i < lineCount - 2; i++)
				{
					stringBuilder.AppendLine(string.Format("{0}: {1}", grouped[i].CatName, grouped[i].Count));
				}
				stringBuilder.AppendLine("...");
			}
