			List<string> list = new List<string>(size);
			foreach (Autodesk.Revit.DB.Parameter parameter in paramSet)
			{
				list.Add(string.Format("\"{0}\":\"{1}\"", parameter.Definition.Name, parameter.AsValueString()));
