		public static string GetTimeSpan(DateTime timeBegin)
		{
			TimeSpan timeSpan = DateTime.Now - timeBegin;
			string text = string.Format("за {0} сек.", Math.Round(timeSpan.TotalSeconds, 3));
			string text2 = " (";
			bool flag = timeSpan.Hours > 0;
			if (flag)
			{
				text2 += string.Format("{0} ч. ", timeSpan.Hours);
			}
			bool flag2 = timeSpan.Minutes > 0;
			if (flag2)
			{
				text2 += string.Format("{0} мин. ", timeSpan.Minutes);
			}
			bool flag3 = text2 != " (";
			if (flag3)
			{
				text2 += string.Format("{0}.{1} сек.)", timeSpan.Seconds, timeSpan.Milliseconds);
				text += text2;
			}
			return text;
		}
