		public static string GetValueAsString(Autodesk.Revit.DB.Parameter p)
		{
			string result;
			switch (p.StorageType)
			{
			case StorageType.None:
				result = null;
				break;
			case StorageType.Integer:
			{
				bool flag = ParamDataTypeService.IsBoolean(p.Definition);
				if (flag)
				{
					result = p.AsValueString();
				}
				else
				{
					result = p.AsInteger().ToString();
				}
				break;
			}
			case StorageType.Double:
				result = p.AsDouble().ToString(CultureInfo.InvariantCulture);
				break;
			case StorageType.String:
				result = p.AsString();
				break;
			case StorageType.ElementId:
				result = p.AsValueString();
				break;
			default:
				result = null;
				break;
			}
			return result;
		}
		public static bool AddProjectParameterBinding(Autodesk.Revit.DB.Document doc, Autodesk.Revit.DB.Parameter p, Category cat, out string ErrorReport)
		{
			ErrorReport = "";
			bool flag = doc == null;
			bool result = false;
			if (flag)
			{
				ErrorReport = "AddProjectParameterBinding: Переданный документ null.";
				result = false;
			}
			else
			{
				bool isFamilyDocument = doc.IsFamilyDocument;
				if (isFamilyDocument)
				{
					ErrorReport = "AddProjectParameterBinding: Переданный документ '" + doc.Title + "' является семейством.";
					result = false;
				}
				else
				{
					bool flag2 = p == null;
					if (flag2)
					{
						ErrorReport = "AddProjectParameterBinding: Переданный параметр null.";
						result = false;
					}
					else
					{
						bool flag3 = cat == null;
						if (flag3)
						{
							ErrorReport = "AddProjectParameterBinding: Переданная категория null.";
							result = false;
						}
						else
						{
							ElementBinding bindingByName = RUtil.GetBindingByName(doc, p.Definition.Name);
							bool flag4 = bindingByName == null;
							if (flag4)
							{
								result = false;
							}
							else
							{
								CategorySet categories = bindingByName.Categories;
								bool flag5 = categories.Contains(cat);
								if (flag5)
								{
									ErrorReport = string.Concat(new string[]
									{
										"Уже существует привязка параметра '",
										p.Definition.Name,
										"' к категории ",
										cat.Name,
										"."
									});
									result = true;
								}
								else
								{
									categories.Insert(cat);
									bool flag6 = bindingByName is InstanceBinding;
									if (flag6)
									{
										InstanceBinding item = doc.Application.Create.NewInstanceBinding(categories);
										result = doc.ParameterBindings.ReInsert(p.Definition, item);
									}
									else
									{
										TypeBinding item2 = doc.Application.Create.NewTypeBinding(categories);
										result = doc.ParameterBindings.ReInsert(p.Definition, item2);
									}
								}
							}
						}
					}
				}
			}
			return result;
		}
