		public static bool ParameterCreate(Autodesk.Revit.DB.Document doc, string name, string guid, CategorySet cats, ParamDataType dataType, ParamGroup group, out string ErrorReport, bool boundToInstance = true, bool isVisible = true, bool createFromTempFOP = false)
		{
			ErrorReport = "";
			string sharedParametersFilename = doc.Application.SharedParametersFilename;
			string tempFileName = RUtil.GetTempFileName("FOP", "txt");
			bool flag = false;
			DefinitionFile sharedParameterFile = RUtil.GetSharedParameterFile(doc);
			bool flag2 = sharedParameterFile == null;
			bool result = false;
			Definition def;
			if (flag2)
			{
				bool flag3 = !createFromTempFOP;
				if (flag3)
				{
					ErrorReport = "Отсутствует Файл Общих Параметров (ФОП). См. Управление -> Общие параметры -> Обзор.";
					result = false;
					return result;
				}
				def = ParamDataTypeService.CreateTempDefinition(doc, tempFileName, name, guid, dataType, isVisible);
				flag = true;
			}
			else
			{
				DefinitionGroup definitionGroup;
				bool flag4 = RUtil.FoundDefinitionInSharedParameterFile(sharedParameterFile, name, out def, out definitionGroup);
				bool flag5 = !flag4;
				if (flag5)
				{
					bool flag6 = !createFromTempFOP;
					if (flag6)
					{
						ErrorReport = "В файле общих параметров (ФОП) отсутствует определение для параметра '" + name + "'.";
						result = false;
						return result;
					}
					def = ParamDataTypeService.CreateTempDefinition(doc, tempFileName, name, guid, dataType, isVisible);
					flag = true;
				}
			}
			Autodesk.Revit.DB.Binding binding;
			if (boundToInstance)
			{
				binding = doc.Application.Create.NewInstanceBinding(cats);
			}
			else
			{
				binding = doc.Application.Create.NewTypeBinding(cats);
			}
			BindingMap parameterBindings = doc.ParameterBindings;
			try
			{
				bool flag7 = ParamGroupService.BindingMapInsert(parameterBindings, def, binding, group);
				ErrorReport = "Параметр '" + name + "' " + (flag7 ? "добавлен в проект." : "не добавлен в проект.");
				Debug.Print(ErrorReport);
				Log.Write(ErrorReport);
				result = true;
			}
			catch (Exception ex)
			{
				ErrorReport = ex.Message;
				Log.Write(ex);
				result = false;
			}
			finally
			{
				bool flag8 = flag;
				if (flag8)
				{
					File.Delete(tempFileName);
					doc.Application.SharedParametersFilename = sharedParametersFilename;
				}
			}
			return result;
		}
		private static bool FoundDefinitionInSharedParameterFile(DefinitionFile defFile, string name, out Definition def, out DefinitionGroup defGroup)
		{
			def = null;
			defGroup = null;
			Func<Definition, bool> __9__0 = null;
			bool result = false;
			foreach (DefinitionGroup current in defFile.Groups)
			{
				IEnumerable<Definition> arg_51_0 = current.Definitions;
				Func<Definition, bool> arg_51_1 = null;
				if ((arg_51_1 = __9__0) == null)
				{
					arg_51_1 = (__9__0 = ((Definition d) => d.Name == name));
				}
				def = arg_51_0.FirstOrDefault(arg_51_1);
				bool flag = def != null;
				if (flag)
				{
					defGroup = current;
					result = true;
					return result;
				}
			}
			result = false;
