		public static Dictionary<ElementId, object> SaveParameterValues(Autodesk.Revit.DB.Document doc, string guid, StorageType storageType, List<ElementId> elemForSaveList, string koef, bool ConvertFromInternalUnits = false)
		{
			Dictionary<ElementId, object> dictionary = new Dictionary<ElementId, object>();
			Dictionary<ElementId, object> result;
			switch (storageType)
			{
			case StorageType.None:
				result = null;
				return result;
			case StorageType.Integer:
				foreach (ElementId current in elemForSaveList)
				{
					int num = doc.GetElement(current).GetParameterByGuid(new Guid(guid)).AsInteger();
					bool flag = koef == "";
					if (flag)
					{
						dictionary.Add(current, num);
					}
					else
					{
						dictionary.Add(current, num * Convert.ToInt32(koef));
					}
				}
				break;
			case StorageType.Double:
				foreach (ElementId current2 in elemForSaveList)
				{
					Autodesk.Revit.DB.Parameter parameterByGuid = doc.GetElement(current2).GetParameterByGuid(new Guid(guid));
					bool flag2 = parameterByGuid == null;
					if (!flag2)
					{
						bool flag3 = !parameterByGuid.HasValue;
						if (!flag3)
						{
							double num2 = parameterByGuid.AsDouble();
							bool flag4 = ConvertFromInternalUnits && parameterByGuid.HasDisplayUnitType();
							if (flag4)
							{
								num2 = RCompatibility.ConvertFromInternalUnits2(num2, parameterByGuid.DisplayUnit());
							}
							bool flag5 = koef != "";
							if (flag5)
							{
								num2 *= Convert.ToDouble(koef);
							}
							dictionary.Add(current2, num2);
						}
					}
				}
				break;
			case StorageType.String:
				foreach (ElementId current3 in elemForSaveList)
				{
					dictionary.Add(current3, doc.GetElement(current3).GetParameterByGuid(new Guid(guid)).AsString());
				}
				break;
			case StorageType.ElementId:
				foreach (ElementId current4 in elemForSaveList)
				{
					dictionary.Add(current4, doc.GetElement(current4).GetParameterByGuid(new Guid(guid)).AsElementId());
				}
				break;
			}
			foreach (KeyValuePair<ElementId, object> current5 in dictionary)
			{
				Element element = doc.GetElement(current5.Key);
				Autodesk.Revit.DB.Parameter parameterByGuid2 = element.GetParameterByGuid(new Guid(guid));
				Log.Write(string.Format("Сохранение значения. ElementId:{0}  Category:{1}\tПараметр '{2}': {3}", new object[]
				{
					current5.Key,
					element.Category.Name,
					parameterByGuid2.Definition.Name,
					(current5.Value == null) ? "null" : current5.Value.ToString()
				}));
			}
			result = dictionary;
			return result;
		}
		public static bool LoadParameterValues(Autodesk.Revit.DB.Document doc, Dictionary<ElementId, object> dict, string GUID, BuiltInParameter BIP, bool ConvertToInternalUnits = false)
		{
			bool result = false;
			foreach (KeyValuePair<ElementId, object> current in dict)
			{
				Element element = doc.GetElement(current.Key);
				bool flag = GUID == "";
				Autodesk.Revit.DB.Parameter parameter;
