				{
					parameter = element.get_Parameter(BIP);
				}
				else
				{
					parameter = element.GetParameterByGuid(new Guid(GUID));
				}
				bool flag2 = parameter == null;
				if (flag2)
				{
					Debug.Print("Parameter with GUID={0} is null", new object[]
					{
						GUID
					});
				}
				else
				{
					StorageType storageType = parameter.StorageType;
					StorageType storageType2 = storageType;
					if (storageType2 == StorageType.None)
					{
						result = false;
						return result;
					}
					if (storageType2 != StorageType.Double)
					{
						string text;
						parameter.SetValue(current.Value, out text);
					}
					else
					{
						bool flag3 = ConvertToInternalUnits && parameter.HasDisplayUnitType();
						if (flag3)
						{
							double num = RCompatibility.ConvertToInternalUnits2((double)current.Value, parameter.DisplayUnit());
							string text;
							parameter.SetValue(num, out text);
						}
						else
						{
							string text;
							parameter.SetValue(current.Value, out text);
						}
					}
					Log.Write(string.Format("Загрузка значения. ElementId:{0}  Category:{1}\tПараметр '{2}': {3}", new object[]
					{
						current.Key,
						element.Category.Name,
						parameter.Definition.Name,
						(current.Value == null) ? "null" : current.Value.ToString()
					}));
				}
			}
			result = true;
			return result;
		}
		public static bool DeleteParameterByName(Autodesk.Revit.DB.Document doc, string name)
		{
			BindingMap parameterBindings = doc.ParameterBindings;
			DefinitionBindingMapIterator definitionBindingMapIterator = parameterBindings.ForwardIterator();
			bool result = false;
			while (definitionBindingMapIterator.MoveNext())
			{
				Definition key = definitionBindingMapIterator.Key;
				bool flag = key.Name.Equals(name);
				if (flag)
				{
					try
					{
						bool flag2 = parameterBindings.Remove(key);
						Debug.Print("Параметр '" + name + "' " + (flag2 ? "удалён." : "не удалён."));
						result = true;
						return result;
					}
					catch (Exception ex)
					{
						Log.Write(ex);
					}
					continue;
				}
			}
			result = false;
			return result;
		}
