		public static void WriteContentBackToTxtFile(List<string[]> lines, string path)
		{
			using (StreamWriter streamWriter = new StreamWriter(path))
			{
				foreach (string[] current in lines)
				{
					string text = string.Empty;
					string[] array = current;
					for (int i = 0; i < array.Length; i++)
					{
						string arg = array[i];
						text += string.Format("{0}\t", arg);
					}
					text = text.Remove(text.Length - 1);
					streamWriter.WriteLine(text);
				}
			}
		}
		public static List<string[]> ReadSharedParameterFileByPath(string path)
		{
			List<string[]> list = new List<string[]>();
			using (StreamReader streamReader = new StreamReader(path))
			{
				while (!streamReader.EndOfStream)
				{
					string[] array = streamReader.ReadLine().Split(new char[]
					{
						'\t'
					});
					bool flag = array != null && array.Length > 0;
					if (flag)
					{
						list.Add(array);
					}
				}
			}
			return list;
		}
