		public static List<ElementId> GetIntersectingLinkedElementIds(Element e, RevitLinkInstance rli)
		{
			List<ElementId> list = new List<ElementId>();
			bool flag = e == null || rli == null || !e.IsValidObject;
			List<ElementId> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				GeomService geomService = new GeomService(e.Document, null);
				Solid solid = geomService.GetSolid2(e);
				Transform transform = rli.GetTransform();
				bool flag2 = !transform.AlmostEqual(Transform.Identity);
				if (flag2)
				{
					solid = SolidUtils.CreateTransformed(solid, transform.Inverse);
				}
				ElementIntersectsSolidFilter filter = new ElementIntersectsSolidFilter(solid);
				FilteredElementCollector filteredElementCollector = new FilteredElementCollector(rli.GetLinkDocument()).WherePasses(filter);
				list.AddRange(filteredElementCollector.ToElementIds());
				result = list;
			}
			return result;
		}
