		public static Family GetFamily(Autodesk.Revit.DB.Document doc, string name, string description, out string report, bool askPermission = true)
		{
			report = "";
			ElementId familyIdByName = RUtil.GetFamilyIdByName(doc, name);
			bool flag = familyIdByName != ElementId.InvalidElementId;
			Family result;
			if (flag)
			{
				result = (doc.GetElement(familyIdByName) as Family);
			}
			else
			{
				Family family = null;
				bool flag2 = false;
				if (askPermission)
				{
					DialogResult dialogResult = MessageBox.Show("Семейство " + description + " не найдено. Добавить его?", "Ошибка получения семейства " + description, MessageBoxButtons.YesNo);
					flag2 = (dialogResult == DialogResult.Yes);
				}
				else
				{
					flag2 = true;
				}
				bool flag3 = flag2;
				if (flag3)
				{
					string dllFolder = RUtil.GetDllFolder();
					string text = dllFolder + "\\" + name + ".rfa";
					bool flag4 = !File.Exists(text);
					if (flag4)
					{
						report = string.Concat(new string[]
						{
							report,
							"Семейство ",
							description,
							" не найдено.\r\n Файл ",
							name,
							".rfa не обнаружен в папке ",
							dllFolder,
							"."
						});
						result = null;
					}
					else
					{
						try
						{
							using (Transaction transaction = new Transaction(doc))
							{
								transaction.Start("Загрузка семейства");
								doc.LoadFamily(text, out family);
								transaction.Commit();
							}
						}
						catch (Exception ex)
						{
							report = report + "Не удалось загрузить семейство " + description + ".";
							Log.Write(ex);
							result = null;
							return result;
						}
						result = family;
					}
				}
				else
				{
					report = report + "Семейство " + description + " отсутствует в проекте.";
					result = null;
				}
			}
			return result;
		}
