		private static bool FilterMatches(string name, string filter, bool caseSensitiveComparison)
		{
			bool flag = string.IsNullOrEmpty(name);
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				bool flag2 = string.IsNullOrEmpty(filter);
				if (flag2)
				{
					result = true;
				}
				else
				{
					bool flag3 = !caseSensitiveComparison;
					if (flag3)
					{
						name = name.ToUpper();
						filter = filter.ToUpper();
					}
					result = name.Contains(filter);
				}
			}
			return result;
		}
