		public static void GetMultiLayerWallRecursive(Wall wall, ref List<ElementId> result)
		{
			Autodesk.Revit.DB.Document document = wall.Document;
			List<ElementId> list = JoinGeometryUtils.GetJoinedElements(document, wall).ToList<ElementId>();
			using (List<ElementId>.Enumerator enumerator = list.GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					ElementId id = enumerator.Current;
					Wall wall2 = document.GetElement(id) as Wall;
					bool flag = wall2 == null;
					if (!flag)
					{
						bool flag2 = !wall2.Orientation.IsParallel(wall.Orientation);
						if (!flag2)
						{
							bool flag3 = result.Exists((ElementId x) => object.Equals(x, id));
							if (!flag3)
							{
								result.Add(id);
								RUtil.GetMultiLayerWallRecursive(wall2, ref result);
							}
						}
					}
				}
			}
		}
		public static Dictionary<RevitLinkInstance, List<ElementId>> GetRoomClosedWalls(Dictionary<RevitLinkInstance, List<ElementId>> roomWalls)
		{
			Dictionary<RevitLinkInstance, List<ElementId>> dictionary = new Dictionary<RevitLinkInstance, List<ElementId>>();
			foreach (KeyValuePair<RevitLinkInstance, List<ElementId>> current in roomWalls)
			{
				Autodesk.Revit.DB.Document linkDocument = current.Key.GetLinkDocument();
				List<ElementId> list = new List<ElementId>();
				foreach (ElementId current2 in current.Value)
				{
					Element element = linkDocument.GetElement(current2);
					bool flag = element == null || !(element is Wall);
					if (!flag)
					{
						List<ElementId> collection = new List<ElementId>();
						RUtil.GetMultiLayerWallRecursive(element as Wall, ref collection);
						list.AddRange(collection);
					}
				}
				bool flag2 = list.Count > 0;
				if (flag2)
				{
					dictionary.Add(current.Key, list.Distinct<ElementId>().ToList<ElementId>());
				}
			}
			return dictionary;
		}
		public static List<List<XYZ>> GetHostBoundary(Solid solid)
		{
			List<List<XYZ>> list = new List<List<XYZ>>();
			PlanarFace planarFace = null;
			FaceArray faces = solid.Faces;
			foreach (Face face in faces)
			{
				PlanarFace planarFace2 = face as PlanarFace;
				bool flag = null != planarFace2 && planarFace2.IsHorizontal();
				if (flag)
				{
					bool flag2 = null == planarFace || planarFace2.Origin.Z < planarFace.Origin.Z;
					if (flag2)
					{
						planarFace = planarFace2;
					}
				}
			}
			bool flag3 = planarFace == null;
			List<List<XYZ>> result;
			if (flag3)
			{
				result = list;
			}
			else
			{
				XYZ xYZ = XYZ.Zero;
				EdgeArrayArray edgeLoops = planarFace.EdgeLoops;
				foreach (EdgeArray edgeArray in edgeLoops)
				{
					List<XYZ> list2 = new List<XYZ>();
					bool flag4 = true;
					foreach (Edge edge in edgeArray)
					{
						IList<XYZ> list3 = edge.Tessellate();
						XYZ xYZ2 = list3[0];
						bool flag5 = !flag4;
						if (flag5)
						{
							Debug.Assert(xYZ2.IsAlmostEqualTo(xYZ), "expected subsequent start point to equal previous end point");
						}
						int count = list3.Count;
						xYZ = list3[count - 1];
						for (int i = 0; i < count - 1; i++)
						{
							XYZ xYZ3 = list3[i];
							xYZ3 -= 0.1 * XYZ.BasisZ;
							list2.Add(xYZ3);
						}
					}
					xYZ -= 0.1 * XYZ.BasisZ;
					Debug.Assert(xYZ.IsAlmostEqualTo(list2[0]), "expected last end point to equal first start point");
					list.Add(list2);
				}
				result = list;
			}
			return result;
		}
