		public static Transform GetProjectLocationTransform(Autodesk.Revit.DB.Document doc)
		{
			ProjectPosition projectPosition = doc.ActiveProjectLocation.GetProjectPosition(XYZ.Zero);
			XYZ vector = new XYZ(projectPosition.EastWest, projectPosition.NorthSouth, projectPosition.Elevation);
			Transform transform = Transform.CreateTranslation(vector);
			Transform right = Transform.CreateRotation(XYZ.BasisZ, projectPosition.Angle);
			return transform.Multiply(right);
		}
