						using (XmlWriter xmlWriter = XmlWriter.Create(fileStream, this._settings))
						{
							this.RemoveBadChars(this._xeRoot);
							this._xeRoot.Save(xmlWriter);
						}
						fileStream.Close();
					}
					catch (Exception ex)
					{
						string text2 = "Не удалось выполнить сохранение xml-файл.";
