					}
					result = true;
				}
			}
			return result;
		}
		private void RemoveBadChars(XElement xeRoot)
		{
			bool flag = xeRoot == null;
			if (!flag)
			{
				foreach (XElement current in xeRoot.Descendants())
				{
					bool hasElements = current.HasElements;
					if (!hasElements)
					{
						bool flag2 = false;
						string value = current.Value;
						for (int i = 0; i < value.Length; i++)
						{
							char ch = value[i];
							UnicodeCategory unicodeCategory = CharUnicodeInfo.GetUnicodeCategory(ch);
							bool flag3 = this.UnprintableUnicodeCats.Contains(unicodeCategory);
							if (flag3)
							{
								flag2 = true;
								break;
							}
						}
						bool flag4 = flag2;
						if (flag4)
						{
							current.Value = XmlConvert.EncodeName(current.Value);
							current.Add(new XAttribute("encoded", "true"));
						}
						else
						{
							XAttribute xAttribute = current.Attribute("encoded");
							if (xAttribute != null)
							{
								xAttribute.Remove();
							}
						}
					}
				}
			}
		}
