		private static bool IsFullPath(string path, out string errDescription)
		{
			errDescription = "";
			bool flag = string.IsNullOrWhiteSpace(path);
			bool result = false;
			if (flag)
			{
				errDescription = "путь к файлу пустой";
				result = false;
			}
			else
			{
				bool flag2 = path.IndexOfAny(Path.GetInvalidPathChars().ToArray<char>()) != -1;
				if (flag2)
				{
					errDescription = "недопустимые символы в пути к файлу";
					result = false;
				}
				else
				{
					bool flag3 = !Path.IsPathRooted(path);
					if (flag3)
					{
						errDescription = "путь не является абсолютным";
						result = false;
					}
					else
					{
						string pathRoot = Path.GetPathRoot(path);
						bool flag4 = pathRoot.Length <= 2;
						if (flag4)
						{
							errDescription = "неправильный корневой элемент пути";
							result = false;
						}
						else
						{
							bool flag5 = pathRoot == path && pathRoot.StartsWith("\\\\") && pathRoot.IndexOf('\\', 2) == -1;
							if (flag5)
							{
								errDescription = "не обнаружено имя папки на сервере";
								result = false;
							}
							else
							{
								result = true;
							}
						}
					}
				}
			}
			return result;
		}
	}
	public interface IConvertibleToXml
	{
		XElement Convert2Xml(params object[] args);
	}
	public class XmlFileManager
	{
		public const string ERR_MSG_1 = "не найден файл";
		public static string Save(IConvertibleToXml dataset, string filePath, string fileDialogTitle, params object[] convertArgs)
		{
			string text = "";
			bool flag = string.IsNullOrEmpty(filePath) || !RUtil.IsFullPath(filePath, out text);
			string result;
			if (flag)
			{
				filePath = XmlFileManager.GetSaveFilePath(filePath, fileDialogTitle);
				bool flag2 = filePath == "";
				if (flag2)
				{
					result = "";
					return result;
				}
			}
			bool flag3 = !File.Exists(filePath);
			if (flag3)
			{
				string directoryName = Path.GetDirectoryName(filePath);
				bool flag4 = Directory.Exists(directoryName);
				if (flag4)
				{
					try
					{
						File.Create(filePath).Close();
					}
					catch (Exception ex)
					{
						text = "Не удалось создать файл '" + filePath + "'.";
						Log.Write(ex);
					}
				}
				else
				{
					text = "Отсутствует папка для сохранения данных в файл xml";
				}
			}
			bool flag5 = dataset == null;
			if (flag5)
			{
				text = "Сохранение данных в xml-файл отменено. Данные не заданы.";
			}
			bool flag6 = text != "";
			if (flag6)
			{
				Log.Write(text);
				MessageBox.Show(text, "Сохранение данных");
				result = filePath;
			}
			else
			{
				XDocument xDocument = new XDocument(new XDeclaration("1.0", "utf-8", "yes"), Array.Empty<object>());
				XElement content = dataset.Convert2Xml(convertArgs);
				xDocument.Add(content);
				XmlWriterSettings settings = new XmlWriterSettings
				{
					Encoding = Encoding.UTF8,
					Indent = true,
					IndentChars = "\t"
				};
				try
				{
					using (XmlWriter xmlWriter = XmlWriter.Create(filePath, settings))
					{
						xDocument.Save(xmlWriter);
					}
				}
				catch (Exception ex2)
				{
					string text2 = "Не удалось выполнить сохранение данных в xml-файл.";
					MessageBox.Show(text2, "Сохранение в файл");
					Log.Write(text2);
					Log.Write(ex2);
					result = filePath;
					return result;
				}
				result = filePath;
			}
			return result;
		}
