				Filter = "XML-документ (*.xml)|*.xml|All files (*.*)|*.*",
				Title = fileDialogTitle,
				RestoreDirectory = true,
				AddExtension = true,
				OverwritePrompt = true
			};
			string text;
			bool flag = RUtil.IsFullPath(path, out text);
			if (flag)
			{
				saveFileDialog.InitialDirectory = Path.GetFullPath(path);
			}
			bool flag2 = saveFileDialog.ShowDialog() == DialogResult.OK;
			if (flag2)
			{
				result = saveFileDialog.FileName;
			}
			return result;
		}
		public static XElement Load(string filePath, string rootName, out string errReport)
		{
			errReport = "";
			bool flag = !File.Exists(filePath);
			XElement result;
			if (flag)
			{
				errReport = "не найден файл";
				result = null;
			}
			else
			{
				XDocument xDocument = XDocument.Load(filePath);
				XElement xElement = xDocument.Element(rootName);
				bool flag2 = xElement == null || xElement.Name != rootName;
				if (flag2)
				{
					errReport = "в файле отсутствует узел '" + rootName + "'";
