	internal class XmlSettingsService
	{
		public const string ERR_MSG_1 = "не найден файл";
		private string _mainNodeName;
		private readonly string _xpath;
		public string ErrReport
		{
			get;
			set;
		}
		public XElement Xe
		{
			get;
			private set;
		}
		public XElement DefXe
		{
			get;
			private set;
		}
		public XmlSettingsService(string xpath)
		{
			this.ErrReport = "";
			
			this._xpath = xpath;
			this.Upload();
			bool flag = this.ErrReport != "";
			if (flag)
			{
				Log.Write(this.ErrReport);
			}
		}
		private void Upload()
		{
			XmlFile xmlFile = new XmlFile("", "root", false, true);
			bool creationError = xmlFile.CreationError;
			if (creationError)
			{
				string text = "Не удалось открыть файл с настройками. Обратитесь к разработчику.";
				this.ErrReport = text;
				MessageBox.Show(text);
				Log.Write(text);
			}
			else
			{
				string text2;
				this.Xe = xmlFile.GetElementOrDefElement(this._xpath, out text2, "");
				bool flag = !string.IsNullOrEmpty(text2);
				if (flag)
				{
					this.ErrReport = text2;
				}
				else
				{
					bool flag2 = this.Xe == null;
					if (flag2)
					{
						this.ErrReport = "не найден узел " + this._xpath;
					}
					else
					{
						this._mainNodeName = this.Xe.Name.ToString();
						this.DefXe = XmlFile.GetElementByDef(this._xpath, out text2, "");
						bool flag3 = !string.IsNullOrEmpty(text2);
						if (flag3)
						{
							this.ErrReport = text2;
						}
					}
				}
			}
		}
		public void UploadSettings(IXmlSerializable settings)
		{
			bool flag = this.ErrReport != "";
			if (!flag)
			{
				settings.Deserialize(this.Xe, this.DefXe);
				bool flag2 = settings.ErrReport != "";
				if (flag2)
				{
					Log.Write(settings.ErrReport);
					bool flag3 = this.ResetToDefault(settings.ErrReport);
					if (flag3)
					{
						this.Upload();
						bool flag4 = this.ErrReport == "";
						if (flag4)
						{
							settings.ErrReport = "";
							settings.Deserialize(this.Xe, this.DefXe);
							this.ErrReport = settings.ErrReport;
							XmlSettingsService.ShowResultMessage(this.ErrReport);
						}
					}
					else
					{
						this.ErrReport = settings.ErrReport;
					}
				}
			}
		}
		private bool ResetToDefault(string errReport)
		{
			string text = "Обнаружена ошибка в сохранённых настройках:\r\n\"" + errReport + "\".\r\n\r\nСбросить к настройкам по умолчанию?";
			DialogResult dialogResult = MessageBox.Show(text, "Сброс настроек", MessageBoxButtons.YesNo);
			bool flag = dialogResult == DialogResult.No;
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				XmlFile xmlFile = new XmlFile("", "root", false, true);
				bool creationError = xmlFile.CreationError;
				if (creationError)
				{
					string text2 = "Не удалось открыть файл с настройками. Обратитесь к разработчику.";
