				XDocument xDocument = new XDocument(new XDeclaration("1.0", "utf-8", "yes"), Array.Empty<object>());
				XElement content = dataset.Serialize(rootName);
				xDocument.Add(content);
				XmlWriterSettings settings = new XmlWriterSettings
				{
					Encoding = Encoding.UTF8,
					Indent = true,
					IndentChars = "\t"
				};
				try
				{
					using (XmlWriter xmlWriter = XmlWriter.Create(filePath, settings))
					{
						xDocument.Save(xmlWriter);
					}
				}
				catch (Exception ex2)
				{
					string text2 = "Не удалось выполнить сохранение данных в xml-файл.";
					MessageBox.Show(text2, "Сохранение в файл");
					Log.Write(text2);
					Log.Write(ex2);
					result = filePath;
					return result;
				}
				result = filePath;
			}
			return result;
		}
		private static string GetSaveFilePath(string path, string fileDialogTitle)
		{
			string result = "";
			System.Windows.Forms.SaveFileDialog saveFileDialog = new System.Windows.Forms.SaveFileDialog
			{
				DefaultExt = "xml",
				Filter = "XML-документ (*.xml)|*.xml|All files (*.*)|*.*",
				Title = fileDialogTitle,
				RestoreDirectory = true,
				AddExtension = true,
				OverwritePrompt = true
			};
			string text;
			bool flag = RUtil.IsFullPath(path, out text);
			if (flag)
			{
				saveFileDialog.InitialDirectory = Path.GetFullPath(path);
			}
			bool flag2 = saveFileDialog.ShowDialog() == DialogResult.OK;
			if (flag2)
			{
				result = saveFileDialog.FileName;
			}
			return result;
		}
		public static XElement Load(string filePath, string rootName, out string errReport)
		{
			errReport = "";
			bool flag = !File.Exists(filePath);
			XElement result;
