	public class LinkedElementTypeFilter : ISelectionFilter
	{
		private readonly Autodesk.Revit.DB.Document _doc = null;
		private readonly Type _t;
		private readonly bool _isLinked = false;
		public LinkedElementTypeFilter(Autodesk.Revit.DB.Document doc, Type t, bool isLinked)
		{
			this._doc = doc;
			this._t = t;
			this._isLinked = isLinked;
		}
		public bool AllowElement(Element elem)
		{
			bool isLinked = this._isLinked;
			return isLinked || this.MyAllow(elem);
		}
		public bool AllowReference(Reference reference, XYZ point)
		{
			bool isLinked = this._isLinked;
			bool result = false;
			if (isLinked)
			{
				RevitLinkInstance revitLinkInstance = this._doc.GetElement(reference) as RevitLinkInstance;
				Autodesk.Revit.DB.Document linkDocument = revitLinkInstance.GetLinkDocument();
				Element element = linkDocument.GetElement(reference.LinkedElementId);
				result = this.MyAllow(element);
			}
			else
			{
				result = false;
			}
			return result;
		}
		private bool MyAllow(Element elem)
		{
			return this._t.IsInstanceOfType(elem);
		}
	}
