			if (useFilledRegion)
			{
				stringBuilder.Append(this.FRTdata.Name + " ");
				stringBuilder.Append(this.FRTdata.GetDescription());
			}
			bool useTextNote = this.UseTextNote;
			if (useTextNote)
			{
				bool flag = stringBuilder.Length > 0;
				if (flag)
				{
					stringBuilder.Append("\r\n");
