		public List<ElementId> Visualize(Visual v, CurveLoop loop, XYZ point, double width, string text, out string errReport)
		{
			errReport = "";
			List<ElementId> list = new List<ElementId>();
			bool flag = v == null || loop == null || !loop.Any<Curve>();
			List<ElementId> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				bool useFilledRegion = this.UseFilledRegion;
				if (useFilledRegion)
				{
					try
					{
						FilledRegion filledRegion = v.DrawCurveLoopFilled(this._frt, loop);
						list.Add(filledRegion.Id);
					}
					catch (System.ArgumentException ex)
					{
						bool flag2 = ex.Message == "Boundaries are self-intersecting.";
						if (flag2)
						{
							errReport = "Самопересечение контура";
						}
					}
					catch (Exception ex2)
					{
						errReport = ex2.Message;
					}
				}
				bool useTextNote = this.UseTextNote;
				if (useTextNote)
				{
					ElementId elementId = TextNoteExt.Create(v.Doc, point, width, text, this.TNT, null);
					bool flag3 = elementId != null;
					if (flag3)
					{
						list.Add(elementId);
					}
				}
				result = list;
			}
			return result;
		}
		public XElement Convert2Xml(string nodeName = "curveLoopStyle")
		{
			XElement xElement = new XElement(nodeName);
			xElement.Add(new XElement("useFilledRegion", this.UseFilledRegion));
			xElement.Add(new XElement("useTextNote", this.UseTextNote));
			bool flag = this.FRTdata != null;
			if (flag)
			{
				xElement.Add(this.FRTdata.Convert2Xml("filledRegionType"));
			}
			bool flag2 = this.TNTdata != null;
			if (flag2)
			{
				xElement.Add(this.TNTdata.Convert2Xml("textNoteType"));
			}
			return xElement;
		}
	}
