			bool flag = !double.TryParse(this.txtTextSizeMm.Text, out num);
			if (flag)
			{
				this._errP.SetError(this.txtTextSizeMm, value);
				e.Cancel = true;
			}
			else
			{
				bool flag2 = num <= 0.2526 || num >= 413.6451;
				if (flag2)
				{
					this._errP.SetError(this.txtTextSizeMm, value);
					e.Cancel = true;
				}
			}
		}
