	public class LineStylesButton
	{
		private readonly System.Windows.Forms.Form _frm;
		private readonly Button _btn;
		private UIApplication _app;
		private DateTime _dt;
		public LineStylesButton(Button btn)
		{
			this._btn = btn;
			this._frm = this._btn.FindForm();
			this._btn.Click += new EventHandler(this.btn_Click);
		}
		private async void btn_Click(object sender, EventArgs e)
		{
			this._dt = DateTime.Now;
			await RevitTask.RunAsync(uiapp =>
			{
				this._app = uiapp;
				this._app.Idling += new EventHandler<IdlingEventArgs>(this.OnCommandEnded);
				RevitCommandId commandId = RevitCommandId.LookupPostableCommandId(PostableCommand.LineStyles);
				if (commandId != null && uiapp.CanPostCommand(commandId))
				{
					uiapp.PostCommand(commandId);
				}
			});
		}
		private void OnCommandEnded(object sender, EventArgs eventArgs)
		{
			bool flag = DateTime.Now > this._dt.AddSeconds(3.0);
			if (flag)
			{
				this._app.Idling -= new EventHandler<IdlingEventArgs>(this.OnCommandEnded);
				this.ReturnFocusToForm();
			}
		}
		private void ReturnFocusToForm()
		{
			IntPtr foregroundWindow = RUtil.FindWindowsWithText(this._frm.Text).FirstOrDefault<IntPtr>();
			RUtil.SetForegroundWindow(foregroundWindow);
		}
	}
