		public static void FindNormalAndTangent(Curve curve, XYZ point, out XYZ normal, out XYZ tangent)
		{
			normal = XYZ.Zero;
			tangent = XYZ.Zero;
			bool flag = curve == null || point == null;
			if (!flag)
			{
				Line line = curve as Line;
				bool flag2 = line != null;
				if (flag2)
				{
					tangent = line.Direction.Normalize();
				}
				else
				{
					IntersectionResult intersectionResult = curve.Project(point);
					bool flag3 = intersectionResult != null;
					if (flag3)
					{
						double parameter = intersectionResult.Parameter;
						Transform transform = curve.ComputeDerivatives(parameter, false);
						tangent = transform.BasisX.Normalize();
						normal = transform.BasisZ.Normalize();
					}
				}
			}
		}
		public static ParameterFilterElement CreateFilter(Autodesk.Revit.DB.Document doc, ElementId paramId, List<ElementId> catIds, string systemName, string filterName)
		{
			List<FilterRule> filterRules = new List<FilterRule>
			{
				RCompatibility.CreateNotEqualsRule2(paramId, systemName)
			};
			ParameterFilterElement parameterFilterElement = ParameterFilterElement.Create(doc, filterName, catIds);
			parameterFilterElement.SetElementFilter(new ElementParameterFilter(filterRules));
			Debug.Print("filterName: " + filterName);
			return parameterFilterElement;
		}
	}
