		public static ConnectorProfileType GetShape(Duct duct)
		{
			ConnectorProfileType result = ConnectorProfileType.Invalid;
			foreach (Connector connector in duct.ConnectorManager.Connectors)
			{
				bool flag = connector.ConnectorType == ConnectorType.End;
				if (flag)
				{
					result = connector.Shape;
					break;
				}
			}
			return result;
		}
		public static ConnectorProfileType[] GetProfileTypes(Duct duct)
		{
			ConnectorSet connectors = duct.ConnectorManager.Connectors;
			int size = connectors.Size;
			ConnectorProfileType[] array = new ConnectorProfileType[size];
			int num = 0;
			foreach (Connector connector in connectors)
			{
				array[num++] = connector.Shape;
			}
			return array;
		}
		public static string ConnectorProfileDescription(ConnectorProfileType form)
		{
			string result;
			switch (form)
			{
			case ConnectorProfileType.Round:
				result = "круглый";
				break;
			case ConnectorProfileType.Rectangular:
				result = "прямоугольный";
				break;
			case ConnectorProfileType.Oval:
				result = "овальный";
				break;
			default:
				result = "неизвестной формы";
				break;
			}
			return result;
		}
