			this.Text = formTitle;
			this.dgvValues.Visible = false;
			this.txtValue.Visible = false;
			this.grpConvert.Visible = false;
			this.rdoNoConvert.Checked = true;
			this._cmbxDUT = new ComboboxExt_Filter(this.cmbDUT, allUnits);
			this._state = new FormExt_State(this, this._parentXpath, 444, 519);
			this._state.SetPostConfigAction(new PostConfigAction(this.RestoreDUT));
			this._state.SetPostSavingAction(new PostSavingAction(this.SaveDUT));
			this._state.ConfigRead();
			bool flag = filt != null;
			if (flag)
			{
				this.txtPropName.Text = filt.PropertyName;
				this.DataType = filt.DataType;
				switch (this.DataType)
				{
				case PropertyDataType.String:
				{
					this.rdoString.Checked = true;
					List<string> list = filt.Matching.Value as List<string>;
					bool flag2 = list != null;
					if (flag2)
					{
						foreach (string current in list)
						{
							int index = this.dgvValues.Rows.Add();
							DataGridViewRow dataGridViewRow = this.dgvValues.Rows[index];
							dataGridViewRow.Cells[this.colValues.Index].Value = current;
						}
					}
					else
					{
						int index2 = this.dgvValues.Rows.Add();
						DataGridViewRow dataGridViewRow2 = this.dgvValues.Rows[index2];
						dataGridViewRow2.Cells[this.colValues.Index].Value = filt.Matching.Value.ToString();
					}
					break;
				}
				case PropertyDataType.Integer:
					this.rdoInteger.Checked = true;
					this.txtValue.Text = filt.Matching.Value.ToString();
					break;
				case PropertyDataType.Double:
					this.rdoDouble.Checked = true;
					this.txtValue.Text = filt.Matching.Value.ToString();
					break;
				}
				this.DataTypeChanged();
				this.cmbMatchType.SelectedItem = Matching.AllMatchTypes[filt.Matching.MatchType];
				this.MatchTypeChanged();
				bool flag3 = filt.Matching.FTid.IsNotNull();
				if (flag3)
				{
					this.rdoConvertTo.Checked = true;
					this.SelectItem(filt.Matching.FTid);
				}
			}
			else
			{
				this.DataType = PropertyDataType.String;
				this.DataTypeChanged();
			}
			this._isLoaded = true;
		}
		private string RestoreDUT(XElement xeForm)
		{
			bool flag = xeForm == null;
			string result;
			if (flag)
			{
				result = "не задан XElement формы";
			}
			else
			{
				XElement xElement = xeForm.Element("forgeTypeId");
				bool flag2 = xElement != null;
				if (flag2)
				{
					ForgeTypeId forgeTypeId = new ForgeTypeId(xElement.Value);
					bool flag3 = forgeTypeId != null;
					if (flag3)
					{
						this.SelectItem(forgeTypeId);
					}
				}
				result = "";
			}
			return result;
		}
		private void SaveDUT(XElement xeForm)
		{
			bool flag = this.cmbDUT.SelectedItem != null;
			if (flag)
			{
				ForgeTypeId forgeTypeId = ((ItemComment)this.cmbDUT.SelectedItem).Item as ForgeTypeId;
				bool flag2 = forgeTypeId != null;
				if (flag2)
				{
					xeForm.Add(new XElement("forgeTypeId", forgeTypeId.TypeId));
				}
			}
		}
		private void SelectItem(ForgeTypeId unit)
		{
			ItemComment itemComment = this.cmbDUT.Items.Cast<ItemComment>().FirstOrDefault((ItemComment x) => (ForgeTypeId)x.Item == unit);
			bool flag = itemComment != null;
			if (flag)
			{
				this.cmbDUT.SelectedItem = itemComment;
			}
			else
			{
				this.cmbDUT.SelectedIndex = -1;
			}
		}
