		private void DataTypeChanged()
		{
			string[] array = new string[0];
			this.cmbMatchType.Items.Clear();
			this.dgvValues.Visible = false;
			this.txtValue.Visible = false;
			switch (this.DataType)
			{
			case PropertyDataType.String:
				array = new string[]
				{
					"равно",
					"не равно",
					"содержит",
					"не содержит",
					"начинается с",
					"не начинается с",
					"заканчивается на",
					"не заканчивается на"
				};
				this.Hide(this.txtValue);
				this.Show(this.dgvValues);
				this.grpConvert.Visible = false;
				break;
			case PropertyDataType.Integer:
				array = new string[]
				{
					"равно",
					"не равно",
					"больше",
					"больше или равно",
					"меньше",
					"меньше или равно"
				};
				this.Hide(this.dgvValues);
				this.Show(this.txtValue);
				this.grpConvert.Visible = false;
				break;
			case PropertyDataType.Double:
				array = new string[]
				{
					"равно",
					"не равно",
					"больше",
					"больше или равно",
					"меньше",
					"меньше или равно"
				};
				this.Hide(this.dgvValues);
				this.Show(this.txtValue);
				this.grpConvert.Visible = true;
				break;
			}
			bool flag = this.DataType != PropertyDataType.Unknown;
			if (flag)
			{
				System.Windows.Forms.ComboBox.ObjectCollection arg_1A7_0 = this.cmbMatchType.Items;
				object[] items = array;
				arg_1A7_0.AddRange(items);
				this.cmbMatchType.SelectedIndex = 0;
			}
		}
		private void MatchTypeChanged()
		{
			bool flag = this.cmbMatchType.SelectedIndex == -1;
			if (!flag)
			{
				string a = this.cmbMatchType.SelectedItem as string;
				PropertyDataType dataType = this.DataType;
				PropertyDataType propertyDataType = dataType;
				if (propertyDataType == PropertyDataType.String)
				{
					bool flag2 = a == "содержит" || a == "не содержит";
					if (flag2)
					{
						this.Hide(this.txtValue);
						this.Show(this.dgvValues);
					}
					else
					{
						this.Hide(this.dgvValues);
						this.Show(this.txtValue);
					}
				}
			}
		}
