		private void btnOk_Click(object sender, EventArgs e)
		{
			bool flag = string.IsNullOrEmpty(this.txtPropName.Text);
			if (flag)
			{
				MessageBox.Show("Не указано название свойства");
			}
			else
			{
				this.PropertyName = this.txtPropName.Text;
				bool flag2 = this.cmbMatchType.SelectedItem != null;
				if (flag2)
				{
					this.MatchType = Matching.AllMatchTypes.FirstOrDefault((KeyValuePair<MatchingType, string> x) => x.Value == (string)this.cmbMatchType.SelectedItem).Key;
				}
				bool flag3 = this.rdoConvertTo.Checked && this.cmbDUT.SelectedItem != null;
				if (flag3)
				{
					this.Unit = (((ItemComment)this.cmbDUT.SelectedItem).Item as ForgeTypeId);
				}
				else
				{
					this.Unit = null;
				}
				this.dgvValues.EndEdit();
				switch (this.DataType)
				{
				case PropertyDataType.String:
				{
					bool flag4 = this.dgvValues.Rows.Count == 1;
					if (flag4)
					{
						this.Value = null;
					}
					else
					{
						bool flag5 = this.dgvValues.Rows.Count == 2;
						if (flag5)
						{
							this.Value = (this.dgvValues.Rows[0].Cells[this.colValues.Index].Value as string);
						}
						else
						{
							List<string> list = new List<string>();
							foreach (DataGridViewRow dataGridViewRow in (IEnumerable)this.dgvValues.Rows)
							{
								bool isNewRow = dataGridViewRow.IsNewRow;
								if (!isNewRow)
								{
									list.Add(dataGridViewRow.Cells[this.colValues.Index].Value as string);
								}
							}
							this.Value = list;
						}
					}
					break;
				}
				case PropertyDataType.Integer:
				{
					int num = 0;
					bool flag6 = int.TryParse(this.txtValue.Text, out num);
					if (!flag6)
					{
						MessageBox.Show("Укажите целое число в качестве значения.");
						return;
					}
					this.Value = num;
					break;
				}
				case PropertyDataType.Double:
				{
					double num2 = 0.0;
					bool flag7 = double.TryParse(this.txtValue.Text, out num2);
					if (!flag7)
					{
						MessageBox.Show("Укажите вещественное число в качестве значения.");
						return;
					}
					this.Value = num2;
					break;
				}
				}
				base.DialogResult = DialogResult.OK;
				base.Close();
			}
		}
		private void txtValue_Validating(object sender, CancelEventArgs e)
		{
			this._errP.SetIconAlignment(this.txtValue, ErrorIconAlignment.MiddleRight);
			this._errP.SetIconPadding(this.txtValue, 2);
			this._errP.SetError(this.txtValue, string.Empty);
			PropertyDataType dataType = this.DataType;
			PropertyDataType propertyDataType = dataType;
			if (propertyDataType != PropertyDataType.Integer)
			{
				if (propertyDataType == PropertyDataType.Double)
				{
					string value = "Здесь должно быть вещественное число.";
					double num = 0.0;
					bool flag = !double.TryParse(this.txtValue.Text, out num);
					if (flag)
					{
						this._errP.SetError(this.txtValue, value);
						e.Cancel = true;
					}
				}
			}
			else
			{
				string value = "Здесь должно быть целое число.";
				int num2 = 0;
				bool flag2 = !int.TryParse(this.txtValue.Text, out num2);
				if (flag2)
				{
					this._errP.SetError(this.txtValue, value);
					e.Cancel = true;
				}
			}
		}
