		private List<string> CaseSensitiveVariants(string s)
		{
			List<string> list = new List<string>
			{
				string.Copy(s)
			};
			bool flag = string.IsNullOrEmpty(s);
			List<string> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				list.Add(string.Copy(s.ToLower()));
				list.Add(string.Copy(s.ToUpper()));
				bool flag2 = s.Length > 1;
				if (flag2)
				{
					list.Add(s.Substring(0, 1).ToUpper() + s.Substring(1, s.Length - 1).ToLower());
				}
				list = list.Distinct<string>().ToList<string>();
				result = list;
			}
			return result;
		}
