		public List<Element> Apply(ModelData md, ApplyOptions options, List<Element> startList, ref StringBuilder sbReport)
		{
			this.FiltersResult.Clear();
			List<Element> list = new List<Element>();
			list.AddRange(startList);
			this.FiltersResult.Add(startList);
			foreach (IFilter current in this.AllFilters)
			{
				sbReport.Append(string.Format("\r\n{0}\r\nдо: {1}", current.Description, list.Count));
				this.LoadData(current, md, options);
				List<Element> filtered = current.GetFiltered(list);
				sbReport.Append(string.Format("\tпосле: {0}", filtered.Count));
				this.FiltersResult.Add(filtered);
				list.Clear();
				bool flag = filtered.Count == 0;
				if (flag)
				{
					break;
				}
				list.AddRange(filtered);
			}
			List<Element> list2 = new List<Element>();
			string name = md.Doc.Settings.Categories.get_Item(BuiltInCategory.OST_CenterLines).Name;
			foreach (Element current2 in list)
			{
				Category category = current2.Category;
				bool flag2 = category == null;
				if (!flag2)
				{
					string b = "<" + category.Name + ">";
					bool flag3 = name != b;
					if (flag3)
					{
						list2.Add(current2);
					}
				}
			}
			bool flag4 = list.Count != list2.Count;
			if (flag4)
			{
				sbReport.Append(string.Format("\r\nс учётом осевых линий: {0}", list2.Count));
			}
			this.FiltersResult[this.FiltersResult.Count - 1] = list2;
			return this.FiltersResult[this.FiltersResult.Count - 1];
		}
		private void LoadData(IFilter filt, ModelData md, ApplyOptions options)
		{
			switch (filt.Type)
			{
			case FilterType.ByCategories:
			case FilterType.ByType:
			case FilterType.ByFamilies:
			case FilterType.ElementIsElementType:
			case FilterType.ByParameterValue:
			case FilterType.ByTypeParameterValue:
			case FilterType.ByHostParameterValue:
			case FilterType.ByHostParameterExistence:
			case FilterType.ByPropertyValue:
			case FilterType.ByTypePropertyValue:
			case FilterType.NestedFamilyInstances:
			case FilterType.ByHostCategories:
				filt.LoadDocument(md.Doc);
				break;
			case FilterType.ByInsulationParameterValue:
			{
				filt.LoadDocument(md.Doc);
				FilterByInsulParamValue filterByInsulParamValue = filt as FilterByInsulParamValue;
				filterByInsulParamValue.LoadData(this.GetAllInsulations(md, options));
				break;
			}
			case FilterType.ByInsulationTypeParameterValue:
			{
				filt.LoadDocument(md.Doc);
				FilterByInsulTypeParamValue filterByInsulTypeParamValue = filt as FilterByInsulTypeParamValue;
				filterByInsulTypeParamValue.LoadData(this.GetAllInsulations(md, options));
				break;
			}
			}
		}
		private List<InsulationLiningBase> GetAllInsulations(ModelData md, ApplyOptions options)
		{
			bool flag = options.ActiveView != null;
			List<InsulationLiningBase> result;
			if (flag)
			{
				result = md.GetElementSet(typeof(InsulationLiningBase), options.ActiveView.Id).Cast<InsulationLiningBase>().ToList<InsulationLiningBase>();
			}
			else
			{
				result = md.GetElementSet(typeof(InsulationLiningBase), null).Cast<InsulationLiningBase>().ToList<InsulationLiningBase>();
			}
			return result;
		}
		public string Description(int columnWidth)
		{
			bool flag = this.AllFilters == null || !this.AllFilters.Any<IFilter>();
			string result;
			if (flag)
			{
				result = "";
			}
			else
			{
				double num = 5.4;
				string text = "; ";
				int num2 = (int)Convert.ToInt16(Math.Round((double)columnWidth / num, 0, MidpointRounding.AwayFromZero));
				string text2 = string.Format("({0})", this.AllFilters.Count);
				int num3 = text2.Length;
