								if (!flag13)
								{
									FilterElementIdRule filterRule3 = new FilterElementIdRule(parameterValueProvider, new FilterNumericEquals(), current2);
									list4.Add(new ElementParameterFilter(filterRule3));
								}
							}
							this.Filter = new LogicalOrFilter(list4);
						}
						else
						{
							FilterElementIdRule filterRule3 = new FilterElementIdRule(parameterValueProvider, new FilterNumericEquals(), ruleValue3);
							this.Filter = new ElementParameterFilter(filterRule3);
						}
					}
					break;
				}
				}
			}
		}
		public static ElementFilter GetStringFilter(ParameterValueProvider pvp, MatchingType matchType, object value)
		{
			ElementFilter result = null;
			string ruleString = "";
			List<string> list = new List<string>();
			List<string> list2 = value as List<string>;
			bool flag = list2 != null;
			if (flag)
			{
				foreach (string current in list2)
				{
					list.AddRange(ElementFilterBase.CaseSensitiveVariants(current));
				}
			}
			else
			{
				string text = value as string;
				bool flag2 = text != null;
				if (flag2)
				{
					ruleString = text;
					list.AddRange(ElementFilterBase.CaseSensitiveVariants(text));
				}
				else
				{
					bool flag3 = RUtil.IsList(value);
					if (flag3)
					{
						foreach (object current2 in (List<object>)value)
						{
							list.AddRange(ElementFilterBase.CaseSensitiveVariants(current2.ToString()));
						}
					}
					else
					{
						ruleString = value.ToString();
						list.AddRange(ElementFilterBase.CaseSensitiveVariants((string)value));
					}
				}
			}
			switch (matchType)
			{
			case MatchingType.Equals:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringEquals(), ruleString, false);
				result = new ElementParameterFilter(filterRule);
				break;
			}
			case MatchingType.NotEquals:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringEquals(), ruleString, false);
				result = new ElementParameterFilter(filterRule, true);
				break;
			}
			case MatchingType.Greater:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringGreater(), ruleString, false);
				result = new ElementParameterFilter(filterRule);
				break;
			}
			case MatchingType.GreaterOrEqual:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringGreaterOrEqual(), ruleString, false);
				result = new ElementParameterFilter(filterRule);
				break;
			}
			case MatchingType.Less:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringLess(), ruleString, false);
				result = new ElementParameterFilter(filterRule);
				break;
			}
			case MatchingType.LessOrEqual:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringLessOrEqual(), ruleString, false);
				result = new ElementParameterFilter(filterRule);
				break;
			}
			case MatchingType.Contains:
			{
				List<ElementFilter> list3 = new List<ElementFilter>();
				foreach (string current3 in list)
				{
					bool flag4 = current3 == null;
					if (!flag4)
					{
						FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringContains(), current3, false);
						ElementParameterFilter item = new ElementParameterFilter(filterRule);
						list3.Add(item);
					}
				}
				result = new LogicalOrFilter(list3);
				break;
			}
			case MatchingType.NotContains:
			{
				List<ElementFilter> list4 = new List<ElementFilter>();
				foreach (string current4 in list)
				{
					bool flag5 = current4 == null;
					if (!flag5)
					{
						FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringContains(), current4, false);
						list4.Add(new ElementParameterFilter(filterRule, true));
					}
				}
				result = new LogicalAndFilter(list4);
				break;
			}
			case MatchingType.BeginsWith:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringBeginsWith(), ruleString, false);
				result = new ElementParameterFilter(filterRule);
				break;
			}
			case MatchingType.NotBeginsWith:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringBeginsWith(), ruleString, false);
				result = new ElementParameterFilter(filterRule, true);
				break;
			}
			case MatchingType.EndsWith:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringEndsWith(), ruleString, false);
				result = new ElementParameterFilter(filterRule);
				break;
			}
			case MatchingType.NotEndsWith:
			{
				FilterStringRule filterRule = RCompatibility.Create(pvp, new FilterStringEndsWith(), ruleString, false);
				result = new ElementParameterFilter(filterRule, true);
				break;
			}
			}
			return result;
		}
		private static List<string> CaseSensitiveVariants(string s)
		{
			bool flag = string.IsNullOrEmpty(s);
			List<string> result;
			if (flag)
			{
				result = new List<string>
				{
					s
				};
			}
			else
			{
				List<string> list = new List<string>
				{
					string.Copy(s),
					string.Copy(s.ToLower()),
					string.Copy(s.ToUpper())
				};
				bool flag2 = s.Length > 1;
				if (flag2)
				{
					list.Add(s.Substring(0, 1).ToUpper() + s.Substring(1, s.Length - 1).ToLower());
				}
				list = list.Distinct<string>().ToList<string>();
				result = list;
			}
			return result;
		}
	}
	internal class FilterByFamilies : ElementFilterBase, IFilter
	{
		public List<string> FamNames;
		public FilterByFamilies(Autodesk.Revit.DB.Document doc, List<string> famNames, bool inverted = false)
		{
			base.Inverted = inverted;
			this.FamNames = famNames;
			this.CreateFilter(doc);
