		public FilterByFamilies(Autodesk.Revit.DB.Document doc, XElement xe) : base(xe)
		{
			bool flag = base.ErrReport != "";
			if (flag)
			{
				this.CreateDescription(null);
			}
			else
			{
				XElement xElement = xe.Element("familyNames");
				bool flag2 = xElement != null;
				if (flag2)
				{
					this.FamNames = new List<string>();
					foreach (XElement current in xElement.Elements("famName"))
					{
						this.FamNames.Add(current.Value);
					}
				}
				this.CreateFilter(doc);
				this.Create();
			}
