		private void Create()
		{
			base.Type = FilterType.ByFamilies;
			this.CreateDescription(null);
		}
		private void CreateFilter(Autodesk.Revit.DB.Document doc)
		{
			bool flag = this.FamNames == null || this.FamNames.Count == 0;
			if (!flag)
			{
				List<ElementId> list = new List<ElementId>();
				foreach (string current in this.FamNames)
				{
					List<ElementId> familyIdsBySubstring = RUtil.GetFamilyIdsBySubstring(doc, current);
					foreach (ElementId current2 in familyIdsBySubstring)
					{
						bool flag2 = current2 != null;
						if (flag2)
						{
							Family family = doc.GetElement(current2) as Family;
							list.AddRange(family.GetFamilySymbolIds());
