				}
				bool inverted = base.Inverted;
				MatchingType matchType;
				if (inverted)
				{
					matchType = MatchingType.NotEquals;
				}
				else
				{
					matchType = MatchingType.Equals;
				}
				bool flag3 = list.Count == 0;
				if (!flag3)
				{
					base.SetElementFilter(new ElementId(-1002051), StorageType.ElementId, list, matchType, null);
				}
			}
		}
		public override void CreateDescription(Autodesk.Revit.DB.Document doc = null)
		{
			base.Description = "";
			bool flag = this.FamNames == null;
			if (flag)
			{
				base.Description = "по имени семейства (??? семейств)";
			}
			else
			{
				base.Description = string.Format("по имени семейства ({0})", this.FamNames.Count);
			}
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			bool flag = this.FamNames != null && this.FamNames.Count > 0;
			if (flag)
			{
				XElement xElement2 = new XElement("familyNames");
				foreach (string current in this.FamNames)
				{
					XElement content = new XElement("famName", current);
					xElement2.Add(content);
				}
				xElement.Add(xElement2);
			}
			return xElement;
		}
	}
