			}
			else
			{
				XElement xElement = xe.Element("type");
				bool flag2 = xElement != null;
				if (flag2)
				{
					this.FType = RUtil.Xml2Type(xElement);
					bool flag3 = this.FType == null;
					if (flag3)
					{
						base.ErrorReturn("не удалось получить тип данных в поле type");
						return;
					}
				}
				base.Filter = new ElementClassFilter(this.FType);
				this.Create();
			}
		}
		private void Create()
		{
			base.Type = FilterType.ByType;
			bool flag = !this.FType.IsSubclassOf(typeof(Element));
			if (flag)
			{
				base.ErrorReturn("переданный тип не является наследником типа Element");
			}
			else
			{
				this.CreateDescription(null);
			}
		}
		public override void CreateDescription(Autodesk.Revit.DB.Document doc = null)
		{
			base.Description = "";
			bool flag = this.FType == null;
			if (flag)
			{
				base.Description = "по классу (??? класс)";
			}
			else
			{
				base.Description = "по классу " + this.FType.Name;
			}
		}
		public static List<ItemComment> GetAllTypes()
		{
			bool flag = FilterByType._allTypes == null;
			if (flag)
			{
				FilterByType._allTypes = new List<ItemComment>();
				Type elt = typeof(Element);
				Type[] types = elt.Assembly.GetTypes();
				List<Type> list = (
					from t in types
					where t.IsSubclassOf(elt)
					select t).ToList<Type>();
				list.Remove(typeof(Room));
				list.Remove(typeof(Space));
				list.Remove(typeof(Area));
				list.Remove(typeof(RoomTag));
				list.Remove(typeof(SpaceTag));
				list.Remove(typeof(AreaTag));
				list.Remove(typeof(CombinableElement));
				list.Remove(typeof(Mullion));
				list.Remove(typeof(Autodesk.Revit.DB.Panel));
				list.Remove(typeof(AreaReinforcementType));
				list.Remove(typeof(PathReinforcementType));
				list.Remove(typeof(AnnotationSymbolType));
				list.Remove(typeof(RoomTagType));
				list.Remove(typeof(SpaceTagType));
				list.Remove(typeof(AreaTagType));
				list.Remove(typeof(TrussType));
				IEnumerable<Type> enumerable = FilterByType.Remove(list, typeof(Material));
				enumerable = FilterByType.Remove(enumerable, typeof(CurveElement));
				enumerable = FilterByType.Remove(enumerable, typeof(ConnectorElement));
				enumerable = FilterByType.Remove(enumerable, typeof(HostedSweep));
				list = enumerable.ToList<Type>();
				foreach (Type current in list)
				{
					string name = current.Name;
					FilterByType._allTypes.Add(new ItemComment(current, name));
				}
			}
			return FilterByType._allTypes;
		}
		private static IEnumerable<Type> Remove(IEnumerable<Type> types, Type baseType)
		{
			return types.Except(
				from t in types
				where t.IsSubclassOf(baseType)
				select t);
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = this.Convert2Xml();
			bool flag = this.FType != null;
			if (flag)
			{
				XElement xElement2 = new XElement("type");
				xElement2 = RUtil.Type2Xml(this.FType, xElement2);
				xElement.Add(xElement2);
			}
			return xElement;
		}
	}
