				FrmSelectParam3 frmSelectParam;
				if (isNewRule)
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._parentXpath, null, true);
				}
				else
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._parentXpath, this.Param, true);
				}
				frmSelectParam.ShowDialog();
				bool flag2 = frmSelectParam.DialogResult == DialogResult.OK;
				if (flag2)
				{
					this.Param = new ParamId(frmSelectParam.SelectedParam);
					this.ParamChanged();
				}
			}
		}
		private void SelectItem(ForgeTypeId unit)
		{
			ItemComment itemComment = this.cmbDUT.Items.Cast<ItemComment>().FirstOrDefault((ItemComment x) => (ForgeTypeId)x.Item == unit);
			bool flag = itemComment != null;
			if (flag)
			{
				this.cmbDUT.SelectedItem = itemComment;
			}
			else
			{
				this.cmbDUT.SelectedIndex = -1;
			}
		}
