					"меньше",
					"меньше или равно"
				};
				this.Hide(this.dgvValues);
				this.Show(this.txtValue);
				this.grpConvert.Visible = true;
				break;
			}
			case StorageType.String:
			{
				Label expr_12A = this.lblStorageType;
				expr_12A.Text += "строка";
				array = Matching.AllMatchTypes.Values.ToArray<string>();
				this.Hide(this.txtValue);
				this.Show(this.dgvValues);
				this.grpConvert.Visible = false;
				break;
