		private void btnOk_Click(object sender, EventArgs e)
		{
			bool flag = this.cmbMatchType.SelectedItem != null;
			if (flag)
			{
				this.MatchType = Matching.AllMatchTypes.FirstOrDefault((KeyValuePair<MatchingType, string> x) => x.Value == (string)this.cmbMatchType.SelectedItem).Key;
			}
			bool flag2 = this.rdoConvertTo.Checked && this.cmbDUT.SelectedItem != null;
			if (flag2)
			{
				this.Unit = (((ItemComment)this.cmbDUT.SelectedItem).Item as ForgeTypeId);
			}
			else
			{
				this.Unit = null;
			}
			this.dgvValues.EndEdit();
			switch (this.ST)
			{
			case StorageType.None:
				this.Value = null;
				break;
			case StorageType.Integer:
			{
				int num = 0;
				bool flag3 = int.TryParse(this.txtValue.Text, out num);
				if (!flag3)
				{
					MessageBox.Show("Укажите целое число в качестве значения.");
					return;
				}
				this.Value = num;
				break;
			}
			case StorageType.Double:
			{
				double num2 = 0.0;
				bool flag4 = double.TryParse(this.txtValue.Text, out num2);
				if (!flag4)
				{
					MessageBox.Show("Укажите вещественное число в качестве значения.");
					return;
				}
				this.Value = num2;
				break;
			}
			case StorageType.String:
			{
				bool flag5 = this.dgvValues.Rows.Count == 1;
				if (flag5)
				{
					this.Value = null;
				}
				else
				{
					bool flag6 = this.dgvValues.Rows.Count == 2;
					if (flag6)
					{
						this.Value = (this.dgvValues.Rows[0].Cells[this.colValues.Index].Value as string);
					}
					else
					{
						List<string> list = new List<string>();
						foreach (DataGridViewRow dataGridViewRow in (IEnumerable)this.dgvValues.Rows)
						{
							bool isNewRow = dataGridViewRow.IsNewRow;
							if (!isNewRow)
							{
								list.Add(dataGridViewRow.Cells[this.colValues.Index].Value as string);
							}
						}
						this.Value = list;
					}
				}
				break;
			}
			case StorageType.ElementId:
			{
				bool flag7 = this.dgvValues.Rows.Count == 1;
				if (flag7)
				{
					this.Value = null;
				}
				else
				{
					bool flag8 = this.dgvValues.Rows.Count == 2;
					if (flag8)
					{
						int id = int.Parse(this.dgvValues.Rows[0].Cells[this.colValues.Index].Value as string);
						this.Value = new ElementId(id);
					}
					else
					{
						List<ElementId> list2 = new List<ElementId>();
						foreach (DataGridViewRow dataGridViewRow2 in (IEnumerable)this.dgvValues.Rows)
						{
							bool isNewRow2 = dataGridViewRow2.IsNewRow;
							if (!isNewRow2)
							{
								int id2 = int.Parse(dataGridViewRow2.Cells[this.colValues.Index].Value as string);
								list2.Add(new ElementId(id2));
							}
						}
						this.Value = list2;
					}
				}
				break;
			}
			}
			base.DialogResult = DialogResult.OK;
			base.Close();
		}
		private void txtValue_Validating(object sender, CancelEventArgs e)
		{
			this._errP.SetIconAlignment(this.txtValue, ErrorIconAlignment.MiddleRight);
			this._errP.SetIconPadding(this.txtValue, 2);
			this._errP.SetError(this.txtValue, string.Empty);
			StorageType sT = this.ST;
			StorageType storageType = sT;
			if (storageType != StorageType.Integer)
			{
				if (storageType == StorageType.Double)
				{
					string value = "Здесь должно быть вещественное число.";
					double num = 0.0;
					bool flag = !double.TryParse(this.txtValue.Text, out num);
					if (flag)
					{
						this._errP.SetError(this.txtValue, value);
						e.Cancel = true;
					}
				}
			}
			else
			{
				string value = "Здесь должно быть целое число.";
				int num2 = 0;
				bool flag2 = !int.TryParse(this.txtValue.Text, out num2);
				if (flag2)
				{
					this._errP.SetError(this.txtValue, value);
					e.Cancel = true;
				}
			}
		}
