		public List<Element> GetFiltered(List<Element> elems)
		{
			List<Element> list = new List<Element>();
			bool flag = elems == null || elems.Count == 0;
			List<Element> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				foreach (Element current in elems)
				{
					FamilyInstance familyInstance = current as FamilyInstance;
					bool flag2 = familyInstance == null;
					if (!flag2)
					{
						bool flag3 = !familyInstance.IsValidObject;
						if (!flag3)
						{
							Autodesk.Revit.DB.Parameter parameter = familyInstance.Symbol.Family.get_Parameter(BuiltInParameter.FAMILY_CONTENT_PART_TYPE);
							bool flag4 = parameter == null;
							if (!flag4)
							{
								PartType partType = (PartType)parameter.AsInteger();
								bool flag5 = this.PartType == partType;
								if (flag5)
								{
									list.Add(current);
									Debug.Print(current.Description());
								}
							}
						}
					}
				}
				result = list;
			}
			return result;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			bool flag = this.PartType != PartType.Undefined;
			if (flag)
			{
				xElement.Add(new XElement("partType", this.PartType));
			}
			return xElement;
		}
	}
