	internal class FilterBase
	{
		public Autodesk.Revit.DB.Document Doc;
		private const string _FILTER = "filter";
		private const string _FILTER_TYPE = "filterType";
		public FilterType Type
		{
			get;
			set;
		}
		public string ErrReport
		{
			get;
			set;
		}
		public string Description
		{
			get;
			set;
		}
		public FilterBase()
		{
			this.ErrReport = "";
			this.Description = "";
			
			this.ErrReport = "";
		}
		public void LoadDocument(Autodesk.Revit.DB.Document doc)
		{
			this.Doc = doc;
		}
		public FilterBase(XElement xe)
		{
			this.ErrReport = "";
			this.Description = "";
			
			string errReport;
			this.Type = FilterBase.GetFilterType(xe, out errReport);
			this.ErrReport = errReport;
		}
		public virtual XElement Convert2Xml()
		{
			XElement xElement = new XElement("filter", new XAttribute("filterType", this.Type));
			bool flag = !string.IsNullOrEmpty(this.ErrReport);
			if (flag)
			{
				xElement.Add(new XElement("errorReport", this.ErrReport));
			}
			return xElement;
		}
		public void ErrorReturn(string errMsg)
		{
			this.ErrReport = errMsg;
			this.CreateDescription(null);
		}
		public virtual void CreateDescription(Autodesk.Revit.DB.Document doc = null)
		{
		}
		public static FilterType GetFilterType(XElement xe, out string errReport)
		{
			string text = "не удалось получить описание фильтра из xml-файла";
			string text2 = "не удалось определить тип фильтра";
			errReport = "";
			FilterType filterType = FilterType.Unknown;
			bool flag = xe == null || xe.Name != "filter";
			FilterType result;
			if (flag)
			{
				errReport = text;
				result = filterType;
			}
			else
			{
				XAttribute xAttribute = xe.Attribute("filterType");
				bool flag2 = xAttribute == null;
				if (flag2)
				{
					errReport = text2;
					result = filterType;
				}
				else
				{
					FilterType filterType2;
					bool flag3 = Enum.TryParse<FilterType>(xAttribute.Value, true, out filterType2);
					if (flag3)
					{
						bool flag4 = Enum.IsDefined(typeof(FilterType), filterType2);
						if (flag4)
						{
							filterType = filterType2;
							result = filterType;
						}
						else
						{
							errReport = text2;
							result = filterType;
						}
					}
					else
					{
						errReport = text2;
						result = filterType;
					}
				}
			}
			return result;
		}
	}
	internal class FilterByParameterExistence : FilterBase, IFilter
	{
		public ParamId Id
		{
			get;
			private set;
		}
		public FilterByParameterExistence(ParamId param)
		{
			base.Type = FilterType.ByParameterExistence;
			this.Id = param;
			this.Create();
		}
		public FilterByParameterExistence(XElement xe) : base(xe)
		{
			bool flag = base.ErrReport != "";
			if (flag)
			{
				this.CreateDescription();
			}
			else
			{
				string errReport;
				XElement xElement = ParamId.CompatibilityCheck(xe, out errReport);
				bool flag2 = xElement == null;
				if (flag2)
				{
					this.CreateDescription();
					base.ErrReport = errReport;
				}
				else
				{
					this.Id = new ParamId(xElement);
					bool flag3 = this.Id.ErrReport != "";
					if (flag3)
					{
						this.CreateDescription();
						base.ErrReport = this.Id.ErrReport;
					}
					else
					{
						this.Create();
					}
				}
			}
		}
		private void Create()
		{
			bool flag = this.Id == null;
			if (flag)
			{
				base.ErrReport = "нет данных о параметре";
			}
			else
			{
				this.CreateDescription();
			}
		}
		private void CreateDescription()
		{
			string str = "";
			bool flag = this.Id != null;
			if (flag)
			{
				this.Id.SetDescription1();
				str = this.Id.Comment;
			}
			base.Description = "по наличию параметра '" + str + "'";
		}
		public List<Element> GetFiltered(List<Element> elems)
		{
			List<Element> list = new List<Element>();
			bool flag = elems == null || elems.Count == 0;
			List<Element> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				foreach (Element current in elems)
				{
					Autodesk.Revit.DB.Parameter parameter = this.Id.GetParameter(current);
					bool flag2 = parameter != null;
					if (flag2)
					{
						list.Add(current);
					}
				}
				result = list;
			}
			return result;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			bool flag = this.Id != null;
			if (flag)
			{
				xElement.Add(this.Id.Convert2Xml());
			}
			return xElement;
		}
	}
