		public FrmParamValue(Engine engine, string title, XElement xeFragment = null)
		{
			this._engine = engine;
			this.InitializeComponent();
			this.Text = title;
			this._resultHandler = new ResultHandler(this.chkConvertTo, this.cmbDUT, this.chkRoundTo, this.cmbRoundDecimal, this.lblRoundTo, this._engine.AllUnits);
			this._state = new FormExt_State(this, this._engine.PluginXPath, 579, 414);
			this._state.SetPostConfigAction(new PostConfigAction(this._resultHandler.Config));
			this._state.SetPostSavingAction(new PostSavingAction(this._resultHandler.SaveTo));
			this._state.ConfigRead();
			this._isNewRule = (xeFragment == null);
			bool flag = xeFragment != null;
			if (flag)
			{
				FragmentParam fragmentParam = new FragmentParam(xeFragment);
				this.ParamData = fragmentParam.ParamData;
				this.Mode = fragmentParam.Mode;
				this.txtParam.Text = ((this.ParamData.Id.Name != "") ? this.ParamData.Id.Name : this.ParamData.Id.Comment);
				this._resultHandler.UpdateControls(fragmentParam.ParamData.FTid, fragmentParam.ParamData.RoundDecimal);
			}
			else
			{
				this.ParamData = new ParamData();
				this.txtParam.Text = "<не выбран>";
				this.Mode = ParamGettingMode.Self;
			}
			switch (this.Mode)
			{
			case ParamGettingMode.Self:
				this.rdoSelf.Checked = true;
				break;
			case ParamGettingMode.Type:
				this.rdoType.Checked = true;
				break;
			case ParamGettingMode.Host:
				this.rdoHost.Checked = true;
				break;
			case ParamGettingMode.HostType:
				this.rdoHostType.Checked = true;
				break;
			case ParamGettingMode.Parent:
				this.rdoParent.Checked = true;
				break;
			}
		}
		private void btnSelectParam_Click(object sender, EventArgs e)
		{
			List<ParamId> allParams = this._engine.Model.GetAllParams(StorageType.None, false);
			bool flag = allParams == null || !allParams.Any<ParamId>();
			if (flag)
			{
				MessageBox.Show("Не удалось получить параметры из проекта.");
			}
			else
			{
				bool isNewRule = this._isNewRule;
				FrmSelectParam3 frmSelectParam;
				if (isNewRule)
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, null, true);
				}
				else
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, this.ParamData.Id, true);
				}
				frmSelectParam.ShowDialog();
				bool flag2 = frmSelectParam.DialogResult == DialogResult.OK;
				if (flag2)
				{
					this.ParamData.Id = new ParamId(frmSelectParam.SelectedParam);
					this.txtParam.Text = this.ParamData.Id.Name;
				}
			}
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			this._resultHandler.UpdateValues();
			this.ParamData.FTid = this._resultHandler.Unit;
			this.ParamData.RoundDecimal = this._resultHandler.RoundDecimal;
			base.DialogResult = DialogResult.OK;
			base.Close();
		}
		private void rdoSelf_CheckedChanged(object sender, EventArgs e)
		{
			this.ModeChanged();
		}
		private void rdoType_CheckedChanged(object sender, EventArgs e)
		{
			this.ModeChanged();
		}
