		{
			this.ModeChanged();
		}
		private void ModeChanged()
		{
			bool @checked = this.rdoSelf.Checked;
			if (@checked)
			{
				this.Mode = ParamGettingMode.Self;
			}
			else
			{
				bool checked2 = this.rdoType.Checked;
				if (checked2)
				{
					this.Mode = ParamGettingMode.Type;
				}
				else
				{
					bool checked3 = this.rdoHost.Checked;
					if (checked3)
					{
						this.Mode = ParamGettingMode.Host;
					}
					else
					{
						bool checked4 = this.rdoHostType.Checked;
						if (checked4)
						{
							this.Mode = ParamGettingMode.HostType;
						}
						else
						{
							bool checked5 = this.rdoParent.Checked;
							if (checked5)
							{
								this.Mode = ParamGettingMode.Parent;
							}
						}
					}
				}
			}
		}
