									Log.Write(ex2);
									num2++;
								}
							}
							progressForm.Increment();
						}
					}
				}
				bool flag9 = num2 > 0;
				if (flag9)
				{
					report += string.Format("Не удалось изменить тип у {0} элементов. Подробности в журнале", num2);
