	internal class Buffer
	{
		private readonly List<int> _gaps;
		private readonly List<int> _indexes;
		public List<XElement> RulesInXml
		{
			get;
			private set;
		}
		public Buffer()
		{
			this.RulesInXml = new List<XElement>();
			this._gaps = new List<int>();
			this._indexes = new List<int>();
		}
		public void AddRules(Autodesk.Revit.DB.Document doc, List<Rule> allRules, List<int> selIndexes)
		{
			this.RulesInXml.Clear();
			this._gaps.Clear();
			this._indexes.Clear();
			selIndexes.Sort();
			this._indexes.AddRange(selIndexes);
			int num = -1;
			using (List<int>.Enumerator enumerator = selIndexes.GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					int index = enumerator.Current;
					Rule rule = allRules.Find((Rule r) => r.Index == index);
					bool flag = rule != null;
					if (flag)
					{
						bool flag2 = num != -1;
						if (flag2)
						{
							int item = index - num;
							this._gaps.Add(item);
						}
						num = index;
						this.RulesInXml.Add(rule.Convert2Xml());
					}
				}
			}
		}
		public static bool IsCompact(List<int> selIndexes)
		{
			selIndexes.Sort();
			int num = -1;
			bool result = false;
			foreach (int current in selIndexes)
			{
				bool flag = num != -1;
				if (flag)
				{
					int num2 = current - num;
					bool flag2 = num2 > 1;
					if (flag2)
					{
						result = false;
						return result;
					}
				}
				num = current;
			}
			result = true;
			return result;
		}
		public bool IsEqualGaps(List<int> selIndexes)
		{
			selIndexes.Sort();
			List<int> list = new List<int>();
			int num = -1;
			foreach (int current in selIndexes)
			{
				bool flag = num != -1;
				if (flag)
				{
					list.Add(current - num);
				}
				num = current;
			}
			return this._gaps.SequenceEqual(list);
		}
		public bool HasOverlays(List<int> selIndexes)
		{
			bool flag = selIndexes == null || !selIndexes.Any<int>();
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				bool flag2 = !this._indexes.Any<int>();
				result = (!flag2 && this._indexes.Intersect(selIndexes).Any<int>());
			}
			return result;
		}
	}
	internal class FrmFragment2Params : System.Windows.Forms.Form
