		{
			get;
			private set;
		}
		public FrmFragment2Params(Engine engine, string title, string param1text, string param2text, XElement xeFragment = null)
		{
			this._engine = engine;
			this.InitializeComponent();
			this.Text = title;
			this.grpParam1.Text = param1text;
			this.grpParam2.Text = param2text;
			this.ResultHandler = new ResultHandler(this.chkConvertTo, this.cmbDUT, this.chkRoundTo, this.cmbRoundDecimal, this.lblRoundTo, this._engine.AllUnits);
			this._state = new FormExt_State(this, this._engine.PluginXPath, 586, 254);
			this._state.SetPostConfigAction(new PostConfigAction(this.ResultHandler.Config));
			this._state.SetPostSavingAction(new PostSavingAction(this.ResultHandler.SaveTo));
			this._state.ConfigRead();
			bool flag = xeFragment != null;
			if (flag)
			{
				FragmentSumSystemParam fragmentSumSystemParam = new FragmentSumSystemParam(xeFragment, this._engine.Model);
				this.Param1 = fragmentSumSystemParam.TotalParam;
				bool flag2 = this.Param1.Name != "";
				if (flag2)
				{
					this.txtParam1.Text = this.Param1.Name;
				}
				else
				{
					this.txtParam1.Text = this.Param1.Comment;
				}
				this.Param2 = fragmentSumSystemParam.SysParam;
				bool flag3 = this.Param2.Name != "";
				if (flag3)
				{
					this.txtParam2.Text = this.Param2.Name;
				}
				else
				{
					this.txtParam2.Text = this.Param2.Comment;
				}
				this.ResultHandler.UpdateControls(fragmentSumSystemParam.FTid, fragmentSumSystemParam.RoundDecimal);
			}
			else
			{
				this._isNewFrag = true;
				this.Param1 = null;
				this.txtParam1.Text = "<не выбран>";
				this.Param2 = null;
				this.txtParam2.Text = "<не выбран>";
			}
		}
		private void btnSelectParam1_Click(object sender, EventArgs e)
		{
			List<ParamId> allParams = this._engine.Model.GetAllParams(StorageType.None, false);
			bool flag = allParams == null || !allParams.Any<ParamId>();
			if (flag)
			{
				MessageBox.Show("Не удалось получить параметры из проекта.");
			}
			else
			{
				bool isNewFrag = this._isNewFrag;
				FrmSelectParam3 frmSelectParam;
				if (isNewFrag)
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, null, true);
				}
				else
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, this.Param1, true);
				}
				frmSelectParam.ShowDialog();
				bool flag2 = frmSelectParam.DialogResult == DialogResult.OK;
				if (flag2)
				{
					this.Param1 = new ParamId(frmSelectParam.SelectedParam);
					this.txtParam1.Text = this.Param1.Name;
				}
			}
		}
