	[Transaction(TransactionMode.Manual)]
	public class CmdRuler : IExternalCommand
	{
		public Autodesk.Revit.UI.Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			UIDocument activeUIDocument = commandData.Application.ActiveUIDocument;
			FormExt.SetRevitWindow(commandData.Application);
			bool isFamilyDocument = activeUIDocument.Document.IsFamilyDocument;
			Autodesk.Revit.UI.Result result;
			if (isFamilyDocument)
			{
				MessageBox.Show("Плагин не может быть запущен, так как текущий открытый документ является семейством, а не проектом.");
				result = Autodesk.Revit.UI.Result.Succeeded;
			}
			else
			{
				Engine engine = new Engine(activeUIDocument, "ParamRules/Editor");
				bool flag = engine.ErrReport != "";
				if (flag)
				{
					MessageBox.Show(engine.ErrReport);
					Log.Write(engine.ErrReport);
					result = Autodesk.Revit.UI.Result.Succeeded;
				}
				else
				{
					FrmRuler frmRuler = new FrmRuler(engine);
					frmRuler.ShowDialog();
					result = Autodesk.Revit.UI.Result.Succeeded;
				}
			}
			return result;
		}
	}
