			this.Argument = (IArgument)frag;
		}
		public CalcOperation(XElement xe, ModelData md)
		{
			this.ErrReport = "";
			bool flag = xe == null || xe.Name != "operation";
			if (flag)
			{
				this.ErrReport = "переданный элемент не является операцией";
			}
			else
			{
				string errReport = "не удалось определить тип арифметической операции";
				XAttribute xAttribute = xe.Attribute("type");
				bool flag2 = xAttribute == null;
				if (flag2)
				{
					this.ErrReport = errReport;
				}
				else
				{
					Operation operation;
					bool flag3 = Enum.TryParse<Operation>(xAttribute.Value, true, out operation);
					if (flag3)
					{
						bool flag4 = Enum.IsDefined(typeof(Operation), operation);
						if (flag4)
						{
							this.Type = operation;
							XElement xElement = xe.Element("argument");
							bool flag5 = xElement == null;
							if (flag5)
							{
								this.ErrReport = "не найден узел аргумента в узле операции";
							}
							else
							{
								XElement xElement2 = xElement.Element("fragment");
								bool flag6 = xElement2 == null;
								if (flag6)
								{
									XElement xElement3 = xElement.Element("scalar");
									bool flag7 = xElement3 == null;
									if (flag7)
									{
										this.ErrReport = "не удалось получить аргумент арифметической операции";
										return;
									}
									this.Argument = new Scalar(xElement3);
								}
								else
								{
									string text;
									this.Argument = (ActionParam.CreateFragment(xElement2, md, out text) as IArgument);
								}
								bool flag8 = this.Argument.ErrReport != "";
								if (flag8)
								{
									this.ErrReport = this.Argument.ErrReport;
								}
							}
						}
						else
						{
							this.ErrReport = errReport;
						}
					}
					else
					{
						this.ErrReport = errReport;
					}
				}
			}
		}
		public object Calc(object arg1, ModelData md, Element e)
		{
			bool flag = arg1 == null;
			object result;
			if (flag)
			{
				result = null;
			}
			else
			{
				object value = this.Argument.GetValue(md, e);
				bool flag2 = value == null;
				if (flag2)
				{
					result = null;
				}
				else
				{
					switch (this.Type)
					{
					case Operation.Add:
						result = Calculator3.Add(arg1, value);
						break;
					case Operation.Multiply:
						result = Calculator3.Multiply(arg1, value);
						break;
					case Operation.Subtraction:
						result = Calculator3.Subtract(arg1, value);
						break;
					case Operation.Division:
					{
						int num = 0;
						bool arg_90_0 = false;
						if (value is int)
						{
							num = (int)value;
							arg_90_0 = true;
						}
						else
						{
							arg_90_0 = false;
						}
						bool flag3 = arg_90_0;
						if (flag3)
						{
							bool flag4 = num == 0;
							if (flag4)
							{
								this.ErrReport = "деление на ноль";
								result = null;
								break;
							}
						}
						else
						{
							double num2 = 0.0;
							bool arg_CA_0 = false;
							if (value is double)
							{
								num2 = (double)value;
								arg_CA_0 = true;
							}
							else
							{
								arg_CA_0 = false;
							}
							bool flag5 = arg_CA_0;
							if (!flag5)
							{
								result = null;
								break;
							}
							bool flag6 = num2 == 0.0;
							if (flag6)
							{
								this.ErrReport = "деление на ноль";
								result = null;
								break;
							}
						}
						result = Calculator3.Divide(arg1, value);
						break;
					}
					default:
						result = null;
						break;
					}
				}
			}
			return result;
		}
		public string GetDescritionLong()
		{
			string text = "";
			switch (this.Type)
			{
			case Operation.Add:
				text += "+";
				break;
			case Operation.Multiply:
				text += "*";
				break;
			case Operation.Subtraction:
				text += "-";
				break;
			case Operation.Division:
				text += "/";
				break;
			}
			text += " ";
			bool flag = this.Argument != null;
			if (flag)
			{
				text += this.Argument.DescriptionLong;
			}
			return text;
		}
		public XElement Convert2Xml()
		{
			XElement xElement = new XElement("operation", new XAttribute("type", this.Type));
			XElement xElement2 = new XElement("argument");
			xElement2.Add(this.Argument.Convert2Xml());
			xElement.Add(xElement2);
			return xElement;
		}
	}
