		public FrmConst(string pluginXPath, string title, object literal = null)
		{
			this.Literal = literal;
			this._errP = new ErrorProvider();
			this.InitializeComponent();
			this.Text = title;
			this._state = new FormExt_State(this, pluginXPath, 444, 412);
			this._state.ConfigRead();
			this.rdoTrue.Checked = true;
			this.rdoString.Checked = true;
			this.txtString.Text = "";
			this.txtInt.Text = "0";
			this.txtDouble.Text = "0";
			bool flag = literal != null;
			if (flag)
			{
				bool flag2 = this.Literal is bool;
				if (flag2)
				{
					this.rdoBoolean.Checked = true;
					this.rdoTrue.Checked = Convert.ToBoolean(this.Literal);
				}
				else
				{
					bool flag3 = this.Literal is int;
					if (flag3)
					{
						this.rdoInt.Checked = true;
						this.txtInt.Text = this.Literal.ToString();
					}
					else
					{
						bool flag4 = this.Literal is double;
						if (flag4)
						{
							this.rdoDouble.Checked = true;
							this.txtDouble.Text = this.Literal.ToString();
						}
						else
						{
							this.rdoString.Checked = true;
							this.txtString.Text = this.Literal.ToString();
						}
					}
				}
			}
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			bool @checked = this.rdoString.Checked;
			if (@checked)
			{
				this.Literal = this.txtString.Text;
			}
			else
			{
				bool checked2 = this.rdoInt.Checked;
				if (checked2)
				{
					this.Literal = int.Parse(this.txtInt.Text);
				}
				else
				{
					bool checked3 = this.rdoDouble.Checked;
					if (checked3)
					{
						double num = 0.0;
						bool flag = this.txtDouble.Text.Try2Double(out num);
						if (flag)
						{
							this.Literal = num;
						}
					}
					else
					{
						bool checked4 = this.rdoBoolean.Checked;
						if (checked4)
						{
							this.Literal = this.rdoTrue.Checked;
						}
					}
				}
			}
			base.DialogResult = DialogResult.OK;
			base.Close();
		}
