	internal class FrmParam : System.Windows.Forms.Form
	{
		private ResultHandler _resultHandler;
		private readonly FormExt_State _state;
		private readonly Engine _engine;
		private readonly bool _isNewRule = false;
		private IContainer components = null;
		public Button btnOk;
		public Button btnCancel;
		private System.Windows.Forms.Panel pnlButtons;
		private TableLayoutPanel tlpMain;
		private GroupBox grpParam;
		private System.Windows.Forms.TextBox txtParam;
		private Button btnSelectParam;
		private GroupBox grpResult;
		private System.Windows.Forms.ComboBox cmbRoundDecimal;
		private System.Windows.Forms.ComboBox cmbDUT;
		private Label lblRoundTo;
		private CheckBox chkConvertTo;
		private CheckBox chkRoundTo;
		public ParamData ParamData
		{
			get;
			private set;
		}
		public FrmParam(Engine engine, string title, ParamData paramData = null)
		{
			this._engine = engine;
			this.ParamData = paramData;
			bool flag = paramData == null;
			if (flag)
			{
				this.ParamData = new ParamData();
			}
			this.InitializeComponent();
			this.Text = title;
			this._resultHandler = new ResultHandler(this.chkConvertTo, this.cmbDUT, this.chkRoundTo, this.cmbRoundDecimal, this.lblRoundTo, this._engine.AllUnits);
			this._state = new FormExt_State(this, this._engine.PluginXPath, 579, 208);
			this._state.SetPostConfigAction(new PostConfigAction(this._resultHandler.Config));
			this._state.SetPostSavingAction(new PostSavingAction(this._resultHandler.SaveTo));
			this._state.ConfigRead();
			this._isNewRule = (paramData == null);
			bool flag2 = this.ParamData.Id == null;
			if (flag2)
			{
				this.txtParam.Text = "<не выбран>";
			}
			else
			{
				this.txtParam.Text = ((this.ParamData.Id.Name != "") ? this.ParamData.Id.Name : this.ParamData.Id.Comment);
			}
			this._resultHandler.UpdateControls(this.ParamData.FTid, this.ParamData.RoundDecimal);
		}
		private void btnSelectParam_Click(object sender, EventArgs e)
		{
			List<ParamId> allParams = this._engine.Model.GetAllParams(StorageType.None, false);
			bool flag = allParams == null || !allParams.Any<ParamId>();
			if (flag)
			{
				MessageBox.Show("Не удалось получить параметры из проекта.");
			}
			else
			{
				bool isNewRule = this._isNewRule;
				FrmSelectParam3 frmSelectParam;
				if (isNewRule)
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, null, true);
				}
				else
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, this.ParamData.Id, true);
				}
				frmSelectParam.ShowDialog();
				bool flag2 = frmSelectParam.DialogResult == DialogResult.OK;
				if (flag2)
				{
					this.ParamData.Id = new ParamId(frmSelectParam.SelectedParam);
					this.txtParam.Text = this.ParamData.Id.Name;
				}
			}
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			this._resultHandler.UpdateValues();
			this.ParamData.FTid = this._resultHandler.Unit;
			this.ParamData.RoundDecimal = this._resultHandler.RoundDecimal;
			base.DialogResult = DialogResult.OK;
			base.Close();
		}
		protected override void Dispose(bool disposing)
		{
			bool flag = disposing && this.components != null;
			if (flag)
			{
				this.components.Dispose();
			}
			base.Dispose(disposing);
		}
		private void InitializeComponent()
		{
			this.btnOk = new Button();
			this.btnCancel = new Button();
			this.pnlButtons = new System.Windows.Forms.Panel();
			this.tlpMain = new TableLayoutPanel();
			this.btnSelectParam = new Button();
			this.grpParam = new GroupBox();
			this.txtParam = new System.Windows.Forms.TextBox();
			this.grpResult = new GroupBox();
			this.cmbRoundDecimal = new System.Windows.Forms.ComboBox();
			this.cmbDUT = new System.Windows.Forms.ComboBox();
			this.lblRoundTo = new Label();
			this.chkConvertTo = new CheckBox();
			this.chkRoundTo = new CheckBox();
			this.pnlButtons.SuspendLayout();
