	{
		public const string MAIN_NODE = "interOptions";
		private const string _SHOW_FILTERS_RESULT = "showFiltersResult";
		public bool ShowFiltersResult
		{
			get;
			set;
		}
		public string ErrReport
		{
			get;
			private set;
		}
		public InterOptions(bool showFiltersResult)
		{
			this.ShowFiltersResult = showFiltersResult;
		}
		public InterOptions(XElement xe)
		{
			this.ErrReport = "";
			bool flag = xe == null || string.IsNullOrEmpty(xe.Value) || xe.Name != "interOptions";
			if (flag)
			{
				this.ErrReport = "не найден узел с настройками интерфейса";
			}
			else
			{
				SAV.Extension.Result result = xe.Parse<bool>("showFiltersResult", false);
				bool ok = result.Ok;
				if (ok)
				{
					this.ShowFiltersResult = (bool)result.Value;
				}
				else
