					this.ErrReport = result.ErrMsg;
				}
			}
		}
		public XElement Convert2Xml()
		{
			XElement xElement = new XElement("interOptions");
			xElement.Add(new XElement("showFiltersResult", this.ShowFiltersResult));
			return xElement;
		}
	}
	internal enum ActionType
	{
		SetParamValue,
		SetWorkset,
		ChangeType,
		Unknown
	}
	internal abstract class Action
	{
		public ActionType Type;
		public const string MAIN_NODE = "action";
		private const string _ACTION_TYPE = "actionType";
		public string ErrReport
		{
			get;
			set;
		}
		public bool IsChanged
		{
			get;
			set;
		}
		public Action()
		{
			this.ErrReport = "";
			
			this.IsChanged = false;
		}
		public Action(XElement xe)
		{
			this.ErrReport = "";
			
			bool flag = xe == null || xe.Name != "action";
			if (flag)
			{
				this.ErrReport = "переданный элемент не является правилом";
			}
			else
			{
				string text;
				this.Type = Action.GetActionType(xe, out text);
				bool flag2 = text != "";
				if (flag2)
				{
					this.ErrReport = text;
				}
			}
		}
		public abstract int Apply(ModelData md, IList<Element> elems, ApplyOptions options, out string report);
		public abstract string Apply(ModelData md, Element elem, ApplyOptions options);
		public virtual XElement Convert2Xml()
		{
			XElement xElement = new XElement("action", new XAttribute("actionType", this.Type));
			xElement.Add(new XElement("errorReport", this.ErrReport));
			return xElement;
		}
		public abstract string Description();
		public static ActionType GetActionType(XElement xe, out string errReport)
		{
			string text = "не удалось получить описание операции из xml-файла";
			string text2 = "не удалось определить тип операции";
			errReport = "";
			ActionType actionType = ActionType.Unknown;
			bool flag = xe == null || xe.Name != "action";
			ActionType result;
			if (flag)
			{
				errReport = text;
				result = actionType;
			}
			else
			{
				XAttribute xAttribute = xe.Attribute("actionType");
				bool flag2 = xAttribute == null;
				if (flag2)
				{
					errReport = text2;
					result = actionType;
				}
				else
				{
					ActionType actionType2;
					bool flag3 = Enum.TryParse<ActionType>(xAttribute.Value, true, out actionType2);
					if (flag3)
					{
						bool flag4 = Enum.IsDefined(typeof(ActionType), actionType2);
						if (flag4)
						{
							actionType = actionType2;
							result = actionType;
						}
						else
						{
							errReport = text2;
							result = actionType;
						}
					}
					else
					{
						errReport = text2;
						result = actionType;
					}
				}
			}
			return result;
		}
	}
	internal class ActionWorkset : Action
	{
		private const string _WORKSET_NAME = "worksetName";
		private const string _WORKSET_ID = "worksetId";
		private const string _DESC = "desc";
		public string WorksetName
		{
			get;
			set;
		}
		public WorksetId Id
		{
			get;
			private set;
		}
		public ActionWorkset()
		{
			this.BaseConstructor();
		}
		public ActionWorkset(string worksetName)
		{
			this.BaseConstructor();
			this.WorksetName = worksetName;
		}
		public ActionWorkset(WorksetId id)
		{
			this.BaseConstructor();
			this.Id = id;
		}
		private void BaseConstructor()
		{
			this.Type = ActionType.SetWorkset;
			this.WorksetName = "";
			this.Id = WorksetId.InvalidWorksetId;
		}
		public ActionWorkset(XElement xe) : base(xe)
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				this.WorksetName = "";
				XAttribute xAttribute = xe.Attribute("worksetName");
				bool flag2 = xAttribute == null;
				if (flag2)
				{
					XAttribute xAttribute2 = xe.Attribute("worksetId");
					bool flag3 = xAttribute2 == null;
					if (flag3)
					{
						base.ErrReport = "не удалось получить данные о рабочем наборе";
					}
					else
					{
						int id = 0;
						bool flag4 = int.TryParse(xAttribute2.Value, out id);
						if (flag4)
						{
							this.Id = new WorksetId(id);
							bool flag5 = this.Id == WorksetId.InvalidWorksetId;
							if (flag5)
							{
								base.ErrReport = "не удалось получить WorksetId";
							}
						}
						else
						{
							base.ErrReport = "не удалось получить WorksetId";
						}
					}
				}
				else
				{
					this.WorksetName = xAttribute.Value;
				}
			}
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			bool flag = this.WorksetName != null;
			if (flag)
			{
				xElement.Add(new XAttribute("worksetName", this.WorksetName));
			}
			bool flag2 = this.Id != WorksetId.InvalidWorksetId;
			if (flag2)
			{
				xElement.Add(new XAttribute("worksetId", this.Id));
			}
			return xElement;
		}
		public override int Apply(ModelData md, IList<Element> elems, ApplyOptions options, out string report)
		{
			this.FindWorkset(md.Worksets);
			bool flag = base.ErrReport != "";
			int result = 0;
			if (flag)
			{
				report = base.ErrReport;
				result = 0;
			}
			else
			{
				report = "";
				int num = 0;
				using (ProgressForm progressForm = new ProgressForm("Назначение рабочего набора '" + this.WorksetName + "'", "", elems.Count))
				{
					foreach (Element current in elems)
					{
						Autodesk.Revit.DB.Parameter parameter = current.get_Parameter(BuiltInParameter.ELEM_PARTITION_PARAM);
						try
						{
							parameter.Set(this.Id.IntegerValue);
							num++;
						}
						catch (Exception ex)
						{
							Log.Write(string.Format("Элемент {0} не удалось поместить в рабочий набор '{1}' id {2}", current.Description(), this.WorksetName, this.Id));
							Log.Write(ex);
						}
						progressForm.Increment();
					}
				}
				result = num;
			}
			return result;
		}
		public override string Apply(ModelData md, Element e, ApplyOptions options)
		{
			this.FindWorkset(md.Worksets);
			bool flag = base.ErrReport != "";
			string result;
			if (flag)
			{
				result = base.ErrReport;
			}
			else
			{
				string text = "";
				Autodesk.Revit.DB.Parameter parameter = e.get_Parameter(BuiltInParameter.ELEM_PARTITION_PARAM);
				text = text + "Элемент '" + e.Description() + "'. ";
				try
				{
					parameter.Set(this.Id.IntegerValue);
					text += string.Format("Новый рабочий набор: '{0}' id {1}", this.WorksetName, this.Id);
				}
				catch (Exception ex)
				{
					Log.Write(ex);
					text += string.Format("Не удалось поместить в рабочий набор '{0}' id {1}: {2}", this.WorksetName, this.Id, ex.Message);
				}
				result = text;
			}
			return result;
		}
		private bool FindWorkset(List<Workset> allWorksets)
		{
			bool flag = allWorksets == null || !allWorksets.Any<Workset>();
			bool result = false;
			if (flag)
			{
				base.ErrReport = "не найдены рабочие наборы";
				result = false;
			}
			else
			{
				bool flag2 = this.Id == null || this.Id == WorksetId.InvalidWorksetId;
				if (flag2)
				{
					bool flag3 = this.WorksetName == "";
					if (flag3)
					{
						base.ErrReport = "не задан рабочий набор.";
						result = false;
						return result;
					}
					Workset workset = (
						from x in allWorksets
						where x.Name == this.WorksetName
						select x).FirstOrDefault<Workset>();
					bool flag4 = workset == null;
					if (flag4)
					{
						base.ErrReport = "не найден рабочий набор с именем '" + this.WorksetName + "'";
						result = false;
						return result;
					}
					this.Id = workset.Id;
				}
				else
				{
					Workset workset2 = (
						from x in allWorksets
						where this.Id != null && object.Equals(x.Id, this.Id)
						select x).FirstOrDefault<Workset>();
					bool flag5 = workset2 == null;
					if (flag5)
					{
						base.ErrReport = string.Format("не найден рабочий набор с заданным id {0}", this.Id);
						result = false;
						return result;
					}
					this.WorksetName = workset2.Name;
				}
				result = true;
			}
			return result;
		}
		public override string Description()
		{
			return "Рабочий набор '" + this.WorksetName + "'";
		}
		private string ParamErrorMessage(string catName, ElementId paramId, string paramName)
		{
			string text = string.IsNullOrEmpty(paramName) ? "" : (" '" + paramName + "'");
			string text2 = (paramId == null) ? "" : string.Format(" id {0}", paramId);
			return string.Concat(new string[]
			{
				text,
				text2,
				", привязанный к категории ",
				catName,
				"."
			});
		}
	}
	internal class ActionParam : Action
	{
		public const string FRAGMENTS = "fragments";
		public const string DESC = "desc";
		public ParamId Param
		{
			get;
			private set;
		}
		public List<IFragment> Fragments
		{
			get;
			private set;
		}
		public ActionParam()
		{
			this.Fragments = new List<IFragment>();
			
			this.Type = ActionType.SetParamValue;
		}
		public ActionParam(XElement xe, ModelData md) : base(xe) {
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				string text;
				XElement xElement = ParamId.CompatibilityCheck(xe, out text);
				bool flag2 = xElement == null;
				if (flag2)
				{
					base.ErrReport = text;
				}
				else
				{
					this.Param = new ParamId(xElement);
					bool flag3 = this.Param.ErrReport != "";
					if (flag3)
					{
						base.ErrReport = this.Param.ErrReport;
					}
					else
					{
						XElement xElement2 = xe.Element("fragments");
						bool flag4 = xElement2 == null;
						if (flag4)
						{
							base.ErrReport = "не обнаружены фрагменты для формирования нового значния";
						}
						else
						{
							foreach (XElement current in xElement2.Elements("fragment"))
							{
								IFragment fragment = ActionParam.CreateFragment(current, md, out text);
								bool flag5 = !string.IsNullOrEmpty(text);
								if (flag5)
								{
									bool flag6 = base.ErrReport != "";
									if (flag6)
									{
										base.ErrReport += "\r\n";
									}
									base.ErrReport += text;
								}
								else
								{
									bool flag7 = fragment != null;
									if (flag7)
									{
										this.Fragments.Add(fragment);
										bool flag8 = fragment.ErrReport != "";
										if (flag8)
										{
											bool flag9 = base.ErrReport != "";
											if (flag9)
											{
												base.ErrReport += "\r\n";
											}
											base.ErrReport = string.Concat(new string[]
											{
												base.ErrReport,
												"при добавлении фрагмента ",
												fragment.DescriptionShort,
												": ",
												fragment.ErrReport
											});
										}
									}
								}
							}
						}
					}
				}
			}
		}
		public static IFragment CreateFragment(XElement xe, ModelData md, out string errReport)
		{
			FragmentType fragmentType = FragmentBase.GetFragmentType(xe, out errReport);
			bool flag = errReport != "";
			IFragment result;
			if (flag)
			{
				result = null;
			}
			else
			{
				IFragment fragment = null;
				switch (fragmentType)
				{
				case FragmentType.Const:
					fragment = new FragmentConst(xe);
					break;
				case FragmentType.Symbol:
					fragment = new FragmentSymbol(xe);
					break;
				case FragmentType.ParameterValue:
					fragment = new FragmentParam(xe);
					break;
				case FragmentType.StringOperation:
					fragment = new FragmentStringOperation(xe);
					break;
				case FragmentType.Calculator:
					fragment = new FragmentCalc(xe, md);
					break;
				case FragmentType.FloorLevelName:
					fragment = new FragmentFloorLevelName(xe);
					break;
				case FragmentType.MEPSize:
					fragment = new FragmentMEPsize(xe);
					break;
				case FragmentType.FittingAngle:
					fragment = new FragmentAngle(xe);
					break;
				case FragmentType.PipeThickness:
					fragment = new FragmentPT(xe);
					break;
				case FragmentType.DuctThickness:
					fragment = new FragmentDT(xe);
					break;
				case FragmentType.DuctTapSize:
					fragment = new FragmentDuctTapSize(xe);
					break;
				case FragmentType.MEPsystem01:
					fragment = new FragmentMEPsys1(xe);
					break;
				case FragmentType.MEPsystem02:
					fragment = new FragmentMEPsys2(xe);
					break;
				case FragmentType.MEPsystemOfHost:
					fragment = new FragmentInsulHostSys(xe);
					break;
				case FragmentType.CatNumber:
					fragment = new FragmentCatNumber(xe);
					break;
				case FragmentType.CatName:
					fragment = new FragmentCatName(xe);
					break;
				case FragmentType.SystemParameter:
					fragment = new FragmentSystemParam(xe);
					break;
				case FragmentType.SumMEPsystemParam:
					fragment = new FragmentSumSystemParam(xe, md);
					break;
				}
				result = fragment;
			}
			return result;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			bool flag = this.Param != null;
			if (flag)
			{
