		public override int Apply(ModelData md, IList<Element> elems, ApplyOptions options, out string report)
		{
			bool flag = !this.Check(md.Doc, elems, out report);
			int result = 0;
			if (flag)
			{
				result = 0;
			}
			else
			{
				int num = 0;
				using (ProgressForm progressForm = new ProgressForm("Вычисление значения параметра '" + this.Param.Name + "'", "", elems.Count))
				{
					foreach (Element current in elems)
					{
						object valueFromFragments = this.GetValueFromFragments(md, current);
						Autodesk.Revit.DB.Parameter parameter = this.Param.GetParameter(current);
						string text;
						bool flag2 = this.SetValue(parameter, valueFromFragments, out text);
						if (flag2)
						{
							num++;
						}
						else
						{
							bool flag3 = text == "RUtil: SetValue2: попытка назначить значение параметру, который является read-only.";
							if (!flag3)
							{
								text = string.Format("Элемент {0} параметр '{1}' значение '{2}': {3}", new object[]
								{
									current.Id,
									(parameter != null) ? parameter.Definition.Name : null,
									valueFromFragments,
									text
								});
								Log.Write(text);
							}
						}
						progressForm.Increment();
					}
				}
				result = num;
			}
			return result;
		}
		public override string Apply(ModelData md, Element e, ApplyOptions options)
		{
			string text = "";
			object valueFromFragments = this.GetValueFromFragments(md, e);
			Autodesk.Revit.DB.Parameter parameter = this.Param.GetParameter(e);
			text = text + "Параметр '" + parameter.Definition.Name + "'. ";
			string arg;
			bool flag = this.SetValue(parameter, valueFromFragments, out arg);
			if (flag)
			{
				text += string.Format("Новое значение: '{0}'", valueFromFragments);
			}
			else
			{
				text += string.Format("Не удалось изменить значение на '{0}': {1}", valueFromFragments, arg);
			}
			return text;
		}
		public bool Check(Autodesk.Revit.DB.Document doc, IList<Element> elems, out string errReport)
		{
			errReport = "";
			bool arg_2D_0 = false;
			if (this.Param != null)
			{
				ParamId expr_16 = this.Param;
				arg_2D_0 = !string.IsNullOrEmpty((expr_16 != null) ? expr_16.ErrReport : null);
			}
			else
			{
				arg_2D_0 = true;
			}
			bool flag = arg_2D_0;
			bool result = false;
			if (flag)
			{
				errReport = "Не выбран параметр.";
				result = false;
			}
			else
			{
				bool flag2 = elems != null && elems.Any<Element>();
				if (flag2)
				{
					List<ElementId> list = new List<ElementId>();
					foreach (Element current in elems)
					{
						bool flag3 = current == null;
						if (!flag3)
						{
							bool flag4 = current.Category != null;
							if (flag4)
							{
								list.Add(current.Category.Id);
							}
						}
					}
					list = list.Distinct<ElementId>().ToList<ElementId>();
					using (List<ElementId>.Enumerator enumerator2 = list.GetEnumerator())
					{
						while (enumerator2.MoveNext())
						{
							ElementId catId = enumerator2.Current;
							Category category = Category.GetCategory(doc, catId);
							string name = category.Name;
							Element element = (
								from e in elems
								where object.Equals(e.Category.Id, catId)
								select e).FirstOrDefault<Element>();
							bool flag5 = element == null;
							if (!flag5)
							{
								Autodesk.Revit.DB.Parameter parameter = this.Param.GetParameter(element);
								bool flag6 = parameter == null;
								if (flag6)
								{
									errReport = "Не удалось найти параметр " + this.ParamErrorMessage(name);
									result = false;
									return result;
								}
								bool flag7 = parameter.StorageType == StorageType.None;
								if (flag7)
								{
									errReport = "Не удалось определить тип данных у результирующего параметра " + this.ParamErrorMessage(name);
									result = false;
									return result;
								}
							}
						}
					}
				}
				result = true;
			}
			return result;
		}
		private object GetValueFromFragments(ModelData md, Element e)
		{
			object obj = null;
			foreach (IFragment current in this.Fragments)
			{
				object value = current.GetValue(md, e);
				bool flag = value != null;
				if (flag)
				{
					bool flag2 = obj == null;
					if (flag2)
					{
						obj = value;
					}
					else
					{
						bool flag3 = !(obj is string);
						if (flag3)
						{
							obj = obj.ToString();
						}
						obj = ((obj != null) ? obj.ToString() : null) + value.ToString();
					}
				}
			}
			return obj;
		}
		private bool SetValue(Autodesk.Revit.DB.Parameter p, object value, out string errReport)
		{
			bool flag = false;
			errReport = "";
			bool flag2 = p == null;
			bool result = false;
			if (flag2)
			{
				errReport = "параметр не определён";
				result = false;
			}
			else
			{
				StorageType storageType = p.StorageType;
				StorageType storageType2 = storageType;
				if (storageType2 - StorageType.Integer > 1)
				{
					flag = p.SetValue2(value, false, out errReport);
				}
				else
				{
					string text = value as string;
					bool flag3 = text != null && text == "";
					if (flag3)
					{
						errReport = "не удалось определить значение для заполнения параметра";
					}
					else
					{
						flag = p.SetValue2(value, false, out errReport);
					}
				}
				result = flag;
			}
			return result;
		}
		public override string Description()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("Запись в параметр '");
			bool flag = this.Param != null;
			if (flag)
			{
				stringBuilder.Append(this.Param.Name);
			}
			stringBuilder.AppendLine("'");
			bool flag2 = this.Fragments != null && this.Fragments.Any<IFragment>();
			if (flag2)
			{
				stringBuilder.Append(": ");
				foreach (IFragment current in this.Fragments)
				{
					stringBuilder.Append(current.DescriptionShort);
				}
			}
			bool flag3 = base.ErrReport != "";
			if (flag3)
			{
				stringBuilder.AppendLine();
				stringBuilder.Append(base.ErrReport);
			}
			return stringBuilder.ToString();
		}
		private string ParamErrorMessage(string catName)
		{
			string text = string.IsNullOrEmpty(this.Param.Name) ? "" : (" '" + this.Param.Name + "'");
			string text2 = (this.Param.BIP == BuiltInParameter.INVALID) ? "" : string.Format(" (встроенный {0})", this.Param.BIP);
			string text3 = (this.Param.Guid == Guid.Empty) ? "" : string.Format(" (общий {0})", this.Param.Guid);
			return string.Concat(new string[]
			{
				text,
				text2,
				text3,
				", привязанный к категории ",
				catName,
				"."
			});
		}
		public string GetDescription()
		{
			string text = "";
			foreach (IFragment current in this.Fragments)
			{
				text = text + current.DescriptionDebug + "\r\n";
			}
			text += "\r\n";
			return text;
		}
