			DataGridViewSelectedRowCollection selectedRows = dgv.SelectedRows;
			bool flag = selectedRows == null;
			if (!flag)
			{
				foreach (DataGridViewRow dataGridViewRow in selectedRows)
				{
					list.Add(dataGridViewRow.Index);
				}
				list.Sort();
				List<int> list2 = move(list);
				this.FillDgvFragments();
				foreach (DataGridViewRow dataGridViewRow2 in dgv.SelectedRows)
				{
					dataGridViewRow2.Selected = false;
				}
				foreach (int current in list2)
				{
					dgv.Rows[current].Selected = true;
				}
			}
		}
