		private void FillDgv()
		{
			bool flag = string.IsNullOrEmpty(this._engine.RS.ErrReport);
			if (flag)
			{
				Tuple<int, int> dGVstate = RUtil.GetDGVstate(this.dgv);
				this.dgv.Rows.Clear();
				foreach (Rule current in this._engine.RS.Rules)
				{
					int index = this.dgv.Rows.Add();
					DataGridViewRow dataGridViewRow = this.dgv.Rows[index];
					dataGridViewRow.Cells[this._colCheckbox.Column.Index].Value = current.Enable;
					dataGridViewRow.Cells[this.colIndex.Index].Value = current.Index;
					dataGridViewRow.Cells[this.colComment.Index].Value = current.Comment;
					DataGridViewCell arg_127_0 = dataGridViewRow.Cells[this.colAction.Index];
					Action expr_11B = current.Action;
					arg_127_0.Value = ((expr_11B != null) ? expr_11B.Description() : null);
					bool flag2 = current.FilterSet != null;
					if (flag2)
					{
						dataGridViewRow.Cells[this.colFilters.Index].Value = current.FilterSet.Description(this.dgv.Columns[this.colFilters.Index].Width);
					}
				}
				RUtil.RestoreScrollingRowIndex(this.dgv, dGVstate);
				this.dgv.EndEdit();
			}
		}
		private void MyResize()
		{
			int index = this.colFilters.Index;
			int width = this.dgv.Columns[index].Width;
			for (int i = 0; i < this.dgv.Rows.Count; i++)
			{
				this.dgv.Rows[i].Cells[index].Value = this._engine.RS.Rules[i].FilterSet.Description(width);
			}
			this.dgv.EndEdit();
		}
		private void Reload()
		{
			this.FillDgv();
			this.MyResize();
			this.Text = this._engine.FileService.GetPath() + " - Редактор набора правил";
		}
		private void CutAction(List<int> selRowIndexes)
		{
			List<int> selectedRuleIndexes = this.GetSelectedRuleIndexes(selRowIndexes);
			int num = 2147483647;
			foreach (DataGridViewRow dataGridViewRow in this.dgv.SelectedRows)
			{
				bool flag = dataGridViewRow.Index < num;
				if (flag)
				{
					num = dataGridViewRow.Index;
				}
			}
			this._engine.RS.CopyToBuffer(this._engine.Model.Doc, selectedRuleIndexes);
			this._engine.RS.DeleteRules(selectedRuleIndexes);
			this.FillDgv();
			this.dgv.ClearSelection();
			foreach (DataGridViewRow dataGridViewRow2 in (IEnumerable)this.dgv.Rows)
			{
				bool flag2 = dataGridViewRow2.Index == num;
				if (flag2)
				{
					dataGridViewRow2.Selected = true;
					break;
				}
			}
		}
		private void CopyAction(List<int> selRowIndexes)
		{
			this._engine.RS.CopyToBuffer(this._engine.Model.Doc, this.GetSelectedRuleIndexes(selRowIndexes));
		}
		private void PasteAction(List<int> selRowIndexes)
		{
			string text;
			List<int> list = this._engine.RS.PasteFromBuffer(this._engine.Model, this.GetSelectedRuleIndexes(selRowIndexes), out text);
			bool flag = text != "";
			if (flag)
			{
				MessageBox.Show(text);
			}
			else
			{
				this.FillDgv();
				this.dgv.ClearSelection();
				foreach (DataGridViewRow dataGridViewRow in (IEnumerable)this.dgv.Rows)
				{
					int item = (int)dataGridViewRow.Cells[this.colIndex.Index].Value;
					bool flag2 = list.Contains(item);
					if (flag2)
					{
						dataGridViewRow.Selected = true;
					}
				}
			}
		}
		private void DeleteAction(List<int> selRowIndexes)
		{
			this._engine.RS.DeleteRules(this.GetSelectedRuleIndexes(selRowIndexes));
			this.FillDgv();
		}
		private List<int> GetSelectedRuleIndexes(List<int> selRowIndexes)
		{
			List<int> list = new List<int>();
			foreach (int current in selRowIndexes)
			{
				list.Add(current + 1);
			}
			return list;
		}
		private void dgv_CellMouseEnter(object sender, DataGridViewCellEventArgs e)
		{
			bool flag = e.ColumnIndex == this.colEditKeys.Index;
			if (flag)
			{
				this.tip1.SetToolTip(this.dgv, "Редактировать правило");
			}
			else
			{
				bool flag2 = e.ColumnIndex == this.colDeleteKeys.Index;
				if (flag2)
				{
					this.tip1.SetToolTip(this.dgv, "Удалить правило");
				}
				else
				{
					bool flag3 = e.ColumnIndex == this.colApply.Index;
					if (flag3)
					{
						this.tip1.SetToolTip(this.dgv, "Применить правило");
					}
					else
					{
						this.tip1.Hide(this.dgv);
					}
				}
			}
		}
		private void dgv_CellValueChanged(object sender, DataGridViewCellEventArgs e)
		{
			bool flag = e.RowIndex < 0;
			if (!flag)
			{
				DataGridViewRow dataGridViewRow = this.dgv.Rows[e.RowIndex];
				object value = dataGridViewRow.Cells[this.colIndex.Index].Value;
				bool flag2 = value == null;
				if (!flag2)
				{
					int ruleIndex = (int)value;
					bool flag3 = e.ColumnIndex == this._colCheckbox.Column.Index && e.RowIndex != -1 && this._isLoaded;
					if (flag3)
					{
						DataGridViewCheckBoxCell dataGridViewCheckBoxCell = dataGridViewRow.Cells[this._colCheckbox.Column.Index] as DataGridViewCheckBoxCell;
						this._engine.RS.ChangeEnable(ruleIndex, (bool)dataGridViewCheckBoxCell.Value);
					}
					bool flag4 = e.ColumnIndex == this.colComment.Index && e.RowIndex != -1 && this._isLoaded;
					if (flag4)
					{
						DataGridViewTextBoxCell dataGridViewTextBoxCell = dataGridViewRow.Cells[this.colComment.Index] as DataGridViewTextBoxCell;
						this._engine.RS.ChangeComment(ruleIndex, dataGridViewTextBoxCell.Value.ToString());
					}
				}
			}
		}
