		private void dgv_CellClick(object sender, DataGridViewCellEventArgs e)
		{
			bool flag = e.RowIndex < 0;
			if (!flag)
			{
				DataGridViewRow dataGridViewRow = this.dgv.Rows[e.RowIndex];
				int ruleIndex = (int)dataGridViewRow.Cells[this.colIndex.Index].Value;
				bool flag2 = e.ColumnIndex == this.colEditKeys.Index;
				if (flag2)
				{
					Rule rule = this._engine.RS.GetRule(ruleIndex);
					DialogResult dialogResult = DialogResult.Cancel;
					Rule rule2 = null;
					ActionType type = rule.Action.Type;
					ActionType actionType = type;
					if (actionType != ActionType.SetParamValue)
					{
						if (actionType == ActionType.ChangeType)
						{
							FrmRuleEditor2 frmRuleEditor = new FrmRuleEditor2(this._engine, rule.Convert2Xml());
							dialogResult = frmRuleEditor.ShowDialog();
							rule2 = frmRuleEditor.MyRule;
						}
					}
					else
					{
						XElement xeRule = rule.Convert2Xml();
						FrmRuleEditor1 frmRuleEditor2 = new FrmRuleEditor1(this._engine, xeRule);
						dialogResult = frmRuleEditor2.ShowDialog();
						rule2 = frmRuleEditor2.MyRule;
					}
					bool flag3 = dialogResult == DialogResult.OK && rule2.IsChanged;
					if (flag3)
					{
						this._engine.RS.UpdateRule(ruleIndex, rule2);
						this.FillDgv();
					}
				}
				bool flag4 = e.ColumnIndex == this.colDeleteKeys.Index;
				if (flag4)
				{
					this._engine.RS.DeleteRule(ruleIndex);
					this.FillDgv();
				}
				bool flag5 = e.ColumnIndex == this.colApply.Index;
				if (flag5)
				{
					this.ControlsEnable(false);
					this._engine.ApplySingleRule(ruleIndex, this.txtResult);
					this.ControlsEnable(true);
				}
			}
		}
