		private void btnAddRule_Click(object sender, EventArgs e)
		{
			bool flag = this.cmbActionType.SelectedIndex == 0;
			ActionType actionType;
			if (flag)
			{
				actionType = ActionType.SetParamValue;
			}
			else
			{
				actionType = ActionType.ChangeType;
			}
			DialogResult dialogResult = DialogResult.Cancel;
			Rule newRule = null;
			ActionType actionType2 = actionType;
			ActionType actionType3 = actionType2;
			if (actionType3 != ActionType.SetParamValue)
			{
				if (actionType3 == ActionType.ChangeType)
				{
					FrmRuleEditor2 frmRuleEditor = new FrmRuleEditor2(this._engine, null);
					dialogResult = frmRuleEditor.ShowDialog();
					newRule = frmRuleEditor.MyRule;
				}
			}
			else
			{
				FrmRuleEditor1 frmRuleEditor2 = new FrmRuleEditor1(this._engine, null);
				dialogResult = frmRuleEditor2.ShowDialog();
				newRule = frmRuleEditor2.MyRule;
			}
			bool flag2 = dialogResult == DialogResult.OK;
			if (flag2)
			{
				this._engine.RS.AddRule(newRule);
				this.FillDgv();
			}
		}
		private void btnRun_Click(object sender, EventArgs e)
