		private void MoveRows(DataGridView dgv, MoveRowsDelegate move)
		{
			int firstDisplayedScrollingRowIndex = dgv.FirstDisplayedScrollingRowIndex;
			List<int> list = new List<int>();
			DataGridViewSelectedRowCollection selectedRows = dgv.SelectedRows;
			bool flag = selectedRows == null;
			if (!flag)
			{
				foreach (DataGridViewRow dataGridViewRow in selectedRows)
				{
					list.Add(dataGridViewRow.Index);
				}
				list.Sort();
				List<int> list2 = move(list);
				this._engine.RS.Renumerate();
				this.FillDgv();
				foreach (DataGridViewRow dataGridViewRow2 in dgv.SelectedRows)
				{
					dataGridViewRow2.Selected = false;
				}
				foreach (int current in list2)
				{
					dgv.Rows[current].Selected = true;
				}
				int num = list2.Min();
				int num2 = list2.Max();
				bool flag2 = num < 0 || num2 > dgv.RowCount - 1 || dgv.Rows.Count <= dgv.DisplayedRowCount(false);
				if (!flag2)
				{
					bool flag3 = num2 > firstDisplayedScrollingRowIndex + dgv.DisplayedRowCount(false) - 2;
					if (flag3)
					{
						dgv.FirstDisplayedScrollingRowIndex = num;
					}
					else
					{
						dgv.FirstDisplayedScrollingRowIndex = firstDisplayedScrollingRowIndex;
					}
				}
			}
		}
