	internal class Rule
	{
		public const string RULE = "rule";
		private const string _INDEX = "index";
		private const string _ENABLE = "enable";
		private const string _COMMENT = "comment";
		public int Index
		{
			get;
			set;
		}
		public Action Action
		{
			get;
			private set;
		}
		public FilterSet FilterSet
		{
			get;
			private set;
		}
		public bool Enable
		{
			get;
			set;
		}
		public bool IsChanged
		{
			get;
			private set;
		}
		public string Comment
		{
			get;
			set;
		}
		public string ErrReport
		{
			get;
			set;
		}
		public Rule(Action action)
		{
			this.Enable = true;
			this.IsChanged = false;
			this.Comment = "";
			this.ErrReport = "";
			
			this.Action = action;
			this.FilterSet = new FilterSet();
			this.FilterSet.FilterAdded += new FilterSet.FilterSetEventHandler(this.AddFilterHandler);
			this.FilterSet.FilterDeleted += new FilterSet.FilterSetEventHandler(this.FilterSetChangedHandler);
			this.FilterSet.FilterUpdated += new FilterSet.FilterSetEventHandler(this.FilterSetChangedHandler);
			this.Check();
		}
		public Rule(ModelData md, XElement xe)
		{
			this.Enable = true;
			this.IsChanged = false;
			this.Comment = "";
			this.ErrReport = "";
			
			bool flag = xe == null || xe.Name != "rule";
			if (flag)
			{
				this.ErrReport = "переданный элемент не является правилом";
			}
			else
			{
				XAttribute xAttribute = xe.Attribute("index");
				bool flag2 = xAttribute != null;
				if (flag2)
				{
					int index = 0;
					bool flag3 = int.TryParse(xAttribute.Value, out index);
					if (!flag3)
					{
						this.ErrReport = "не удалось получить индекс правила";
						return;
					}
					this.Index = index;
				}
				XAttribute xAttribute2 = xe.Attribute("enable");
				bool flag4 = xAttribute2 != null;
				if (flag4)
				{
					bool enable = false;
					bool flag5 = bool.TryParse(xAttribute2.Value, out enable);
					if (flag5)
					{
						this.Enable = enable;
					}
				}
				XElement xElement = xe.Element("comment");
				bool flag6 = xElement != null;
				if (flag6)
				{
					this.Comment = xElement.Value;
				}
				XElement xElement2 = xe.Element("action");
				bool flag7 = xElement2 == null;
				if (flag7)
				{
					this.ErrReport = "не обнаружено описание действия";
				}
				else
				{
					string value;
					ActionType actionType = Action.GetActionType(xElement2, out value);
					bool flag8 = !string.IsNullOrEmpty(value);
					if (flag8)
					{
						this.ErrReport += "не удалось определить тип операции";
					}
					else
					{
						this.Action = null;
						switch (actionType)
						{
						case ActionType.SetParamValue:
							this.Action = new ActionParam(xElement2, md);
							break;
						case ActionType.SetWorkset:
							this.Action = new ActionWorkset(xElement2);
							break;
						case ActionType.ChangeType:
							this.Action = new ActionChangeType(xElement2);
							break;
						}
						this.FilterSet = new FilterSet(md, xe.Element("filters"));
						this.FilterSet.FilterAdded += new FilterSet.FilterSetEventHandler(this.AddFilterHandler);
						this.FilterSet.FilterDeleted += new FilterSet.FilterSetEventHandler(this.FilterSetChangedHandler);
						this.FilterSet.FilterUpdated += new FilterSet.FilterSetEventHandler(this.FilterSetChangedHandler);
						this.Check();
						this.IsChanged = false;
					}
				}
			}
		}
		private void Check()
		{
			this.ErrReport = "";
			bool flag = this.Action == null;
			if (flag)
			{
				this.ErrReport += "не удалось получить операцию";
			}
			else
			{
				bool flag2 = this.Action.ErrReport != "";
				if (flag2)
				{
					bool flag3 = this.ErrReport != "";
					if (flag3)
					{
						this.ErrReport += "\r\n";
					}
					this.ErrReport += this.Action.ErrReport;
				}
				this.FilterSet.Check();
				bool flag4 = this.FilterSet.ErrReport != "";
				if (flag4)
				{
					bool flag5 = this.ErrReport != "";
					if (flag5)
					{
						this.ErrReport += "\r\n";
					}
					this.ErrReport += this.FilterSet.ErrReport;
				}
			}
		}
		public XElement Convert2Xml()
		{
			XElement xElement = new XElement("rule", new object[]
			{
				new XAttribute("index", this.Index),
				new XAttribute("enable", this.Enable)
			});
			bool flag = this.Comment != "";
			if (flag)
			{
				xElement.Add(new XElement("comment", this.Comment));
			}
			XElement content = this.Action.Convert2Xml();
			xElement.Add(content);
			XElement content2 = this.FilterSet.Convert2Xml();
			xElement.Add(content2);
			return xElement;
		}
		public void AddFilterHandler()
		{
			this.IsChanged = true;
			this.Check();
		}
		public void FilterSetChangedHandler()
		{
			this.IsChanged = true;
		}
		public void Update(Action action, FilterSet filterSet)
		{
			bool isChanged = action.IsChanged;
			if (isChanged)
			{
				this.Action = action;
				bool flag = this.Action.ErrReport != "";
				if (flag)
				{
					this.ErrReport = action.ErrReport;
				}
				this.IsChanged = true;
			}
			bool flag2 = filterSet != null;
			if (flag2)
			{
				this.FilterSet = filterSet;
				bool flag3 = this.FilterSet.ErrReport != "";
				if (flag3)
				{
					this.ErrReport = this.FilterSet.ErrReport;
				}
				this.IsChanged = true;
			}
			this.Check();
			bool flag4 = this.ErrReport != "";
			if (flag4)
			{
				MessageBox.Show(this.ErrReport);
			}
		}
		public void Update(string comment)
		{
			bool flag = comment != this.Comment;
			if (flag)
			{
				this.Comment = comment;
				this.IsChanged = true;
			}
		}
		public List<Element> ApplyFilters4OneElement(ModelData md, string discip, Element elem, ApplyOptions applyOpt, out string applyErrReport, out string report)
		{
			applyErrReport = "";
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("Применение фильтров:");
			List<Element> result = this.FilterSet.Apply(md, applyOpt, new List<Element>
			{
				elem
			}, ref stringBuilder);
			report = stringBuilder.ToString();
			return result;
		}
		public bool Apply(ModelData md, ApplyOptions options, List<Element> startList, System.Windows.Forms.TextBox txtResult)
		{
			string text = "";
			string text2 = string.Format("{0}: ", this.Index) + this.Action.Description();
			bool flag = !this.Enable;
			bool result = false;
			if (flag)
			{
				string text3 = text2 + ": <не применяется>\r\n";
				txtResult.AppendText(text3);
				Log.Write("Операция " + text3);
				result = true;
			}
			else
			{
				txtResult.AppendText(text2 + "\r\n");
				text = text + "Операция " + text2 + "\r\n";
				bool flag2 = this.ErrReport != "";
				if (flag2)
				{
					txtResult.AppendText("Ошибка: " + this.ErrReport + "\r\n");
					text += string.Format("\r\nОшибка в операции {0}: {1}: {2}\r\n", this.Index, text2, this.ErrReport);
					Log.Write(text);
					result = false;
				}
				else
				{
					string str;
					List<Element> list = this.ApplyFilters(md, options, startList, out str);
					str = "Применение фильтров: " + str;
					text = text + str + "\r\n";
					bool flag3 = list == null || list.Count == 0;
					if (flag3)
					{
						txtResult.AppendText("Не найдено элементов.\r\n\r\n");
						Log.Write(text);
						result = true;
					}
					else
					{
						string text4;
						int num = this.Action.Apply(md, list, options, out text4);
						bool flag4 = text4 != "";
						if (flag4)
						{
							text += text4;
							txtResult.AppendText(text4 + "\r\n");
						}
						string text5 = string.Format("Обработано элементов: {0} из {1}\r\n\r\n", num, list.Count);
						txtResult.AppendText(text5);
						text += text5;
						Log.Write(text);
						result = true;
					}
				}
			}
			return result;
		}
		public List<Element> ApplyFilters(ModelData md, ApplyOptions options, List<Element> startList, out string rep)
		{
			StringBuilder stringBuilder = new StringBuilder();
			List<Element> result = this.FilterSet.Apply(md, options, startList, ref stringBuilder);
			rep = stringBuilder.ToString();
			return result;
		}
	}
	internal class RuleSet : XmlDataSetBase
	{
		private Buffer _buffer;
		private DateTime _timeBegin;
		public const string RULES = "rules";
		private const string _COMMENT = "comment";
		public List<Rule> Rules
		{
			get;
			private set;
		}
		public string Comment
		{
			get;
			set;
		}
		public string ErrReport
		{
			get;
			private set;
		}
		public RuleSet()
		{
			this.Rules = new List<Rule>();
			this.Comment = "";
			this.ErrReport = "";
			
			base.IsChanged = false;
		}
		public RuleSet(ModelData md, XElement xe)
		{
			this.Rules = new List<Rule>();
			this.Comment = "";
			this.ErrReport = "";
			
			base.IsChanged = false;
			this._buffer = new Buffer();
			bool flag = md.Doc == null || xe == null;
			if (flag)
			{
				this.ErrReport = "аргумент не задан";
			}
			else
			{
				XElement xElement = xe.Element("comment");
				bool flag2 = xElement != null;
				if (flag2)
				{
					this.Comment = xElement.Value;
				}
				RulesFormatService rulesFormatService = new RulesFormatService();
				rulesFormatService.UpdateToActualVersion(xe);
				bool wasUpdated = rulesFormatService.WasUpdated;
				if (wasUpdated)
				{
					xe = rulesFormatService.ActualXElement;
					base.IsChanged = true;
					MessageBox.Show("Файл был создан в предыдущей версии плагина. Данные обновлены до текущей версии.\r\nСохраните файл c заменой существующего или под другим именем.");
				}
				foreach (XElement current in xe.Elements("rule"))
				{
					Rule rule = new Rule(md, current);
					bool flag3 = rule.ErrReport != "";
					if (flag3)
					{
						Log.Write(string.Format("Ошибка при загрузке правила {0} из файла: {1}", rule.Index, rule.ErrReport));
					}
					this.Rules.Add(rule);
				}
			}
		}
		public void Add(Rule rule)
		{
			rule.Index = this.Rules.Count + 1;
			bool flag = rule.FilterSet.AllFilters.Count == 0;
			if (flag)
			{
				rule.Enable = false;
			}
			this.Rules.Add(rule);
		}
		public void AddRule(Rule newRule)
		{
			this.Rules.Add(newRule);
			this.Renumerate();
			base.IsChanged = true;
		}
		public void DeleteRule(int ruleIndex)
		{
			int num = this.Rules.FindIndex((Rule r) => r.Index == ruleIndex);
			bool flag = num == -1;
			if (!flag)
			{
				this.Rules.RemoveAt(num);
				this.Renumerate();
				base.IsChanged = true;
			}
		}
		public void DeleteRules(List<int> selIndexes)
		{
			bool flag = selIndexes == null || !selIndexes.Any<int>();
			if (!flag)
			{
				using (List<int>.Enumerator enumerator = selIndexes.GetEnumerator())
				{
					while (enumerator.MoveNext())
					{
						int selIndex = enumerator.Current;
						int num = this.Rules.FindIndex((Rule r) => r.Index == selIndex);
						bool flag2 = num == -1;
						if (flag2)
						{
							return;
						}
						this.Rules.RemoveAt(num);
					}
				}
				this.Renumerate();
				base.IsChanged = true;
			}
		}
		public void CopyToBuffer(Autodesk.Revit.DB.Document doc, List<int> selIndexes)
		{
			bool flag = selIndexes == null || !selIndexes.Any<int>();
			if (!flag)
			{
				bool flag2 = this._buffer == null;
				if (flag2)
				{
					this._buffer = new Buffer();
				}
				this._buffer.AddRules(doc, this.Rules, selIndexes);
			}
		}
		public List<int> PasteFromBuffer(ModelData md, List<int> selIndexes, out string errReport)
		{
			List<int> list = new List<int>();
			errReport = "";
			bool flag = selIndexes == null || !selIndexes.Any<int>();
			List<int> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				selIndexes.Sort();
				bool flag2 = selIndexes.Count == 1;
				if (flag2)
				{
					int num = selIndexes[0];
					List<Rule> list2 = new List<Rule>();
					for (int i = 0; i < this._buffer.RulesInXml.Count; i++)
					{
						XElement xe = this._buffer.RulesInXml[i];
						Rule rule = new Rule(md, xe);
						bool flag3 = rule.ErrReport != "";
						if (flag3)
						{
							Log.Write(string.Format("Ошибка при вставке правила {0} из буфера: {1}", rule.Index, rule.ErrReport));
						}
						list2.Add(rule);
						list.Add(num + i + 1);
					}
					this.Rules.InsertRange(num, list2);
				}
				else
				{
					bool flag4 = !Buffer.IsCompact(selIndexes);
					if (flag4)
					{
						errReport = "Данная команда неприменима для несвязных диапазонов";
						result = list;
						return result;
					}
					int num2 = selIndexes[0];
					int count = this.Rules.Count;
					for (int j = 0; j < this._buffer.RulesInXml.Count; j++)
					{
						XElement xe2 = this._buffer.RulesInXml[j];
						Rule rule2 = new Rule(md, xe2);
						bool flag5 = rule2.ErrReport != "";
						if (flag5)
						{
							Log.Write(string.Format("Ошибка при вставке правила {0} из буфера: {1}", rule2.Index, rule2.ErrReport));
						}
						int num3 = num2 + j - 1;
						bool flag6 = num3 < count;
						if (flag6)
						{
							this.Rules[num3] = rule2;
						}
						else
						{
							this.Rules.Add(rule2);
						}
						list.Add(num3 + 1);
					}
				}
				this.Renumerate();
				base.IsChanged = true;
				result = list;
			}
			return result;
		}
		public void UpdateRule(int ruleIndex, Rule editedRule)
		{
