		public void ApplyAll(ModelData md, ApplyOptions options, List<Element> startList, System.Windows.Forms.TextBox txtResult)
		{
			Log.Write("Применение правил к проекту '" + md.Doc.Title + "'\r\n");
			this._timeBegin = DateTime.Now;
			int num = 0;
			foreach (Rule current in this.Rules)
			{
				List<Element> list = new List<Element>();
				list.AddRange(startList);
				bool flag = !current.Apply(md, options, list, txtResult);
				if (flag)
				{
					num++;
				}
			}
			txtResult.AppendText(string.Format("ВЫПОЛНЕНО ОПЕРАЦИЙ: {0} из {1}.\r\n\r\n", this.Rules.Count - num, this.Rules.Count));
			TimeSpan timeSpan = DateTime.Now - this._timeBegin;
			Log.Write(string.Format("Завершено. Время работы {0} мин {1}.{2} сек.", timeSpan.Minutes, timeSpan.Seconds, timeSpan.Milliseconds));
		}
		public void ApplySingleRule(int ruleIndex, ModelData md, ApplyOptions options, List<Element> startList, System.Windows.Forms.TextBox txtResult)
		{
			int num = this.Rules.FindIndex((Rule r) => r.Index == ruleIndex);
			bool flag = num == -1;
			if (!flag)
			{
				this.Rules[num].Apply(md, options, startList, txtResult);
			}
		}
		public string Apply4OneElement(ModelData md, ApplyOptions options, ElementId id)
		{
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = md.Doc == null || id == null;
			string result;
			if (flag)
			{
				result = "недостаточно входных данных";
			}
			else
			{
				Element element = md.Doc.GetElement(id);
				bool flag2 = element == null;
				if (flag2)
				{
					result = string.Format("не найден элемент id {0}", id);
				}
				else
				{
					List<Element> startList = new List<Element>
					{
						element
					};
					stringBuilder.AppendLine(string.Format("Применение правил к элементу id {0} '{1}'", id, element.Description()));
					this._timeBegin = DateTime.Now;
					int num = 0;
					foreach (Rule current in this.Rules)
					{
						string text = "";
						string text2 = string.Format("Операция {0}: ", current.Index) + current.Action.Description();
						bool flag3 = !current.Enable;
						if (flag3)
						{
							stringBuilder.AppendLine(text2 + ": <не применяется>\r\n");
						}
						else
						{
							stringBuilder.AppendLine(text2);
							bool flag4 = current.ErrReport != "";
							if (flag4)
							{
								stringBuilder.AppendLine("Ошибка: " + current.ErrReport + "\r\n");
								num++;
							}
							else
							{
								options.Set4OneElement(id);
								string str;
								List<Element> list = current.ApplyFilters(md, options, startList, out str);
								stringBuilder.AppendLine("Фильтры: " + str);
								bool flag5 = list == null || list.Count == 0;
								if (flag5)
								{
									stringBuilder.AppendLine();
								}
								else
								{
									bool flag6 = list.Count == 1 && object.Equals(list[0].Id, id);
									if (flag6)
									{
										stringBuilder.AppendLine(current.Action.Apply(md, list[0], options));
									}
									else
									{
										foreach (Element current2 in list)
										{
											string value = current.Action.Apply(md, current2, options);
											stringBuilder.AppendLine(string.Format("Элемент id {0} '{1}'", id, element.Description()));
											stringBuilder.AppendLine(value);
										}
									}
									stringBuilder.AppendLine();
									Log.Write(text);
								}
							}
						}
					}
					TimeSpan timeSpan = DateTime.Now - this._timeBegin;
					stringBuilder.AppendLine(string.Format("\r\nВЫПОЛНЕНО ОПЕРАЦИЙ: {0} из {1}. ", this.Rules.Count - num, this.Rules.Count) + string.Format("Время работы {0} мин {1}.{2} сек.\r\n", timeSpan.Minutes, timeSpan.Seconds, timeSpan.Milliseconds));
					result = stringBuilder.ToString();
				}
			}
			return result;
		}
		public override XElement Convert2Xml(params object[] args)
		{
			Autodesk.Revit.DB.Document document = args[0] as Autodesk.Revit.DB.Document;
			XElement xElement = new XElement("rules");
			xElement.Add(new XElement("comment", this.Comment));
			foreach (Rule current in this.Rules)
			{
				XElement content = current.Convert2Xml();
				xElement.Add(content);
			}
			return xElement;
		}
		public override void Clear()
		{
			this.Rules.Clear();
			this.Comment = "";
			this.ErrReport = "";
			base.IsChanged = true;
		}
	}
