		public Engine(UIDocument uidoc, string pluginXPath)
		{
			this.RS = new RuleSet();
			
			this.ErrReport = "";
			this.UIdoc = uidoc;
			this.PluginXPath = pluginXPath;
			this.Model = new ModelData(uidoc.Document);
			TypeDescriptor.AddAttributes(typeof(ElementId), new Attribute[]
			{
				new TypeConverterAttribute(typeof(ElementIdConverter))
			});
			this.FileService = new FileService(this.RS, new LoaderFromXml(this.LoadFromXml), new SaveArgsGetter(this.GetArgs), "Сохранение файла правил заполнения параметров", "Набор правил не был сохранён", "Сохранить файл");
			this.AllUnits = new List<ItemComment>();
			foreach (ForgeTypeId current in UnitUtils.GetAllUnits())
			{
				string shortLabel = current.GetShortLabel();
				string comment = LabelUtils.GetLabelForUnit(current) + " (" + shortLabel + ")";
				this.AllUnits.Add(new ItemComment(current, comment));
			}
			XmlFile xmlFile = new XmlFile("", "root", false, true);
			bool creationError = xmlFile.CreationError;
			if (creationError)
			{
				string text = "Не удалось открыть файл с настройками. Обратитесь к разработчику.";
				MessageBox.Show(text);
				Log.Write(text);
			}
			else
			{
				string text2;
				XElement elementOrDefElement = xmlFile.GetElementOrDefElement(this.GetLastFileXPath(), out text2, "");
				bool flag = elementOrDefElement != null;
				if (flag)
				{
					string path = XmlConvert.DecodeName(elementOrDefElement.Value);
					bool flag2 = File.Exists(path);
					if (flag2)
					{
						this.FileService.SetPath(path);
					}
				}
				XElement elementOrDefElement2 = xmlFile.GetElementOrDefElement(this.PluginXPath + "/applyOptions", out text2, "");
				if (elementOrDefElement2 == null)
				{
					elementOrDefElement2 = new XElement("applyOptions", new XAttribute("inFullDoc", "true"));
				}
				this.ApplyOpt = new ApplyOptions(this.UIdoc, elementOrDefElement2);

				XElement elementOrDefElement3 = xmlFile.GetElementOrDefElement(this.PluginXPath + "/interOptions", out text2, "");
				if (elementOrDefElement3 == null)
				{
					elementOrDefElement3 = new XElement("interOptions", new XAttribute("isAutoSave", "true"));
				}
				this.InterOpt = new InterOptions(elementOrDefElement3);
				this.ErrReport = "";
			}
		}
		public void LoadFromXml(out string errReport)
		{
			XElement xe = XmlFileManager.Load(this.FileService.GetPath(), "rules", out errReport);
			bool flag = errReport != "";
			if (!flag)
			{
				this.RS = new RuleSet(this.Model, xe);
				this.FileService.LoadDataset(this.RS);
			}
		}
		public object[] GetArgs()
		{
			return new object[]
			{
				this.Model.Doc
			};
		}
		public void SaveSettings()
		{
			XmlFile xmlFile = new XmlFile("", "root", false, true);
			bool creationError = xmlFile.CreationError;
			if (creationError)
			{
				string text = "Не удалось открыть файл с настройками. Обратитесь к разработчику.";
				MessageBox.Show(text);
				Log.Write(text);
			}
			else
			{
				XElement xe = new XElement("lastFilePath", XmlConvert.EncodeName(this.FileService.GetPath()));
				string text2;
				xmlFile.Write(xe, this.GetLastFileXPath(), out text2, false);
				this.ApplyOpt.SetSelectingMode(this.UIdoc);
				XElement xe2 = this.ApplyOpt.Convert2Xml();
				xmlFile.Write(xe2, this.PluginXPath + "/applyOptions", out text2, false);
				XElement xe3 = this.InterOpt.Convert2Xml();
				xmlFile.Write(xe3, this.PluginXPath + "/interOptions", out text2, true);
			}
		}
		public void ApplyAll(System.Windows.Forms.TextBox txtResult)
		{
			this.ApplyOpt.SetSelectingMode(this.UIdoc);
			using (Transaction transaction = new Transaction(this.Model.Doc))
			{
				transaction.Start("Применение правил");
				List<Element> startList = this.GetStartList();
				this.RS.ApplyAll(this.Model, this.ApplyOpt, startList, txtResult);
				transaction.Commit();
			}
		}
		public void ApplySingleRule(int ruleIndex, System.Windows.Forms.TextBox txtResult)
		{
			this.ApplyOpt.SetSelectingMode(this.UIdoc);
			using (Transaction transaction = new Transaction(this.Model.Doc))
			{
				transaction.Start("Применение правила");
				List<Element> startList = this.GetStartList();
				this.RS.ApplySingleRule(ruleIndex, this.Model, this.ApplyOpt, startList, txtResult);
				transaction.Commit();
			}
		}
		public List<Element> GetStartList()
		{
			bool flag = this.ApplyOpt.ActiveView != null;
			FilteredElementCollector filteredElementCollector;
			if (flag)
			{
				filteredElementCollector = new FilteredElementCollector(this.Model.Doc, this.ApplyOpt.ActiveView.Id);
			}
			else
			{
				bool flag2 = this.ApplyOpt.SelectedElemIds.Any<ElementId>();
				if (flag2)
				{
					filteredElementCollector = new FilteredElementCollector(this.Model.Doc, this.ApplyOpt.SelectedElemIds);
				}
				else
				{
					filteredElementCollector = new FilteredElementCollector(this.Model.Doc);
				}
			}
			return filteredElementCollector.WherePasses(new LogicalOrFilter(new ElementIsElementTypeFilter(false), new ElementIsElementTypeFilter(true))).ToElements().ToList<Element>();
		}
		public string GetLastFileXPath()
		{
			return this.PluginXPath + "/lastFilePath";
