namespace SAV.ParamRules.Services
{
	internal class RulesFormatService
	{
		public const string UPDATE_MSG = "Файл был создан в предыдущей версии плагина. Данные обновлены до текущей версии.\r\nСохраните файл c заменой существующего или под другим именем.";
		public bool WasUpdated
		{
			get;
			private set;
		}
		public XElement ActualXElement
		{
			get;
			private set;
		}
		public RulesFormatService()
		{
			this.WasUpdated = false;
			this.ActualXElement = null;
			
		}
		public void UpdateToActualVersion(XElement xe)
		{
			this.WasUpdated = false;
			List<XElement> list = xe.Descendants("paramData").ToList<XElement>();
			bool flag = list.Count > 0;
			if (flag)
			{
				foreach (XElement current in list)
				{
					current.Name = "paramId";
				}
				this.WasUpdated = true;
			}
			List<XElement> list2 = xe.Descendants("fragment").ToList<XElement>();
			List<string> list3 = new List<string>
			{
				"Parameter",
				"TypeParameter",
				"HostParameter",
				"HostTypeParameter",
				"ParentFamilyParameter"
			};
			bool flag2 = list2.Count > 0;
			if (flag2)
			{
				foreach (XElement current2 in list2)
				{
					XAttribute xAttribute = current2.Attribute("type");
					bool flag3 = xAttribute == null;
					if (!flag3)
					{
						string value = xAttribute.Value;
						bool flag4 = list3.Contains(value);
						if (flag4)
						{
							string a;
							IFragment fragment = this.ConvertToParameterValue(current2, value, out a);
							bool flag5 = a != "";
							if (!flag5)
							{
								bool flag6 = fragment == null;
								if (!flag6)
								{
									current2.ReplaceWith(fragment.Convert2Xml());
									this.WasUpdated = true;
								}
							}
						}
					}
				}
			}
			bool wasUpdated = this.WasUpdated;
			if (wasUpdated)
			{
				this.ActualXElement = xe;
			}
		}
		private IFragment ConvertToParameterValue(XElement xe, string typeName, out string errReport)
		{
			IFragment fragment = null;
			errReport = "";
			XElement xElement = ParamId.CompatibilityCheck(xe, out errReport);
			bool flag = xElement == null;
			IFragment result;
			if (flag)
			{
				result = null;
			}
			else
			{
				ParamId paramId = new ParamId(xElement);
				bool flag2 = paramId.ErrReport != "";
				if (flag2)
				{
					errReport = paramId.ErrReport;
					result = null;
				}
				else
				{
					ForgeTypeId forgeTypeId = null;
					XElement xElement2 = xe.Element("forgeTypeId");
					bool flag3 = xElement2 != null;
					if (flag3)
					{
						forgeTypeId = new ForgeTypeId(xElement2.Value);
						bool flag4 = forgeTypeId == null;
						if (flag4)
						{
							errReport = "не удалось получить ForgeTypeId";
							result = null;
							return result;
						}
					}
					int roundDecimal = 2147483647;
					SAV.Extension.Result result2 = xe.Parse<int>("roundDecimal", false);
					bool ok = result2.Ok;
					if (ok)
					{
						roundDecimal = (int)result2.Value;
					}
					ParamData paramData = new ParamData(paramId, forgeTypeId, roundDecimal);
					if (!(typeName == "Parameter"))
					{
						if (!(typeName == "TypeParameter"))
						{
							if (!(typeName == "HostParameter"))
							{
								if (!(typeName == "HostTypeParameter"))
								{
									if (typeName == "ParentFamilyParameter")
									{
										fragment = new FragmentParam(ParamGettingMode.Parent, paramData);
									}
								}
								else
								{
									fragment = new FragmentParam(ParamGettingMode.HostType, paramData);
								}
							}
							else
							{
								fragment = new FragmentParam(ParamGettingMode.Host, paramData);
							}
						}
						else
						{
							fragment = new FragmentParam(ParamGettingMode.Type, paramData);
						}
					}
					else
					{
						fragment = new FragmentParam(ParamGettingMode.Self, paramData);
					}
					result = fragment;
				}
			}
			return result;
		}
	}
}
