		public object GetValue(ModelData md, Element e)
		{
			Element element = null;
			object result;
			switch (this.Mode)
			{
			case ParamGettingMode.Self:
				element = e;
				break;
			case ParamGettingMode.Type:
				element = md.Doc.GetElement(e.GetTypeId());
				break;
			case ParamGettingMode.Host:
				element = e.GetHost();
				break;
			case ParamGettingMode.HostType:
			{
				Element host = e.GetHost();
				bool flag = host == null;
				if (flag)
				{
					result = null;
					return result;
				}
				element = md.Doc.GetElement(host.GetTypeId());
				break;
			}
			case ParamGettingMode.Parent:
			{
				FamilyInstance familyInstance = e as FamilyInstance;
				bool flag2 = familyInstance == null;
				if (flag2)
				{
					result = null;
					return result;
				}
				element = familyInstance.SuperComponent;
				break;
			}
			}
			bool flag3 = element == null;
			if (flag3)
			{
				result = null;
			}
			else
			{
				ParamId expr_B3 = this.ParamData.Id;
				Autodesk.Revit.DB.Parameter p = (expr_B3 != null) ? expr_B3.GetParameter(element) : null;
				result = FragmentBase.GetParameterValue(p, this.ParamData.FTid, this.ParamData.RoundDecimal);
			}
			return result;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			xElement.Add(new XElement("paramGettingMode", this.Mode));
			bool flag = this.ParamData != null;
			if (flag)
			{
				xElement = this.ParamData.Convert2Xml(xElement);
			}
			return xElement;
		}
