		private bool ValidateInt(System.Windows.Forms.TextBox txt, string errMsg, out int value)
		{
			bool flag = !int.TryParse(txt.Text, out value) || value < 1;
			bool result = false;
			if (flag)
			{
				MessageBox.Show(errMsg);
				txt.Focus();
				result = false;
			}
			else
			{
				result = true;
			}
			return result;
		}
		private bool ValidateString(System.Windows.Forms.TextBox txt, string errMsg)
		{
			bool flag = string.IsNullOrEmpty(txt.Text);
			bool result = false;
			if (flag)
			{
				MessageBox.Show(errMsg);
				txt.Focus();
				result = false;
			}
			else
			{
				result = true;
			}
			return result;
		}
