			case StringOperationType.IgnoreLeftN:
				this.SetEnableLook(this.rdoIgnoreLeftN, true);
				this.SetControlsEnabled(controls4, true);
				break;
			case StringOperationType.IgnoreRightN:
				this.SetEnableLook(this.rdoIgnoreRightN, true);
				this.SetControlsEnabled(controls5, true);
				break;
			case StringOperationType.IgnoreFromTo:
				this.SetEnableLook(this.rdoIgnoreFromTo, true);
				this.SetControlsEnabled(controls6, true);
				break;
			case StringOperationType.BeforePosition:
				this.SetEnableLook(this.rdoBeforePosition, true);
				this.SetControlsEnabled(controls7, true);
				break;
			case StringOperationType.AfterPosition:
				this.SetEnableLook(this.rdoAfterPosition, true);
				this.SetControlsEnabled(controls8, true);
				break;
			case StringOperationType.NfromPosition:
				this.SetEnableLook(this.rdoNfromPosition, true);
				this.SetControlsEnabled(controls9, true);
				break;
			case StringOperationType.Replace:
				this.SetEnableLook(this.rdoReplace, true);
				this.SetControlsEnabled(controls10, true);
				break;
			case StringOperationType.ArrayItem:
				this.SetEnableLook(this.rdoArrayItem, true);
				this.SetControlsEnabled(controls11, true);
				break;
			case StringOperationType.LetterCase:
				this.SetEnableLook(this.rdoLetterCase, true);
				this.cmbLetterCase.Enabled = true;
				break;
			}
		}
		private void SetControlsEnabled(IEnumerable<System.Windows.Forms.Control> controls, bool enabled)
		{
			foreach (System.Windows.Forms.Control current in controls)
			{
				current.Enabled = enabled;
			}
		}
		private void SetEnableLook(RadioButton rdo, bool enabled)
		{
			if (enabled)
			{
				rdo.ForeColor = SystemColors.ControlText;
				rdo.BackColor = SystemColors.Control;
			}
			else
			{
				rdo.ForeColor = SystemColors.GrayText;
				rdo.BackColor = SystemColors.Control;
			}
		}
		private void txtN_Validating(object sender, CancelEventArgs e)
		{
			System.Windows.Forms.TextBox textBox = sender as System.Windows.Forms.TextBox;
			bool flag = textBox != null;
			if (flag)
			{
				this._errP.SetIconAlignment(textBox, ErrorIconAlignment.MiddleRight);
				this._errP.SetIconPadding(textBox, 2);
				this._errP.SetError(textBox, string.Empty);
				string value = "Здесь должно быть целое число, больше или равное 1.";
				int num = 0;
				bool flag2 = !int.TryParse(textBox.Text, out num);
				if (flag2)
				{
					this._errP.SetError(textBox, value);
					e.Cancel = true;
				}
				else
				{
					bool flag3 = num < 1;
					if (flag3)
					{
						this._errP.SetError(textBox, value);
						e.Cancel = true;
					}
				}
			}
		}
		private void txtSubstring_Validating(object sender, CancelEventArgs e)
		{
			System.Windows.Forms.TextBox textBox = sender as System.Windows.Forms.TextBox;
			bool flag = textBox != null;
			if (flag)
			{
				this._errP.SetIconAlignment(textBox, ErrorIconAlignment.MiddleRight);
				this._errP.SetIconPadding(textBox, 2);
				this._errP.SetError(textBox, string.Empty);
				string value = "Здесь должна быть непустая строка.";
				bool flag2 = string.IsNullOrEmpty(textBox.Text);
				if (flag2)
				{
					this._errP.SetError(textBox, value);
					e.Cancel = true;
				}
			}
		}
