		public FrmSystemParam(Engine engine, XElement xeFragment = null)
		{
			this.Id = null;
			this.Mode = FewSystemsMode.JoinWithSeparator;
			this.IsInstanceParam = true;
			this.Sep = ",";
			this.components = null;
			
			this._engine = engine;
			this.InitializeComponent();
			this._state = new FormExt_State(this, this._engine.PluginXPath, 650, 380);
			this._state.ConfigRead();
			this._systemsModeUI = new EnumRadioButtonSet<FewSystemsMode>(FewSystemsMode.JoinWithSeparator);
			this._systemsModeUI.Add(FewSystemsMode.JoinWithSeparator, this.rdoJoinWithSeparator);
			this._systemsModeUI.Add(FewSystemsMode.MaxCount, this.rdoMaxCount);
			this._systemsModeUI.Add(FewSystemsMode.PrimaryConnector, this.rdoPrimaryConnector);
			this._systemsModeUI.AfterHandler = new EnumRadioButtonSet_After(this.Visibility);
			this._isNewRule = (xeFragment == null);
			bool flag = xeFragment != null;
			if (flag)
			{
				FragmentSystemParam fragmentSystemParam = new FragmentSystemParam(xeFragment);
				this.Id = fragmentSystemParam.Id;
				this.Mode = fragmentSystemParam.Mode;
				this._systemsModeUI.SetValue(this.Mode);
				this.IsInstanceParam = fragmentSystemParam.IsInstanceParam;
				this.Sep = fragmentSystemParam.Sep;
				this.txtParam.Text = ((this.Id.Name != "") ? this.Id.Name : this.Id.Comment);
			}
			else
			{
				this.txtParam.Text = "<не выбран>";
			}
			bool isInstanceParam = this.IsInstanceParam;
			if (isInstanceParam)
			{
				this.rdoIsInstanceParameter.Checked = true;
			}
			else
			{
				this.rdoIsTypeParameter.Checked = true;
			}
			this.txtSeparator.Text = this.Sep;
		}
		private void btnSelectParam_Click(object sender, EventArgs e)
		{
			List<ParamId> allParams = this._engine.Model.GetAllParams(StorageType.None, false);
			bool flag = allParams == null || !allParams.Any<ParamId>();
			if (flag)
			{
				MessageBox.Show("Не удалось получить параметры из проекта.");
			}
			else
			{
				bool isNewRule = this._isNewRule;
				FrmSelectParam3 frmSelectParam;
				if (isNewRule)
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, null, true);
				}
				else
				{
					frmSelectParam = new FrmSelectParam3(allParams, this._engine.PluginXPath, this.Id, true);
				}
				frmSelectParam.ShowDialog();
				bool flag2 = frmSelectParam.DialogResult == DialogResult.OK;
				if (flag2)
				{
					this.Id = new ParamId(frmSelectParam.SelectedParam);
					this.txtParam.Text = this.Id.Name;
				}
			}
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			this.IsInstanceParam = this.rdoIsInstanceParameter.Checked;
			this.Mode = this._systemsModeUI.CurrentValue;
			bool flag = !string.IsNullOrEmpty(this.txtSeparator.Text);
			if (flag)
			{
				this.Sep = this.txtSeparator.Text;
			}
			base.DialogResult = DialogResult.OK;
			base.Close();
		}
		private void Visibility()
		{
			this.txtSeparator.Enabled = this.rdoJoinWithSeparator.Checked;
		}
		protected override void Dispose(bool disposing)
		{
			bool flag = disposing && this.components != null;
			if (flag)
			{
				this.components.Dispose();
			}
			base.Dispose(disposing);
		}
