	public class ParamData
	{
		public const string FORGE_TYPE_ID = "forgeTypeId";
		public const string ROUND_DECIMAL = "roundDecimal";
		public string ErrReport
		{
			get;
			private set;
		}
		public ParamId Id
		{
			get;
			set;
		}
		public ForgeTypeId FTid
		{
			get;
			set;
		}
		public int RoundDecimal
		{
			get;
			set;
		}
		public ParamData()
		{
			this.ErrReport = "";
			this.Id = null;
			this.FTid = null;
			this.RoundDecimal = 2147483647;
			
		}
		public ParamData(ParamId id, ForgeTypeId ftid, int roundDecimal)
		{
			this.ErrReport = "";
			this.Id = null;
			this.FTid = null;
			this.RoundDecimal = 2147483647;
			
			bool flag = this.ErrReport != "";
			if (!flag)
			{
				this.Id = id;
				this.FTid = ftid;
				this.RoundDecimal = roundDecimal;
			}
		}
		public ParamData(ParamData paramData)
		{
			this.ErrReport = "";
			this.Id = null;
			this.FTid = null;
			this.RoundDecimal = 2147483647;
			
			bool flag = paramData == null || paramData.ErrReport != "";
			if (!flag)
			{
				this.Id = new ParamId(paramData.Id);
				bool flag2 = paramData.FTid.IsNotNull();
				if (flag2)
				{
					ForgeTypeId expr_70 = paramData.FTid;
					this.FTid = new ForgeTypeId((expr_70 != null) ? expr_70.TypeId : null);
				}
				this.RoundDecimal = paramData.RoundDecimal;
				this.ErrReport = paramData.ErrReport;
			}
		}
		public ParamData(XElement parent)
		{
			this.ErrReport = "";
			this.Id = null;
			this.FTid = null;
			this.RoundDecimal = 2147483647;
			
			bool flag = this.ErrReport != "";
			if (!flag)
			{
				string errReport;
				XElement xElement = ParamId.CompatibilityCheck(parent, out errReport);
				bool flag2 = xElement == null;
				if (flag2)
				{
					this.ErrReport = errReport;
				}
				else
				{
					this.Id = new ParamId(xElement);
					bool flag3 = this.Id.ErrReport != "";
					if (flag3)
					{
						this.ErrReport = this.Id.ErrReport;
					}
					else
					{
						XElement xElement2 = parent.Element("forgeTypeId");
						bool flag4 = xElement2 != null;
						if (flag4)
