							bool ok = result.Ok;
							if (ok)
							{
								this.RoundDecimal = (int)result.Value;
							}
							XElement xElement5 = xe.Element("operations");
							bool flag9 = xElement5 == null;
							if (flag9)
							{
								base.ErrReport = "не найден узел стека арифметических операций";
							}
							else
							{
								bool flag10 = xElement5.Elements("operation").Count<XElement>() == 0;
								if (flag10)
								{
									base.ErrReport = "пустой стек арифметических операций";
								}
								else
								{
									foreach (XElement current in xElement5.Elements("operation"))
									{
										CalcOperation calcOperation = new CalcOperation(current, md);
										bool flag11 = calcOperation.ErrReport != "";
										if (flag11)
										{
											base.ErrReport = "ошибка при определении арифметической операции";
											return;
										}
										this.Operations.Add(calcOperation);
									}
									this.Create();
								}
							}
						}
					}
				}
			}
		}
		private void Create()
		{
			base.Type = FragmentType.Calculator;
			base.DescriptionShort = string.Format("[калькулятор (действий: {0})]", this.Operations.Count);
			base.DescriptionDebug = "P calc: ";
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = this.Arg1 != null;
			if (flag)
			{
				stringBuilder.Append("Калькулятор " + this.Arg1.DescriptionLong);
			}
			foreach (CalcOperation current in this.Operations)
			{
				stringBuilder.Append(" ");
				stringBuilder.Append(current.GetDescritionLong());
			}
			base.DescriptionLong = stringBuilder.ToString();
		}
		public object GetValue(ModelData md, Element e)
		{
			object value = this.Arg1.GetValue(md, e);
			object obj = value;
			object result;
			foreach (CalcOperation current in this.Operations)
			{
				obj = current.Calc(obj, md, e);
				bool flag = obj == null;
				if (flag)
				{
					bool flag2 = current.ErrReport != "";
					if (flag2)
					{
						base.ErrReport = current.ErrReport;
					}
					result = null;
					return result;
				}
			}
			double num = double.NaN;
			int num2 = 2147483647;
			double num3 = 0.0;
			bool arg_AF_0 = false;
			if (obj is double)
			{
				num3 = (double)obj;
				arg_AF_0 = true;
			}
			else
			{
				arg_AF_0 = false;
			}
			bool flag3 = arg_AF_0;
			if (flag3)
			{
				num = num3;
				bool flag4 = this.FTid.IsNotNull();
				if (flag4)
				{
					num = UnitUtils.ConvertFromInternalUnits(num, this.FTid);
				}
			}
			else
			{
				int num4 = 0;
				bool arg_F0_0 = false;
				if (obj is int)
				{
					num4 = (int)obj;
					arg_F0_0 = true;
				}
				else
				{
					arg_F0_0 = false;
				}
				bool flag5 = arg_F0_0;
				if (flag5)
				{
					num2 = num4;
					bool flag6 = this.FTid.IsNotNull();
					if (flag6)
					{
						num = UnitUtils.ConvertFromInternalUnits((double)num2, this.FTid);
					}
				}
			}
			bool flag7 = !double.IsNaN(num);
			if (flag7)
			{
				bool flag8 = this.RoundDecimal != 2147483647;
				if (flag8)
				{
					num = Math.Round(num, this.RoundDecimal, MidpointRounding.AwayFromZero);
				}
				result = num;
			}
			else
			{
				bool flag9 = num2 != 2147483647;
				if (flag9)
				{
					result = num2;
				}
				else
				{
					result = null;
				}
			}
			return result;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			bool flag = this.Arg1 != null;
			if (flag)
			{
				XElement xElement2 = new XElement("arg1");
				xElement2.Add(this.Arg1.Convert2Xml());
				xElement.Add(xElement2);
			}
			bool flag2 = this.FTid.IsNotNull();
			if (flag2)
			{
				xElement.Add(new XElement("forgeTypeId", this.FTid.TypeId));
			}
			bool flag3 = this.RoundDecimal != 2147483647;
			if (flag3)
			{
				xElement.Add(new XElement("roundDecimal", this.RoundDecimal));
			}
			XElement xElement3 = new XElement("operations");
			bool flag4 = this.Operations != null;
			if (flag4)
			{
				foreach (CalcOperation current in this.Operations)
				{
					XElement content = current.Convert2Xml();
					xElement3.Add(content);
				}
			}
			xElement.Add(xElement3);
			return xElement;
		}
	}
