		public FrmCalc(Engine engine, string title, XElement xeFragmentCalc = null)
		{
			this._engine = engine;
			this.InitializeComponent();
			this.Text = title;
			this.ResultHandler = new ResultHandler(this.chkConvertTo, this.cmbDUT, this.chkRoundTo, this.cmbRoundDecimal, this.lblRoundTo, this._engine.AllUnits);
			this._curOperation = Operation.unknown;
			this.Operations = new List<CalcOperation>();
			this._state = new FormExt_State(this, this._engine.PluginXPath, 436, 478);
			this._state.SetPostConfigAction(new PostConfigAction(this.ResultHandler.Config));
			this._state.SetPostSavingAction(new PostSavingAction(this.ResultHandler.SaveTo));
			this._state.ConfigRead();
			bool flag = xeFragmentCalc != null;
			if (flag)
			{
				FragmentCalc fragmentCalc = new FragmentCalc(xeFragmentCalc, this._engine.Model);
				this.Arg1 = fragmentCalc.Arg1;
				this.ResultHandler.UpdateControls(fragmentCalc.FTid, fragmentCalc.RoundDecimal);
				this.Operations.AddRange(fragmentCalc.Operations);
				this.UpdateOperations();
			}
			else
			{
				this.Arg1 = null;
				this.txtCalcLog.Text = "";
			}
			this._errP = new ErrorProvider();
		}
		private void UpdateOperations()
		{
			bool flag = this.Arg1 == null;
			if (flag)
			{
				this.grpArgument.Text = "Aргумент 1";
			}
			else
			{
				this.grpArgument.Text = string.Format("Aргумент {0}", this.Operations.Count + 2);
			}
			StringBuilder stringBuilder = new StringBuilder();
			bool flag2 = this.Arg1 != null;
			if (flag2)
			{
				stringBuilder.AppendLine(this.Arg1.DescriptionLong);
			}
			foreach (CalcOperation current in this.Operations)
			{
				string operSymbol = this.GetOperSymbol(current.Type);
				bool flag3 = operSymbol != "";
				if (flag3)
				{
					stringBuilder.AppendLine(operSymbol);
				}
				bool flag4 = current.Argument != null;
				if (flag4)
				{
					stringBuilder.AppendLine(current.Argument.DescriptionLong);
				}
			}
			bool flag5 = this._curOperation != Operation.unknown;
			if (flag5)
			{
				string operSymbol2 = this.GetOperSymbol(this._curOperation);
				bool flag6 = operSymbol2 != "";
				if (flag6)
				{
					stringBuilder.AppendLine(operSymbol2);
				}
			}
			this.txtCalcLog.Text = stringBuilder.ToString();
		}
		private string GetOperSymbol(Operation op)
		{
			string result;
			switch (op)
			{
			case Operation.Add:
				result = "➕";
				break;
			case Operation.Multiply:
				result = "✖";
				break;
			case Operation.Subtraction:
				result = "➖";
				break;
			case Operation.Division:
				result = "➗";
				break;
			default:
				result = "";
				break;
			}
			return result;
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			this.ResultHandler.UpdateValues();
			bool flag = this.Arg1 == null;
			if (flag)
			{
				MessageBox.Show("Не задан аргумент 1");
			}
			else
			{
				bool flag2 = !this.Operations.Any<CalcOperation>();
				if (flag2)
				{
					MessageBox.Show("Не задано ни одной операции");
				}
				else
				{
					base.DialogResult = DialogResult.OK;
					base.Close();
				}
			}
		}
		private void txtNumber_Validating(object sender, CancelEventArgs e)
		{
			this._errP.SetIconAlignment(this.txtNumber, ErrorIconAlignment.MiddleRight);
			this._errP.SetIconPadding(this.txtNumber, 2);
			this._errP.SetError(this.txtNumber, string.Empty);
			string value = "Здесь должно быть целое или вещественное число.";
			int num = 0;
			bool flag = int.TryParse(this.txtNumber.Text, out num);
			if (!flag)
			{
				double num2 = 0.0;
				bool flag2 = this.txtNumber.Text.Try2Double(out num2);
				if (!flag2)
				{
					this._errP.SetError(this.txtNumber, value);
					e.Cancel = true;
				}
			}
		}
		private void btnSelectFragment_Click(object sender, EventArgs e)
		{
			FragmentService fragmentService = new FragmentService(this._engine);
			IFragment fragment = fragmentService.CreateOrEdit(FragmentType.ParameterValue, null);
			bool flag = fragment == null;
			if (!flag)
			{
				bool flag2 = fragment.ErrReport == "";
				if (flag2)
				{
					this.AddOperation((IArgument)fragment);
				}
				else
				{
					MessageBox.Show(fragment.ErrReport);
				}
			}
		}
		private void btnSelectNumber_Click(object sender, EventArgs e)
		{
			Scalar arg = new Scalar(this.txtNumber.Text);
			this.AddOperation(arg);
		}
		private void AddOperation(IArgument arg)
		{
			bool flag = arg == null;
			if (flag)
			{
				MessageBox.Show("Аргумент не задан");
			}
			else
			{
				bool flag2 = arg.ErrReport != "";
				if (flag2)
				{
					MessageBox.Show("Ошибка в аргументе: " + arg.ErrReport);
				}
				else
				{
					bool flag3 = this.Operations.Count == 0 && this._curOperation == Operation.unknown;
					if (flag3)
					{
						this.Arg1 = arg;
						this.UpdateOperations();
					}
					else
					{
						bool flag4 = this._curOperation == Operation.unknown;
						if (flag4)
						{
							MessageBox.Show("Выберите арифметическую операцию");
						}
						else
						{
							CalcOperation calcOperation = null;
							IFragment fragment = arg as IFragment;
							bool flag5 = fragment != null;
							if (flag5)
							{
								calcOperation = new CalcOperation(this._curOperation, fragment);
							}
							else
							{
								Scalar scalar = arg as Scalar;
								bool flag6 = scalar != null;
								if (flag6)
								{
									calcOperation = new CalcOperation(this._curOperation, scalar);
								}
							}
							bool flag7 = calcOperation != null;
							if (flag7)
							{
								this.Operations.Add(calcOperation);
								this._curOperation = Operation.unknown;
								this.UpdateOperations();
							}
						}
					}
				}
			}
		}
		private void btnAdd_Click(object sender, EventArgs e)
		{
			this._curOperation = Operation.Add;
			this.OperClick();
		}
		private void btnSubtract_Click(object sender, EventArgs e)
		{
			this._curOperation = Operation.Subtraction;
			this.OperClick();
		}
		private void btnMultiply_Click(object sender, EventArgs e)
		{
			this._curOperation = Operation.Multiply;
			this.OperClick();
		}
		private void btnDivide_Click(object sender, EventArgs e)
		{
			this._curOperation = Operation.Division;
			this.OperClick();
		}
		private void OperClick()
		{
			bool flag = this.Arg1 == null;
			if (flag)
			{
				MessageBox.Show("Сначала нужно указать аргумент 1");
				this._curOperation = Operation.unknown;
			}
			else
			{
				this.UpdateOperations();
			}
		}
		private void btnBackspace_Click(object sender, EventArgs e)
		{
			bool flag = this.Operations.Count > 0;
			if (flag)
			{
				this.Operations.RemoveAt(this.Operations.Count - 1);
				this._curOperation = Operation.unknown;
				this.UpdateOperations();
			}
			else
			{
				bool flag2 = this.Arg1 != null;
				if (flag2)
				{
					this.Arg1 = null;
					this._curOperation = Operation.unknown;
					this.UpdateOperations();
				}
			}
		}
		private void btnClear_Click(object sender, EventArgs e)
		{
			this.Operations.Clear();
			this.Arg1 = null;
			this._curOperation = Operation.unknown;
			this.UpdateOperations();
		}
