		public void FindConnectedDucts()
		{
			this.ConnectedDucts = new List<Element>();
			ConnectorSet connectors = this._mm.ConnectorManager.Connectors;
			this._p1 = null;
			this._p2 = null;
			ConnectorSetIterator connectorSetIterator = connectors.ForwardIterator();
			while (connectorSetIterator.MoveNext())
			{
				Connector connector = connectorSetIterator.Current as Connector;
				bool flag = connector != null && connector.IsConnected;
				if (flag)
				{
					bool flag2 = connector.ConnectorType == ConnectorType.End || connector.ConnectorType == ConnectorType.Curve || connector.ConnectorType == ConnectorType.Physical;
