						bool flag3 = connectedConnector != null;
						if (flag3)
						{
							Element owner = connectedConnector.Owner;
							bool flag4 = owner != null;
							if (flag4)
							{
								this.ConnectedDucts.Add(owner);
								bool flag5 = this._p1 == null;
								if (flag5)
								{
									this._p1 = connector.Origin;
									this.Profile = connector.Shape;
