	internal class RuleFragmentUtils
	{
		public static string GetSystemName1(ModelData md, string systemName)
		{
			string text = "";
			bool flag = systemName == "";
			string result;
			if (flag)
			{
				result = text;
			}
			else
			{
				MEPSystem mEPSystem = md.MEPsystems.Find((MEPSystem s) => s.Name == systemName);
				bool flag2 = mEPSystem == null;
				if (flag2)
				{
					result = text;
				}
				else
				{
					ElementId typeId = mEPSystem.GetTypeId();
					MEPSystemType mEPSystemType = md.Doc.GetElement(typeId) as MEPSystemType;
					string name = mEPSystemType.Name;
					string text2 = name.Substring(0, 1).ToUpper();
					text = name;
					bool flag3 = text2 == "Т" || text2 == "Х";
					if (flag3)
					{
						text = text2;
						bool flag4 = name.Length > 2;
						if (flag4)
						{
							text += name.Substring(2);
						}
					}
					result = text;
				}
			}
			return result;
		}
		public static string GetMepSystemName(Element e)
		{
			string systemNamesString = MepSystemService.GetSystemNamesString(e);
			bool flag = string.IsNullOrEmpty(systemNamesString);
			string result;
			if (flag)
			{
				MepSystemService mepSystemService = new MepSystemService(false, true, SysSelectMode.PrimaryConnector);
				MEPSystem system = mepSystemService.GetSystem(e);
				bool flag2 = system == null;
				if (flag2)
				{
					result = "";
				}
				else
				{
					result = system.Name;
				}
			}
			else
			{
				result = systemNamesString;
			}
			return result;
		}
		public static string[] GetSizes(Element e, string connectorSeparator)
		{
			string size = RuleFragmentUtils.GetSize(e);
			bool flag = size == null;
			string[] result;
			if (flag)
			{
				result = null;
			}
			else
			{
				result = RuleFragmentUtils.CuttingSize(size, connectorSeparator);
			}
			return result;
		}
		public static string GetShape(Element e)
		{
			string elementShape = MepElementShape.V5.GetElementShape(e);
			bool flag = elementShape == "unknown";
			if (flag)
			{
				elementShape = MepElementShape.V2.GetElementShape(e, null, null);
			}
			bool flag2 = elementShape == "unknown";
			string result;
			if (flag2)
			{
				result = null;
			}
			else
			{
				result = elementShape;
			}
			return result;
		}
		public static decimal GetMaxDiameter(string[] sizes, DuctSettings ds)
		{
			decimal result = 0m;
			bool flag = sizes.Length == 1;
			if (flag)
			{
				result = RuleFragmentUtils.GetDiameter(sizes[0], ds);
			}
			else
			{
				bool flag2 = sizes.Length == 2;
				if (flag2)
				{
					bool flag3 = sizes[0] != sizes[1];
					if (flag3)
					{
						decimal diameter = RuleFragmentUtils.GetDiameter(sizes[0], ds);
						decimal diameter2 = RuleFragmentUtils.GetDiameter(sizes[1], ds);
						result = ((diameter > diameter2) ? diameter : diameter2);
					}
					else
					{
						result = RuleFragmentUtils.GetDiameter(sizes[0], ds);
					}
				}
			}
			return result;
		}
		public static decimal GetMaxDimension(string[] sizes, DuctSettings ds)
		{
			decimal result = 0m;
			bool flag = sizes.Length == 1;
			if (flag)
			{
				result = RuleFragmentUtils.GetMaxDimension(sizes[0], ds);
			}
			else
			{
				bool flag2 = sizes.Length == 2;
				if (flag2)
				{
					bool flag3 = sizes[0] != sizes[1];
					if (flag3)
					{
						decimal maxDimension = RuleFragmentUtils.GetMaxDimension(sizes[0], ds);
						decimal maxDimension2 = RuleFragmentUtils.GetMaxDimension(sizes[1], ds);
						result = ((maxDimension > maxDimension2) ? maxDimension : maxDimension2);
					}
					else
					{
						result = RuleFragmentUtils.GetMaxDimension(sizes[0], ds);
					}
				}
			}
			return result;
		}
		public static string GetSize(Element e)
		{
			bool flag = e == null || !e.IsValidObject;
			string result;
			if (flag)
			{
				result = null;
			}
			else
			{
				Autodesk.Revit.DB.Parameter parameter = e.get_Parameter(BuiltInParameter.RBS_CALCULATED_SIZE);
				bool flag2 = parameter == null;
				if (flag2)
				{
					result = null;
				}
				else
				{
					result = parameter.AsString();
				}
			}
			return result;
		}
		public static string[] CuttingSize(string value, string sep)
		{
			string[] array = null;
			bool flag = value == null || value == "";
			string[] result;
			if (flag)
			{
				result = array;
			}
			else
			{
				bool flag2 = sep == "" || sep == null;
				if (flag2)
				{
					result = array;
				}
				else
				{
					string text = string.Copy(sep);
					int num = value.IndexOf(text);
					bool flag3 = num == -1;
					if (flag3)
					{
						text = "-";
						num = value.IndexOf(text);
					}
					bool flag4 = num == -1;
					if (flag4)
					{
						result = new string[]
						{
							value
						};
					}
					else
					{
						result = value.Split(new string[]
						{
							text
						}, StringSplitOptions.RemoveEmptyEntries);
					}
				}
			}
			return result;
		}
		public static decimal GetDiameter(string s)
		{
			bool flag = string.IsNullOrEmpty(s);
			decimal result;
			if (flag)
			{
				result = decimal.Zero;
			}
			else
			{
				s = s.Replace("ø", "");
				decimal num;
				bool flag2 = decimal.TryParse(s, out num);
				if (flag2)
				{
					result = num;
				}
				else
				{
					result = decimal.Zero;
				}
			}
			return result;
		}
		public static decimal GetDiameter(string s, DuctSettings ds)
		{
			bool flag = string.IsNullOrEmpty(s);
			decimal result;
			if (flag)
			{
				result = decimal.Zero;
			}
			else
			{
				bool flag2 = !string.IsNullOrEmpty(ds.RoundDuctSizePrefix);
				if (flag2)
				{
					s = s.Replace(ds.RoundDuctSizePrefix, "");
				}
				bool flag3 = !string.IsNullOrEmpty(ds.RoundDuctSizeSuffix);
				if (flag3)
				{
					s = s.Replace(ds.RoundDuctSizeSuffix, "");
				}
				s = s.Replace("мм", "");
				s = s.Replace(" ", "");
				decimal num;
				bool flag4 = decimal.TryParse(s, out num);
				if (flag4)
				{
					result = num;
				}
				else
				{
					result = decimal.Zero;
				}
			}
			return result;
		}
		public static List<decimal> GetThiknesses(Element e, DuctSettings ds)
		{
			List<decimal> list = new List<decimal>();
			string[] sizes = RuleFragmentUtils.GetSizes(e, ds.ConnectorSeparator);
			bool flag = sizes == null;
			List<decimal> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				string[] array = sizes;
				for (int i = 0; i < array.Length; i++)
				{
					string text = array[i];
					Log.Write("Элемент " + e.Description());
					Log.Write("Size " + text);
					decimal thickness = RuleFragmentUtils.GetThickness(text, ds);
					Log.Write(string.Format("thikness {0}", thickness));
					bool flag2 = thickness == decimal.Zero;
					if (flag2)
					{
						result = list;
						return result;
					}
					list.Add(thickness);
				}
				result = list;
			}
			return result;
		}
		public string GetMaxThikness(Element e, DuctSettings ds)
		{
			List<decimal> thiknesses = RuleFragmentUtils.GetThiknesses(e, ds);
			bool flag = !thiknesses.Any<decimal>();
			string result;
			if (flag)
			{
				result = null;
			}
			else
			{
				result = thiknesses.Max().ToString("0.##", CultureInfo.InvariantCulture);
			}
			return result;
		}
		public static decimal GetThickness(string size, DuctSettings ds)
		{
			bool flag = string.IsNullOrEmpty(size);
			decimal result;
			if (flag)
			{
				result = decimal.Zero;
			}
			else
			{
				bool flag2 = size[0].ToString() == ds.RoundDuctSizePrefix;
				if (flag2)
				{
					decimal diameter = RuleFragmentUtils.GetDiameter(size, ds);
					bool flag3 = diameter == decimal.Zero;
					if (flag3)
					{
						result = decimal.Zero;
					}
					else
					{
						bool flag4 = diameter <= 315m;
						if (flag4)
						{
							result = 0.5m;
						}
						else
						{
							result = 0.7m;
						}
					}
				}
				else
				{
					decimal maxDimension = RuleFragmentUtils.GetMaxDimension(size, ds);
					bool flag5 = maxDimension == decimal.Zero;
					if (flag5)
					{
						result = decimal.Zero;
					}
					else
					{
						bool flag6 = maxDimension <= 500m;
						if (flag6)
						{
							result = 0.5m;
						}
						else
						{
							bool flag7 = maxDimension <= 1000m;
							if (flag7)
							{
								result = 0.7m;
							}
							else
							{
								result = 0.9m;
							}
						}
					}
				}
			}
			return result;
		}
		public static decimal GetMaxDimension(string s, DuctSettings ds)
		{
			bool flag = string.IsNullOrEmpty(s);
			decimal result;
			if (flag)
			{
				result = decimal.Zero;
			}
			else
			{
				bool flag2 = string.IsNullOrEmpty(ds.RectangularDuctSizeSeparator);
				if (flag2)
				{
					result = decimal.Zero;
				}
				else
				{
					string[] array = RuleFragmentUtils.CuttingSize(s, ds.RectangularDuctSizeSeparator);
					bool flag3 = array == null || array.Length != 2;
					if (flag3)
					{
						result = decimal.Zero;
					}
					else
					{
						decimal num;
						decimal.TryParse(array[0], out num);
						decimal num2;
						decimal.TryParse(array[1], out num2);
						result = ((num > num2) ? num : num2);
					}
				}
			}
			return result;
		}
	}
}
namespace SAV.ParamRules.Fragments.StringOperations
{
	public enum LetterCaseMode
	{
		ToUpper,
		ToLower,
		Capitalize,
		Invert,
		TitleCase
	}
	internal class AfterPosition : OperSubstrBase, IStringOperation
	{
		public AfterPosition(string substring) : base(substring)
		{
			base.Type = StringOperationType.AfterPosition;
			this.Init();
		}
		public AfterPosition(XElement xe) : base(xe)
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				this.Init();
			}
		}
		private void Init()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				base.DescriptionShort = "символы после '" + base.Substring + "'";
				base.DescriptionLong = "Получение всех символов после первого вхождения подстроки '" + base.Substring + "' (не включительно)";
				base.DescriptionDebug = string.Format("{0}'{1}'", base.Type, base.Substring);
			}
		}
		public override string Apply(string s)
		{
			bool flag = string.IsNullOrEmpty(s) || string.IsNullOrEmpty(base.Substring);
			string result;
			if (flag)
			{
				result = s;
			}
			else
			{
				int num = s.IndexOf(base.Substring, StringComparison.OrdinalIgnoreCase);
				bool flag2 = num == -1;
				if (flag2)
				{
					result = s;
				}
				else
				{
					result = s.Substring(num + base.Substring.Length);
				}
			}
			return result;
		}
	}
	internal class ArrayItem : OperStrAndNBase, IStringOperation
	{
		public ArrayItem(string substring, int n) : base(substring, n - 1)
		{
			base.Type = StringOperationType.ArrayItem;
			this.Init();
		}
		public ArrayItem(XElement xe) : base(xe)
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				this.Init();
			}
		}
		private void Init()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				base.DescriptionShort = string.Format("{0}-й элемент посл-ти", base.N + 1);
				base.DescriptionLong = string.Format("Получение {0}-го элемента последовательности, полученной из строки с помощью разделителя '{1}'", base.N + 1, base.Substring);
				base.DescriptionDebug = string.Format("{0}'{1}'[{2}]", base.Type, base.Substring, base.N + 1);
			}
		}
		public override string Apply(string s)
		{
			bool flag = string.IsNullOrEmpty(s);
			string result;
			if (flag)
			{
				result = s;
			}
			else
			{
				bool flag2 = string.IsNullOrEmpty(base.Substring);
				if (flag2)
				{
					result = "";
				}
				else
				{
					bool flag3 = base.N < 0;
					if (flag3)
					{
						result = "";
					}
					else
					{
						string[] array = s.Split(new string[]
						{
							base.Substring
						}, StringSplitOptions.None);
						bool flag4 = base.N >= array.Length;
						if (flag4)
						{
							result = "";
						}
						else
						{
							result = array[base.N];
						}
					}
				}
			}
			return result;
		}
	}
	internal class LetterCase : OperBase, IStringOperation
	{
		public const string _MODE = "mode";
		public LetterCaseMode Mode
		{
			get;
			private set;
		}
		public LetterCase(LetterCaseMode mode)
		{
			this.Mode = LetterCaseMode.ToLower;
			
			this.Mode = mode;
			base.Type = StringOperationType.LetterCase;
			this.Init();
		}
		public LetterCase(XElement xe) : base(xe) {
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				this.Mode = LetterCaseMode.ToLower;
				SAV.Extension.Result result = xe.Parse<LetterCaseMode>("mode", false);
				bool ok = result.Ok;
				if (ok)
				{
					this.Mode = (LetterCaseMode)result.Value;
				}
				this.Init();
			}
		}
		private void Init()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				switch (this.Mode)
				{
				case LetterCaseMode.ToUpper:
					base.DescriptionShort = "ПРОПИСНЫЕ";
					base.DescriptionLong = "Преобразование строки в верхний регистр";
					break;
				case LetterCaseMode.ToLower:
					base.DescriptionShort = "строчные";
					base.DescriptionLong = "Преобразование строки в нижний регистр";
					break;
				case LetterCaseMode.Capitalize:
					base.DescriptionShort = "Предложение";
					base.DescriptionLong = "Преобразование первой буквы строки в заглавную, остальные в строчные";
					break;
				case LetterCaseMode.Invert:
					base.DescriptionShort = "иНВЕРТИРОВАТЬ рЕГИСТР";
					base.DescriptionLong = "Преобразование регистра букв в строке на противоположный";
					break;
				case LetterCaseMode.TitleCase:
					base.DescriptionShort = "Всё с Заглавной";
					base.DescriptionLong = "Преобразование первой буквы каждого слова в заглавную, остальные в строчные";
					break;
				default:
					base.ErrReport = "некорректный режим преобразования регистра";
					return;
				}
				base.DescriptionDebug = string.Format("{0}[{1}]", base.Type, this.Mode);
			}
		}
		public string Apply(string s)
		{
			bool flag = string.IsNullOrEmpty(s);
			string result;
			if (flag)
			{
				result = s;
			}
			else
			{
				switch (this.Mode)
				{
				case LetterCaseMode.ToUpper:
					result = s.ToUpper();
					break;
				case LetterCaseMode.ToLower:
					result = s.ToLower();
					break;
				case LetterCaseMode.Capitalize:
					result = s.Capitalize();
					break;
				case LetterCaseMode.Invert:
					result = s.InvertCase();
					break;
				case LetterCaseMode.TitleCase:
					result = s.TitleCase();
					break;
				default:
					result = s;
					break;
				}
			}
			return result;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			xElement.Add(new XElement("mode", this.Mode));
			return xElement;
		}
	}
	internal class OperStrAndNBase : OperBase, IStringOperation
	{
		private const string _SUBSTR = "substring";
		private const string _N = "n";
		public string Substring
		{
			get;
			private set;
		}
		public int N
		{
			get;
			set;
		}
		public OperStrAndNBase(string substring, int n)
		{
			this.Substring = "";
			this.N = -1;
			
			this.Substring = substring;
			this.N = n;
			this.InitBase();
		}
		public OperStrAndNBase(XElement xe) : base(xe) {
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				SAV.Extension.Result result = xe.Parse<string>("substring", false);
				bool ok = result.Ok;
				if (ok)
				{
					this.Substring = XmlConvert.DecodeName((string)result.Value);
					SAV.Extension.Result result2 = xe.Parse<int>("n", false);
					bool ok2 = result2.Ok;
					if (ok2)
					{
						this.N = (int)result2.Value;
						this.InitBase();
					}
					else
					{
						base.ErrReport = result2.ErrMsg;
					}
				}
				else
				{
					base.ErrReport = result.ErrMsg;
				}
			}
		}
		private void InitBase()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				bool flag2 = string.IsNullOrEmpty(this.Substring);
				if (flag2)
				{
					base.ErrReport = "не задана строка";
				}
				else
				{
					bool flag3 = this.N < 0;
					if (flag3)
					{
						base.ErrReport = "некорректное целое число";
					}
				}
			}
		}
		public virtual string Apply(string s)
		{
			return s;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			xElement.Add(new XElement("substring", XmlConvert.EncodeName(this.Substring)));
			xElement.Add(new XElement("n", this.N));
			return xElement;
		}
	}
	internal class NfromPosition : OperStrAndNBase, IStringOperation
	{
		public NfromPosition(string substring, int n) : base(substring, n)
		{
			base.Type = StringOperationType.NfromPosition;
			this.Init();
		}
		public NfromPosition(XElement xe) : base(xe)
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				this.Init();
			}
		}
		private void Init()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				base.DescriptionShort = string.Format("{0} симв. после '{1}'", base.N, base.Substring);
				base.DescriptionLong = string.Format("Получение {0} символов после подстроки '{1}' (не включительно)", base.N, base.Substring);
				base.DescriptionDebug = string.Format("{0}[{1}]'{2}'", base.Type, base.N, base.Substring);
			}
		}
		public override string Apply(string s)
		{
			bool flag = string.IsNullOrEmpty(s);
			string result;
			if (flag)
			{
				result = s;
			}
			else
			{
				bool flag2 = base.N < 1;
				if (flag2)
				{
					result = "";
				}
				else
				{
					int num = s.IndexOf(base.Substring, StringComparison.OrdinalIgnoreCase);
					bool flag3 = num == -1;
					if (flag3)
					{
						result = "";
					}
					else
					{
						int num2 = num + base.Substring.Length;
						bool flag4 = num2 >= s.Length;
						if (flag4)
						{
							result = "";
						}
						else
						{
							int val = s.Length - num2;
							int length = Math.Min(base.N, val);
							result = s.Substring(num2, length);
						}
					}
				}
			}
			return result;
		}
	}
	internal class IgnoreFromTo : OperStartEndBase, IStringOperation
	{
		public IgnoreFromTo(int startIndex, int endIndex) : base(startIndex, endIndex)
		{
			base.Type = StringOperationType.IgnoreFromTo;
			this.Init();
		}
		public IgnoreFromTo(XElement xe) : base(xe)
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				this.Init();
			}
		}
		private void Init()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				base.DescriptionShort = string.Format("кроме [{0}..{1}]", base.StartIndex + 1, base.EndIndex + 1);
				base.DescriptionLong = string.Format("Удаление символов с {0}-го по {1}-й", base.StartIndex + 1, base.EndIndex + 1);
				base.DescriptionDebug = string.Format("{0}[{1}..{2}]", base.Type, base.StartIndex + 1, base.EndIndex + 1);
			}
		}
		public override string Apply(string s)
		{
			bool flag = string.IsNullOrEmpty(s);
			string result;
			if (flag)
			{
				result = s;
			}
			else
			{
				int num = (base.StartIndex < 0) ? 0 : base.StartIndex;
				int num2 = (base.EndIndex > s.Length - 1) ? (s.Length - 1) : base.EndIndex;
				bool flag2 = num2 < 0 || num > s.Length - 1;
				if (flag2)
				{
					result = s;
				}
				else
				{
					int num3 = num2 - num + 1;
					bool flag3 = num3 < 1;
					if (flag3)
					{
						result = s;
					}
					else
					{
						result = s.Remove(num, num3);
					}
				}
			}
			return result;
		}
	}
