	internal class Replace : OperBase, IStringOperation
	{
		private const string _FIND = "find";
		private const string _REPLACE = "replace";
		public string FindString
		{
			get;
			private set;
		}
		public string ReplaceString
		{
			get;
			private set;
		}
		public Replace(string find, string replace)
		{
			this.FindString = "";
			this.ReplaceString = "";
			
			this.FindString = find;
			this.ReplaceString = replace;
			base.Type = StringOperationType.Replace;
			this.Init();
		}
		public Replace(XElement xe) : base(xe) {
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				SAV.Extension.Result result = xe.Parse<string>("find", false);
				bool ok = result.Ok;
				if (ok)
				{
					this.FindString = XmlConvert.DecodeName((string)result.Value);
					SAV.Extension.Result result2 = xe.Parse<string>("replace", true);
					bool ok2 = result2.Ok;
					if (ok2)
					{
						this.ReplaceString = XmlConvert.DecodeName((string)result2.Value);
						this.Init();
					}
					else
					{
						base.ErrReport = result2.ErrMsg;
					}
				}
				else
				{
					base.ErrReport = result.ErrMsg;
				}
			}
		}
		private void Init()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				bool flag2 = string.IsNullOrEmpty(this.FindString);
				if (flag2)
				{
					base.ErrReport = "не задана строка для поиска";
				}
				else
				{
					base.DescriptionShort = string.Concat(new string[]
					{
						"замена '",
						this.FindString,
						"' на '",
						this.ReplaceString,
						"'"
					});
					base.DescriptionLong = string.Concat(new string[]
					{
						"Замена подстроки '",
						this.FindString,
						"' на '",
						this.ReplaceString,
						"'"
					});
					base.DescriptionDebug = string.Format("{0}'{1}''{2}'", base.Type, this.FindString, this.ReplaceString);
				}
			}
		}
		public virtual string Apply(string s)
		{
			bool flag = string.IsNullOrEmpty(s) || string.IsNullOrEmpty(this.FindString);
			string result;
			if (flag)
			{
				result = s;
			}
			else
			{
				result = s.Replace(this.FindString, this.ReplaceString ?? string.Empty);
			}
			return result;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			xElement.Add(new XElement("find", XmlConvert.EncodeName(this.FindString ?? "")));
			xElement.Add(new XElement("replace", XmlConvert.EncodeName(this.ReplaceString ?? "")));
			return xElement;
		}
	}
