	internal class OperBase
	{
		public const string MAIN_NODE = "strOperation";
		public const string TYPE = "type";
		public StringOperationType Type
		{
			get;
			set;
		}
		public string ErrReport
		{
			get;
			set;
		}
		public string DescriptionShort
		{
			get;
			set;
		}
		public string DescriptionLong
		{
			get;
			set;
		}
		public string DescriptionDebug
		{
			get;
			set;
		}
		public OperBase()
		{
			this.ErrReport = "";
			this.DescriptionShort = "";
			this.DescriptionLong = "";
			this.DescriptionDebug = "";
			
		}
		public OperBase(XElement xe)
		{
			this.ErrReport = "";
			this.DescriptionShort = "";
			this.DescriptionLong = "";
			this.DescriptionDebug = "";
			
			string errReport;
			this.Type = OperBase.GetOperationType(xe, out errReport).GetValueOrDefault();
			this.ErrReport = errReport;
		}
		public static StringOperationType? GetOperationType(XElement xe, out string errReport)
		{
			errReport = "";
			StringOperationType? stringOperationType = null;
			bool flag = xe == null || xe.Name != "strOperation";
			StringOperationType? result;
			if (flag)
			{
				errReport = "не удалось получить тип операции над строкой";
				result = null;
			}
			else
			{
				XAttribute xa = xe.Attribute("type");
				SAV.Extension.Result result2 = xa.Parse<FragmentType>(false);
				bool ok = result2.Ok;
				if (ok)
				{
					stringOperationType = new StringOperationType?((StringOperationType)result2.Value);
				}
				else
				{
					errReport = result2.ErrMsg;
				}
				result = stringOperationType;
			}
			return result;
		}
		public virtual XElement Convert2Xml()
		{
			return new XElement("strOperation", new XAttribute("type", this.Type));
		}
	}
