	internal class OperStartEndBase : OperBase, IStringOperation
	{
		private const string _START_INDEX = "startIndex";
		private const string _END_INDEX = "endIndex";
		public int StartIndex
		{
			get;
			private set;
		}
		public int EndIndex
		{
			get;
			private set;
		}
		public OperStartEndBase(int startIndex, int endIndex)
		{
			this.StartIndex = -1;
			this.EndIndex = -1;
			
			base.Type = StringOperationType.Substring;
			this.StartIndex = startIndex - 1;
			this.EndIndex = endIndex - 1;
			this.InitBase();
		}
		public OperStartEndBase(XElement xe) : base(xe) {
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				SAV.Extension.Result result = xe.Parse<int>("startIndex", false);
				bool ok = result.Ok;
				if (ok)
				{
					this.StartIndex = (int)result.Value;
					SAV.Extension.Result result2 = xe.Parse<int>("endIndex", false);
					bool ok2 = result2.Ok;
					if (ok2)
					{
						this.EndIndex = (int)result2.Value;
						this.InitBase();
					}
					else
					{
						base.ErrReport = result2.ErrMsg;
					}
				}
				else
				{
					base.ErrReport = result.ErrMsg;
				}
			}
		}
		private void InitBase()
		{
			bool flag = base.ErrReport != "";
			if (!flag)
			{
				bool flag2 = this.StartIndex < -1;
				if (flag2)
				{
					base.ErrReport = "некорректный начальный индекс";
				}
				else
				{
					bool flag3 = this.EndIndex < -1;
					if (flag3)
					{
						base.ErrReport = "некорректный конечный индекс";
					}
					else
					{
						bool flag4 = this.StartIndex > this.EndIndex;
						if (flag4)
						{
							base.ErrReport = "начальный индекс не может быть больше конечного индекса";
						}
					}
				}
			}
		}
		public virtual string Apply(string s)
		{
			return s;
		}
		public override XElement Convert2Xml()
		{
			XElement xElement = base.Convert2Xml();
			xElement.Add(new XElement("startIndex", this.StartIndex));
			xElement.Add(new XElement("endIndex", this.EndIndex));
			return xElement;
		}
	}
