	public static class InternalGeom
	{
		private static readonly string _PRECISION_RANGE_ERROR = "Error: Precision is out of range.";
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		internal static double CrossProduct(Point64 pt1, Point64 pt2, Point64 pt)
		{
			double num = (double)((pt2.X - pt1.X) * (pt.Y - pt2.Y));
			double num2 = (double)((pt2.Y - pt1.Y) * (pt.X - pt2.X));
			return num - num2;
		}
		internal static void CheckPrecision(int precision)
		{
			bool flag = precision < -8 || precision > 8;
			if (flag)
			{
				throw new Exception(InternalGeom._PRECISION_RANGE_ERROR);
			}
		}
