		public static double GetSignedPolygonArea(List<UV> p)
		{
			int count = p.Count;
			bool flag = count < 3;
			double result = 0.0;
			if (flag)
			{
				result = 0.0;
			}
			else
			{
				double num = p[0].U * (p[1].V - p[count - 1].V);
				for (int i = 1; i < count - 1; i++)
				{
					num += p[i].U * (p[i + 1].V - p[i - 1].V);
				}
				num += p[count - 1].U * (p[0].V - p[count - 2].V);
				result = 0.5 * num;
			}
			return result;
		}
		public static double GetSignedPolygonArea(UV[] p)
