			double result = 0.0;
			if (flag)
			{
				result = 0.0;
			}
			else
			{
				double num2 = p[0].U * (p[1].V - p[num - 1].V);
				for (int i = 1; i < num - 1; i++)
				{
					num2 += p[i].U * (p[i + 1].V - p[i - 1].V);
				}
				num2 += p[num - 1].U * (p[0].V - p[num - 2].V);
				result = 0.5 * num2;
			}
			return result;
		}
		internal static bool GetPolygonPlane(List<XYZ> polygon, out XYZ normal, out double dist, out double area)
		{
			normal = XYZ.Zero;
			dist = (area = 0.0);
			int num = (polygon == null) ? 0 : polygon.Count;
			bool flag = 2 < num;
			bool flag2 = 3 == num;
			if (flag2)
			{
				XYZ xYZ = polygon[0];
				XYZ left = polygon[1];
				XYZ left2 = polygon[2];
				XYZ xYZ2 = left - xYZ;
				normal = xYZ2.CrossProduct(left2 - xYZ);
				dist = normal.DotProduct(xYZ);
			}
			else
			{
				bool flag3 = 4 == num;
				if (flag3)
				{
					XYZ xYZ3 = polygon[0];
					XYZ xYZ4 = polygon[1];
					XYZ xYZ5 = polygon[2];
					XYZ xYZ6 = polygon[3];
					normal = new XYZ((xYZ5.Y - xYZ3.Y) * (xYZ6.Z - xYZ4.Z) + (xYZ5.Z - xYZ3.Z) * (xYZ4.Y - xYZ6.Y), (xYZ5.Z - xYZ3.Z) * (xYZ6.X - xYZ4.X) + (xYZ5.X - xYZ3.X) * (xYZ4.Z - xYZ6.Z), (xYZ5.X - xYZ3.X) * (xYZ6.Y - xYZ4.Y) + (xYZ5.Y - xYZ3.Y) * (xYZ4.X - xYZ6.X));
					dist = 0.25 * (normal.X * (xYZ3.X + xYZ4.X + xYZ5.X + xYZ6.X) + normal.Y * (xYZ3.Y + xYZ4.Y + xYZ5.Y + xYZ6.Y) + normal.Z * (xYZ3.Z + xYZ4.Z + xYZ5.Z + xYZ6.Z));
				}
				else
				{
					bool flag4 = 4 < num;
					if (flag4)
					{
						XYZ xYZ7 = polygon[num - 2];
						XYZ xYZ8 = polygon[num - 1];
						XYZ xYZ9 = XYZ.Zero;
						for (int i = 0; i < num; i++)
						{
							XYZ xYZ10 = xYZ7;
							xYZ7 = xYZ8;
							xYZ8 = polygon[i];
							normal = new XYZ(normal.X + xYZ7.Y * (xYZ8.Z - xYZ10.Z), normal.Y + xYZ7.Z * (xYZ8.X - xYZ10.X), normal.Z + xYZ7.X * (xYZ8.Y - xYZ10.Y));
							xYZ9 += xYZ8;
						}
						dist = xYZ9.DotProduct(normal) / (double)num;
					}
				}
			}
			bool flag5 = flag;
			if (flag5)
			{
				double length = normal.GetLength();
				flag = !length.IsZero();
				bool flag6 = flag;
				if (flag6)
				{
					normal /= length;
					dist /= length;
					area = 0.5 * length;
				}
			}
			return flag;
		}
