		private static Transform GetTransformToZ(XYZ v)
		{
			double num = XYZ.BasisZ.AngleTo(v);
			bool flag = num.IsZero();
			Transform result;
			if (flag)
			{
				result = Transform.Identity;
			}
			else
			{
				XYZ axis = num.IsEqual(3.1415926535897931) ? XYZ.BasisX : v.CrossProduct(XYZ.BasisZ);
				result = Transform.CreateRotation(axis, num);
