		public static List<List<XYZ>> GetBoundary(Solid solid)
		{
			List<List<XYZ>> list = new List<List<XYZ>>();
			PlanarFace planarFace = null;
			FaceArray faces = solid.Faces;
			foreach (Face face in faces)
			{
				PlanarFace planarFace2 = face as PlanarFace;
				bool flag = null != planarFace2 && planarFace2.IsHorizontal();
				if (flag)
				{
					bool flag2 = null == planarFace || planarFace2.Origin.Z < planarFace.Origin.Z;
					if (flag2)
					{
						planarFace = planarFace2;
					}
				}
			}
			bool flag3 = planarFace == null;
			List<List<XYZ>> result;
			if (flag3)
			{
				result = list;
			}
			else
			{
				XYZ xYZ = XYZ.Zero;
				EdgeArrayArray edgeLoops = planarFace.EdgeLoops;
				foreach (EdgeArray edgeArray in edgeLoops)
				{
					List<XYZ> list2 = new List<XYZ>();
					bool flag4 = true;
					foreach (Edge edge in edgeArray)
					{
						IList<XYZ> list3 = edge.Tessellate();
						XYZ xYZ2 = list3[0];
						bool flag5 = !flag4;
						if (flag5)
						{
							Debug.Assert(xYZ2.IsAlmostEqualTo(xYZ), "expected subsequent start point to equal previous end point");
						}
						int count = list3.Count;
						xYZ = list3[count - 1];
						for (int i = 0; i < count - 1; i++)
						{
							XYZ xYZ3 = list3[i];
							xYZ3 -= 0.1 * XYZ.BasisZ;
							list2.Add(xYZ3);
						}
					}
					xYZ -= 0.1 * XYZ.BasisZ;
					Debug.Assert(xYZ.IsAlmostEqualTo(list2[0]), "expected last end point to equal first start point");
					list.Add(list2);
				}
				result = list;
			}
			return result;
		}
