		public static void GetClosestEdge(List<XYZ> polygon, XYZ point, out XYZ a, out XYZ b, bool isPolygon = true)
		{
			double num = 2147483647.0;
			int num2 = -1;
			for (int i = 0; i < polygon.Count - 1; i++)
			{
				Line line = Line.CreateBound(polygon[i], polygon[i + 1]);
				double num3 = line.Distance(point);
				bool flag = num3 < num;
				if (flag)
				{
					num = num3;
					num2 = i;
				}
			}
			a = polygon[num2];
			b = polygon[num2 + 1];
			if (isPolygon)
			{
				Line line2 = Line.CreateBound(polygon[0], polygon[polygon.Count - 1]);
				double num4 = line2.Distance(point);
				bool flag2 = num4 < num;
				if (flag2)
				{
					a = polygon[0];
					b = polygon[polygon.Count - 1];
				}
			}
		}
