				{
					num = signedPolygonArea;
				}
				array[i++] = signedPolygonArea;
			}
			Debug.Print("Найдено граничных контуров: {0}.", new object[]
			{
				count
			});
			for (i = 0; i < count; i++)
			{
				Debug.Print("  Loop {0} area is {1} square feet{2}", new object[]
				{
					i,
					array[i].GetShortNumber(),
					array[i].Equals(num) ? ", outer loop of largest floor slab" : ""
				});
			}
		}
