		public static XYZ GetPolygonMassCenter(List<XYZ> points, bool finishIsNotStart, double tolerance = 1E-08)
		{
			bool flag = points == null;
			XYZ result;
			if (flag)
			{
				result = null;
			}
			else
			{
				bool flag2 = points.Count == 0;
				if (flag2)
				{
					result = null;
				}
				else
				{
					bool flag3 = points.Count == 1;
					if (flag3)
					{
						result = points[0];
					}
					else
					{
						bool flag4 = points.Count == 2;
						if (flag4)
						{
							result = XYZext.LineMiddle(points[0], points[1]);
						}
						else
						{
							double z = points[0].Z;
							if (finishIsNotStart)
							{
								points.Add(new XYZ(points[0].X, points[0].Y, z));
							}
							XYZ[] array = points.ToArray();
							double num = 0.0;
							double num2 = 0.0;
							double num3 = 0.0;
							for (int i = 0; i < array.Length - 1; i++)
							{
								double num4 = array[i].X * array[i + 1].Y - array[i + 1].X * array[i].Y;
								num += (array[i].X + array[i + 1].X) * num4;
								num2 += (array[i].Y + array[i + 1].Y) * num4;
								num3 += num4 / 2.0;
							}
							bool flag5 = Math.Abs(num3) >= tolerance;
							XYZ xYZ;
							if (flag5)
							{
								num = num / 6.0 / num3;
								num2 = num2 / 6.0 / num3;
								xYZ = new XYZ(num, num2, z);
							}
							else
							{
								XYZ a;
								XYZ b;
								Polygon.GetLineEnds(points, out a, out b, tolerance);
								xYZ = XYZext.LineMiddle(a, b);
							}
							if (finishIsNotStart)
							{
								points.RemoveAt(points.Count - 1);
							}
							result = xYZ;
						}
					}
				}
			}
			return result;
		}
		public static UV GetPolygonMassCenter(UV[] points, double tolerance = 1E-08)
		{
			bool flag = points == null;
			UV result;
			if (flag)
