									solid = BooleanOperationsUtils.ExecuteBooleanOperation(current, current2, BooleanOperationsType.Intersect);
								}
								catch (Autodesk.Revit.Exceptions.InvalidOperationException)
								{
									isGeomCollision = true;
									continue;
								}
								catch (Exception ex)
								{
									Log.Write("Ошибка в методе RUtil.Get2SolidsIntersection:");
									Log.Write(ex);
									continue;
								}
								bool flag4 = Math.Abs(solid.Volume) > tolerance;
								if (flag4)
								{
									result = solid;
									return result;
								}
							}
						}
					}
				}
				result = null;
			}
			return result;
		}
		public List<Curve> GetCurves(GeomResult gr)
		{
			List<Curve> list = new List<Curve>();
			list.AddRange(gr.Curves);
			foreach (Solid current in gr.Solids)
			{
				bool flag = current.Volume.IsZero();
				if (!flag)
				{
					foreach (Edge edge in current.Edges)
					{
						list.Add(edge.AsCurve());
					}
				}
			}
			return list;
		}
	}
