		public FrmSelectCategories(List<ValueTuple<BuiltInCategory, CategoryType, string>> fullList, string parentXpath, string formTitle, List<ValueTuple<BuiltInCategory, string>> selected = null)
		{
			this.Selected = new List<BuiltInCategory>();
			this.Comments = new List<string>();
			this._modelCats = new List<ValueTuple<BuiltInCategory, string>>();
			this._annotationCats = new List<ValueTuple<BuiltInCategory, string>>();
			this._analyticalModelCats = new List<ValueTuple<BuiltInCategory, string>>();
			this._internalCats = new List<ValueTuple<BuiltInCategory, string>>();
			this.components = null;
			
			this._fullList = fullList;
			foreach (ValueTuple<BuiltInCategory, CategoryType, string> current in this._fullList)
			{
				ValueTuple<BuiltInCategory, string> item = new ValueTuple<BuiltInCategory, string>(current.Item1, current.Item3);
				switch (current.Item2)
				{
				case CategoryType.Model:
					this._modelCats.Add(item);
					break;
				case CategoryType.Annotation:
					this._annotationCats.Add(item);
					break;
				case CategoryType.Internal:
					this._internalCats.Add(item);
					break;
				case CategoryType.AnalyticalModel:
					this._analyticalModelCats.Add(item);
					break;
				}
			}
			bool flag = selected == null;
			if (flag)
			{
				selected = new List<ValueTuple<BuiltInCategory, string>>();
			}
			this.InitializeComponent();
			this.Text = formTitle;
			this.FillSelectTable(selected);
			this.FillTable(this.dgvModel, this._modelCats);
			this.FillTable(this.dgvAnnotation, this._annotationCats);
			this.FillTable(this.dgvAnalyticalModel, this._analyticalModelCats);
			this.FillTable(this.dgvInternal, this._internalCats);
			this._state = new FormExt_State(this, parentXpath, 846, 549);
			this._state.Add(this.tabCats);
			this._state.ConfigRead();
		}
		private void FillTable(DataGridView dgv, List<ValueTuple<BuiltInCategory, string>> dataList)
		{
			List<BuiltInCategory> list = (
				from DataGridViewRow r in this.dgvSelected.Rows
				select r.Cells[this.colItem.Index].Value).OfType<BuiltInCategory>().ToList<BuiltInCategory>();
			foreach (ValueTuple<BuiltInCategory, string> current in dataList)
			{
				bool flag = list.Contains(current.Item1);
				if (!flag)
				{
					int index = dgv.Rows.Add();
					DataGridViewRow dataGridViewRow = dgv.Rows[index];
					dataGridViewRow.Cells[this.colItem.Index].Value = current.Item1;
					dataGridViewRow.Cells[this.colComment.Index].Value = current.Item2;
				}
			}
			dgv.Sort(dgv.Columns[1], ListSortDirection.Ascending);
		}
		private void FillSelectTable(List<ValueTuple<BuiltInCategory, string>> dataList)
		{
			foreach (ValueTuple<BuiltInCategory, string> current in dataList)
			{
				int index = this.dgvSelected.Rows.Add();
				DataGridViewRow dataGridViewRow = this.dgvSelected.Rows[index];
				dataGridViewRow.Cells[this.colItem.Index].Value = current.Item1;
				dataGridViewRow.Cells[this.colComment.Index].Value = current.Item2;
			}
			this.dgvSelected.Sort(this.dgvSelected.Columns[1], ListSortDirection.Ascending);
		}
		private void MoveOneItem(DataGridViewRow row, DataGridView destDgv)
		{
			object obj = (row != null) ? row.Cells[this.colItem.Index].Value : null;
			BuiltInCategory builtInCategory = BuiltInCategory.INVALID;
			bool arg_36_0 = false;
			if (obj is BuiltInCategory)
			{
				builtInCategory = (BuiltInCategory)obj;
				arg_36_0 = true;
			}
			else
			{
				arg_36_0 = false;
			}
			bool flag = arg_36_0;
			if (flag)
			{
				string text = (string)row.Cells[this.colComment.Index].Value;
				foreach (DataGridViewRow dataGridViewRow in (IEnumerable)destDgv.Rows)
				{
					string a = (string)dataGridViewRow.Cells[this.colComment.Index].Value;
					bool flag2 = a == text;
					if (flag2)
					{
						return;
					}
				}
				int index = destDgv.Rows.Add();
				DataGridViewRow dataGridViewRow2 = destDgv.Rows[index];
				dataGridViewRow2.Cells[this.colItem.Index].Value = builtInCategory;
				dataGridViewRow2.Cells[this.colComment.Index].Value = text;
			}
		}
		private void Deselect()
		{
			DataGridViewSelectedRowCollection selectedRows = this.dgvSelected.SelectedRows;
			bool flag = selectedRows == null;
			if (!flag)
			{
				IEnumerator enumerator = selectedRows.GetEnumerator();
				try
				{
					while (enumerator.MoveNext())
					{
						DataGridViewRow dataGridViewRow = (DataGridViewRow)enumerator.Current;
						object obj = (dataGridViewRow != null) ? dataGridViewRow.Cells[this.colItem.Index].Value : null;
						bool arg_79_0 = false;
						BuiltInCategory bic = BuiltInCategory.INVALID;
						if (obj is BuiltInCategory)
						{
							bic = (BuiltInCategory)obj;
							arg_79_0 = true;
						}
						else
						{
							arg_79_0 = false;
						}
						bool flag2 = arg_79_0;
						if (flag2)
						{
							switch (this._fullList.First((ValueTuple<BuiltInCategory, CategoryType, string> c) => c.Item1.Equals(bic)).Item2)
							{
							case CategoryType.Model:
								this.MoveOneItem(dataGridViewRow, this.dgvModel);
								break;
							case CategoryType.Annotation:
								this.MoveOneItem(dataGridViewRow, this.dgvAnnotation);
								break;
							case CategoryType.Internal:
								this.MoveOneItem(dataGridViewRow, this.dgvInternal);
								break;
							case CategoryType.AnalyticalModel:
								this.MoveOneItem(dataGridViewRow, this.dgvAnalyticalModel);
								break;
							}
						}
					}
				}
				finally
				{
					IDisposable disposable = enumerator as IDisposable;
					if (disposable != null)
					{
						disposable.Dispose();
					}
				}
				foreach (DataGridViewRow dataGridViewRow2 in selectedRows)
				{
					this.dgvSelected.Rows.Remove(dataGridViewRow2);
				}
				this.dgvSelected.Sort(this.dgvSelected.Columns[1], ListSortDirection.Ascending);
				this.dgvModel.Sort(this.dgvModel.Columns[1], ListSortDirection.Ascending);
				this.dgvAnnotation.Sort(this.dgvAnnotation.Columns[1], ListSortDirection.Ascending);
				this.dgvAnalyticalModel.Sort(this.dgvAnalyticalModel.Columns[1], ListSortDirection.Ascending);
				this.dgvInternal.Sort(this.dgvInternal.Columns[1], ListSortDirection.Ascending);
			}
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			this.Selected.Clear();
			this.Comments.Clear();
			bool flag = this.dgvSelected.Rows.Count == 0;
			if (flag)
			{
				MessageBox.Show("Ничего не выбрано.");
			}
			else
			{
				foreach (DataGridViewRow dataGridViewRow in (IEnumerable)this.dgvSelected.Rows)
				{
					this.Selected.Add((BuiltInCategory)dataGridViewRow.Cells[this.colItem.Index].Value);
					this.Comments.Add(dataGridViewRow.Cells[this.colComment.Index].Value.ToString());
				}
				base.DialogResult = DialogResult.OK;
				base.Close();
			}
		}
		private void txtFilter_TextChanged(object sender, EventArgs e)
		{
			string sFilter = (this.txtFilter.Text?.ToLowerInvariant()) ?? string.Empty;
			this.dgvModel.Rows.Clear();
			this.dgvAnnotation.Rows.Clear();
			this.dgvAnalyticalModel.Rows.Clear();
			this.dgvInternal.Rows.Clear();
			this.FillTable(this.dgvModel, this._modelCats.Where(x => x.Item2.IndexOf(sFilter, StringComparison.OrdinalIgnoreCase) >= 0).ToList());
			this.FillTable(this.dgvAnnotation, this._annotationCats.Where(x => x.Item2.IndexOf(sFilter, StringComparison.OrdinalIgnoreCase) >= 0).ToList());
			this.FillTable(this.dgvAnalyticalModel, this._analyticalModelCats.Where(x => x.Item2.IndexOf(sFilter, StringComparison.OrdinalIgnoreCase) >= 0).ToList());
			this.FillTable(this.dgvInternal, this._internalCats.Where(x => x.Item2.IndexOf(sFilter, StringComparison.OrdinalIgnoreCase) >= 0).ToList());
		}
