		private void btnSelectItem_Click(object sender, EventArgs e)
		{
			bool flag = this.tabCats.SelectedTab == this.tpModel;
			DataGridView dataGridView;
			if (flag)
			{
				dataGridView = this.dgvModel;
			}
			else
			{
				bool flag2 = this.tabCats.SelectedTab == this.tpAnnotation;
				if (flag2)
				{
					dataGridView = this.dgvAnnotation;
				}
				else
				{
					bool flag3 = this.tabCats.SelectedTab == this.tpAnalyticalModel;
					if (flag3)
					{
						dataGridView = this.dgvAnalyticalModel;
					}
					else
					{
						bool flag4 = this.tabCats.SelectedTab == this.tpInternal;
						if (!flag4)
						{
							return;
						}
						dataGridView = this.dgvInternal;
					}
				}
			}
			DataGridViewSelectedRowCollection selectedRows = dataGridView.SelectedRows;
			bool flag5 = selectedRows == null;
			if (!flag5)
			{
				foreach (DataGridViewRow row in selectedRows)
				{
					this.MoveOneItem(row, this.dgvSelected);
				}
				foreach (DataGridViewRow dataGridViewRow in selectedRows)
				{
					dataGridView.Rows.Remove(dataGridViewRow);
				}
				this.dgvSelected.Sort(this.dgvSelected.Columns[1], ListSortDirection.Ascending);
			}
		}
