	public class FrmSelectItems : System.Windows.Forms.Form
	{
		private readonly FormExt_State _state;
		private readonly CheckboxColumn _colCheckbox;
		private readonly bool _sortByComment = false;
		private readonly bool _isLoaded = false;
		private IContainer components = null;
		public DataGridView dgv;
		public Button btnOk;
		public Button btnCancel;
		private TableLayoutPanel tlpMain;
		private TableLayoutPanel tlpBottom;
		private System.Windows.Forms.Panel pnlFilter;
		private Label label3;
		private System.Windows.Forms.TextBox txtFilter;
		private Label lblTotal;
		private DataGridViewTextBoxColumn colItem;
		private DataGridViewTextBoxColumn colComment;
		public List<ItemCommentEnable> Items
		{
			get;
			private set;
		}
		public FrmSelectItems(List<ItemCommentEnable> fullList, string parentXpath, string formTitle, bool sortByComment = true)
		{
			this._isLoaded = false;
			this._sortByComment = sortByComment;
			this.Items = new List<ItemCommentEnable>();
			this.Items.AddRange(fullList);
			this.InitializeComponent();
			this._state = new FormExt_State(this, parentXpath, 345, 380);
			this._state.ConfigRead();
			this.Text = formTitle;
			this._colCheckbox = new CheckboxColumn(this.dgv, this, 0, this.lblTotal, false, 6);
			this.FillTable(this.Items);
			this._isLoaded = true;
		}
		private void FillTable(List<ItemCommentEnable> items)
		{
			foreach (ItemCommentEnable current in items)
			{
				int index = this.dgv.Rows.Add();
				DataGridViewRow dataGridViewRow = this.dgv.Rows[index];
				dataGridViewRow.Cells[this.colItem.Index].Value = current.Item;
				dataGridViewRow.Cells[this.colComment.Index].Value = current.Comment;
				dataGridViewRow.Cells[this._colCheckbox.Column.Index].Value = current.Enable;
			}
			bool sortByComment = this._sortByComment;
			if (sortByComment)
			{
				this.dgv.Sort(this.dgv.Columns[this.colComment.Index], ListSortDirection.Ascending);
			}
			this.lblTotal.Text = string.Format("Всего: {0}", this.dgv.Rows.Count);
		}
		private void txtFilter_TextChanged(object sender, EventArgs e)
		{
			List<ItemCommentEnable> list = new List<ItemCommentEnable>();
			list.AddRange(this.Items);
			this.dgv.Rows.Clear();
			bool flag = !string.IsNullOrEmpty(this.txtFilter.Text);
			if (flag)
			{
				string sFilter = this.txtFilter.Text.ToLower();
				list = list.FindAll((ItemCommentEnable x) => x.Comment.Contains(sFilter, StringComparison.OrdinalIgnoreCase));
			}
			this.FillTable(list);
		}
		private void dgv_CellValueChanged(object sender, DataGridViewCellEventArgs e)
		{
			bool flag = !this._isLoaded;
			if (!flag)
			{
				bool flag2 = this._colCheckbox != null && e.ColumnIndex == this._colCheckbox.Column.Index && e.RowIndex != -1;
				if (flag2)
				{
					DataGridView dataGridView = (DataGridView)sender;
					DataGridViewRow dataGridViewRow = dataGridView.Rows[e.RowIndex];
					DataGridViewCheckBoxCell dataGridViewCheckBoxCell = dataGridViewRow.Cells[this._colCheckbox.Column.Index] as DataGridViewCheckBoxCell;
					DataGridViewTextBoxCell chkItem = dataGridViewRow.Cells[this.colItem.Index] as DataGridViewTextBoxCell;
					bool flag3 = chkItem.Value != null;
					if (flag3)
					{
						ItemCommentEnable itemCommentEnable = (
							from ite in this.Items
							where ite.Item == chkItem.Value
							select ite).FirstOrDefault<ItemCommentEnable>();
						bool flag4 = itemCommentEnable != null;
						if (flag4)
						{
							itemCommentEnable.Enable = (bool)dataGridViewCheckBoxCell.Value;
						}
					}
				}
			}
		}
		private void dgv_MouseDoubleClick(object sender, MouseEventArgs e)
		{
			DataGridView dataGridView = (DataGridView)sender;
			DataGridViewRow currentRow = dataGridView.CurrentRow;
			bool flag = this._colCheckbox != null && currentRow != null;
			if (flag)
			{
				DataGridViewCheckBoxCell dataGridViewCheckBoxCell = currentRow.Cells[this._colCheckbox.Column.Index] as DataGridViewCheckBoxCell;
				dataGridViewCheckBoxCell.Value = !(bool)dataGridViewCheckBoxCell.Value;
			}
		}
		protected override void Dispose(bool disposing)
		{
			bool flag = disposing && this.components != null;
			if (flag)
			{
				this.components.Dispose();
			}
			base.Dispose(disposing);
		}
