	public class FrmSelectViews : System.Windows.Forms.Form
	{
		private readonly TSTVservice _treeService;
		private readonly FormExt_State _state;
		private IContainer components = null;
		private TableLayoutPanel tlp;
		private Button btnCancel;
		private Button btnOk;
		public List<Autodesk.Revit.DB.View> Views
		{
			get;
			private set;
		}
		public FrmSelectViews(Autodesk.Revit.DB.Document doc, string parentXpath, bool addViews, bool addSheets, bool addSchedules, List<ViewType> viewTypes = null)
		{
			this.InitializeComponent();
			this.Views = new List<Autodesk.Revit.DB.View>();
			this._treeService = new TSTVservice("tvw", this.tlp, null, null, 0, 0, 2, 1);
			ProjectBrowser projectBrowser = new ProjectBrowser(doc, this._treeService.Tree)
			{
				AddViews = addViews,
				AddSheets = addSheets,
				AddSchedules = addSchedules
			};
			bool flag = viewTypes != null;
			if (flag)
			{
				projectBrowser.ViewTypes = viewTypes;
			}
			projectBrowser.BuildTree();
			this._state = new FormExt_State(this, parentXpath, 300, 300);
			this._state.Add(this._treeService.Tree);
			this._state.ConfigRead();
		}
		private void TraverseTree(TreeNode node)
		{
			Autodesk.Revit.DB.View view = node.Tag as Autodesk.Revit.DB.View;
			bool flag = view != null && node.Checked;
			if (flag)
			{
				this.Views.Add(view);
			}
			foreach (TreeNode node2 in node.Nodes)
			{
				this.TraverseTree(node2);
			}
