	public class FileInterface
	{
		private readonly System.Windows.Forms.Form _frm;
		private readonly string _title;
		private readonly FileService _fileService;
		private readonly ReloadHandler _reloadHandler;
		private readonly ToolStripMenuItem _tsmiNew;
		private readonly ToolStripMenuItem _tsmiOpen;
		private readonly ToolStripMenuItem _tsmiSave;
		private readonly ToolStripMenuItem _tsmiSaveAs;
		private readonly ToolStripMenuItem _tsmiExit;
		public FileInterface(System.Windows.Forms.Form frm, string title, FileService fileService, ReloadHandler reloadHandler, ToolStripMenuItem tsmiNew, ToolStripMenuItem tsmiOpen, ToolStripMenuItem tsmiSave, ToolStripMenuItem tsmiSaveAs, ToolStripMenuItem tsmiExit)
		{
			this._frm = frm;
			this._title = title;
			this._fileService = fileService;
			this._reloadHandler = reloadHandler;
			this._tsmiNew = tsmiNew;
			this._tsmiOpen = tsmiOpen;
			this._tsmiSave = tsmiSave;
			this._tsmiSaveAs = tsmiSaveAs;
			this._tsmiExit = tsmiExit;
			this._tsmiNew.Click += new EventHandler(this.tsmiNew_Click);
			this._tsmiOpen.Click += new EventHandler(this.tsmiOpen_Click);
			this._tsmiSave.Click += new EventHandler(this.tsmiSave_Click);
			this._tsmiSaveAs.Click += new EventHandler(this.tsmiSaveAs_Click);
			this._tsmiExit.Click += new EventHandler(this.tsmiExit_Click);
			this._frm.FormClosing += new FormClosingEventHandler(this.Frm_FormClosing);
			bool flag = !string.IsNullOrEmpty(this._fileService.GetPath());
			if (flag)
			{
				string text;
				this._fileService.Loader(out text);
				bool flag2 = text != "" && text != "не найден файл";
				if (flag2)
				{
					Log.Write(text);
					MessageBox.Show(text);
				}
				else
				{
					this._reloadHandler();
				}
			}
		}
		private void tsmiNew_Click(object sender, EventArgs e)
		{
			bool flag = !this._fileService.CheckOnExit();
			if (!flag)
			{
				this._fileService.Clear();
				this._reloadHandler();
				this._frm.Text = "<не сохранён> - " + this._title;
			}
		}
		private void tsmiOpen_Click(object sender, EventArgs e)
		{
			bool flag = !this._fileService.CheckOnExit();
			if (!flag)
			{
				string path = this._fileService.GetPath();
				System.Windows.Forms.OpenFileDialog openFileDialog = new System.Windows.Forms.OpenFileDialog
				{
					DefaultExt = "xml",
					Filter = "XML-документ (*.xml)|*.xml|All files (*.*)|*.*",
					Title = "Открытие файла правил заполнения параметров"
				};
				bool flag2 = path != "";
				if (flag2)
				{
					openFileDialog.InitialDirectory = Path.GetDirectoryName(path);
				}
				openFileDialog.RestoreDirectory = true;
				openFileDialog.AddExtension = true;
				bool flag3 = openFileDialog.ShowDialog() != DialogResult.OK;
				if (!flag3)
				{
					bool flag4 = openFileDialog.FileName == "";
					if (!flag4)
					{
						this._fileService.SetPath(openFileDialog.FileName);
						string text;
						this._fileService.Loader(out text);
						bool flag5 = text != "";
						if (flag5)
						{
							Log.Write(text);
							MessageBox.Show(text);
						}
						else
						{
							this._reloadHandler();
						}
					}
				}
			}
		}
		private void tsmiSave_Click(object sender, EventArgs e)
		{
			this._fileService.SaveToXml();
			this._frm.Text = this._fileService.GetPath() + " - " + this._title;
		}
		private void tsmiSaveAs_Click(object sender, EventArgs e)
		{
			this._fileService.SaveAs2Xml();
			this._frm.Text = this._fileService.GetPath() + " - " + this._title;
		}
		private void tsmiExit_Click(object sender, EventArgs e)
		{
			this._frm.Close();
		}
		private void Frm_FormClosing(object sender, FormClosingEventArgs e)
		{
			bool flag = !this._fileService.CheckOnExit();
			if (flag)
			{
				e.Cancel = true;
			}
		}
	}
	public delegate void LoaderFromXml(out string errReport);
	public delegate object[] SaveArgsGetter();
	public class FileService
	{
		private string _fullFilePath;
		private XmlDataSetBase _dataset;
		private readonly string _saveFileDialogTitle;
		private readonly string _warningMsg1;
		private readonly string _warningMsg2;
		public LoaderFromXml Loader
		{
			get;
			private set;
		}
		public SaveArgsGetter SaveArgsGetter
		{
			get;
			private set;
		}
		public FileService(XmlDataSetBase dataset, LoaderFromXml loader, SaveArgsGetter saveArgsGetter, string saveFileDialogTitle, string warningMsg1, string warningMsg2)
		{
			this._saveFileDialogTitle = saveFileDialogTitle;
			this.Loader = loader;
			this.SaveArgsGetter = saveArgsGetter;
			this._dataset = dataset;
			this._warningMsg1 = warningMsg1;
			this._warningMsg2 = warningMsg2;
		}
		public string GetPath()
		{
			return this._fullFilePath;
		}
		public void SetPath(string path)
		{
			this._fullFilePath = path;
		}
		public void LoadDataset(XmlDataSetBase dataset)
		{
			this._dataset = dataset;
		}
		public bool SaveToXml()
		{
			object[] convertArgs = this.SaveArgsGetter();
			string text = XmlFileManager.Save(this._dataset, this._fullFilePath, this._saveFileDialogTitle, convertArgs);
			bool flag = text == "";
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				bool flag2 = this._fullFilePath != text;
				if (flag2)
				{
					this._fullFilePath = text;
				}
				this._dataset.IsChanged = false;
				result = true;
			}
			return result;
		}
		public void SaveAs2Xml()
		{
			object[] convertArgs = this.SaveArgsGetter();
			string text = XmlFileManager.Save(this._dataset, "", this._saveFileDialogTitle, convertArgs);
			bool flag = text == "";
			if (!flag)
			{
				bool flag2 = this._fullFilePath != text;
				if (flag2)
				{
					this._fullFilePath = text;
				}
				this._dataset.IsChanged = false;
			}
		}
		public bool CheckOnExit()
		{
			bool flag = this._dataset == null;
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				bool isChanged = this._dataset.IsChanged;
				if (isChanged)
				{
					bool flag2 = string.IsNullOrEmpty(this._fullFilePath);
					DialogResult dialogResult;
					if (flag2)
					{
						dialogResult = MessageBox.Show(this._warningMsg1 + ". Сохранить в файл?", "Сохранение", MessageBoxButtons.YesNoCancel);
					}
					else
					{
						dialogResult = MessageBox.Show(this._warningMsg2 + " \"" + this._fullFilePath + "\"?", "Сохранение", MessageBoxButtons.YesNoCancel);
					}
					bool flag3 = dialogResult == DialogResult.Cancel;
					if (flag3)
					{
						result = false;
						return result;
					}
					bool flag4 = dialogResult == DialogResult.Yes;
					if (flag4)
					{
						result = this.SaveToXml();
						return result;
					}
				}
				result = true;
			}
			return result;
		}
		public void Clear()
		{
			this._dataset.Clear();
			this._dataset.IsChanged = false;
			this._fullFilePath = null;
		}
	}
