		private System.Drawing.Point GetPosition(string x, string y)
		{
			int X = Convert.ToInt32(x);
			int Y = Convert.ToInt32(y);
			bool flag = Screen.AllScreens.Any((Screen s) => X >= s.Bounds.Left && X < s.Bounds.Right - 20 && Y >= s.Bounds.Top && Y < s.Bounds.Bottom - 20);
			System.Drawing.Point result;
			if (flag)
			{
				result = new System.Drawing.Point(X, Y);
			}
			else
			{
				bool flag2 = Screen.PrimaryScreen != null;
				if (flag2)
				{
					X = Screen.PrimaryScreen.Bounds.Left + 50;
					Y = Screen.PrimaryScreen.Bounds.Top + 50;
				}
				result = new System.Drawing.Point(X, Y);
			}
			return result;
		}
		private XElement DgvColumnSizesToXml(DataGridView dgv)
		{
			bool flag = dgv == null;
			XElement result;
			if (flag)
			{
				result = null;
			}
			else
			{
				List<string> list = new List<string>();
				foreach (DataGridViewColumn dataGridViewColumn in dgv.Columns)
				{
					list.Add(Convert.ToString(dataGridViewColumn.Width));
				}
				XElement xElement = new XElement("columnSizes", string.Join(";", list));
				result = xElement;
			}
			return result;
		}
		private void DgvColumnSizesFromXml(DataGridView dgv, XElement xeParent, string defSizes)
		{
			bool flag = dgv == null;
			if (!flag)
			{
				bool flag2 = xeParent == null || !xeParent.HasElements;
				string text;
				if (flag2)
				{
					bool flag3 = string.IsNullOrEmpty(defSizes);
					if (flag3)
					{
						return;
					}
					text = defSizes;
				}
				else
				{
					XElement xElement = xeParent.Element("columnSizes");
					bool flag4 = xElement == null;
					if (flag4)
					{
						text = defSizes;
					}
					else
					{
						text = xElement.Value;
					}
				}
				string[] array = text.Split(new char[]
				{
					';'
				});
				bool flag5 = array.Length < dgv.Columns.Count;
				if (flag5)
				{
					array = defSizes.Split(new char[]
					{
						';'
					});
					bool flag6 = array.Length < dgv.Columns.Count;
					if (flag6)
					{
						Log.Write(string.Concat(new string[]
						{
							"Попытка восстановить размеры столбцов в ",
							dgv.Name,
							" данными '",
							defSizes,
							"' не удалась. ",
							string.Format("Всего в {0} {1} столбцов.", dgv.Name, dgv.Columns.Count)
						}));
						return;
					}
				}
				for (int i = 0; i < dgv.Columns.Count; i++)
				{
					bool flag7 = i < array.Length;
					if (!flag7)
					{
						break;
					}
					bool flag8 = dgv.Columns[i].AutoSizeMode == DataGridViewAutoSizeColumnMode.Fill;
					if (!flag8)
					{
						int width = 0;
						bool flag9 = int.TryParse(array[i], out width);
						if (flag9)
						{
							dgv.Columns[i].Width = width;
						}
					}
				}
			}
		}
		private XElement TreeViewNodesStateToXml(TreeView tvw)
		{
			XElement xElement = new XElement("expandedNodes");
			foreach (TreeNode current in tvw.GetAllNodes())
			{
				bool isExpanded = current.IsExpanded;
				if (isExpanded)
				{
					XElement xElement2 = new XElement("node", current.FullPath);
					xElement2.Add(new XAttribute("level", current.Level));
					xElement.Add(xElement2);
				}
			}
			return xElement;
		}
		private void TreeViewNodesStateFromXml(TreeView tvw, XElement xeExpNodes)
		{
			List<TreeNode> allNodes = tvw.GetAllNodes();
			bool flag = xeExpNodes != null;
			if (flag)
			{
				foreach (XElement current in xeExpNodes.Elements("node"))
				{
					bool flag2 = current.Value == null;
					if (!flag2)
					{
						XAttribute expr_63 = current.Attribute("level");
						int level = 0;
						bool flag3 = int.TryParse((expr_63 != null) ? expr_63.Value : null, out level);
						if (flag3)
						{
							IEnumerable<TreeNode> enumerable = 
								from n in tvw.GetAllNodes()
								where n.Level == level
								select n;
							foreach (TreeNode current2 in enumerable)
							{
								bool flag4 = current2.FullPath == current.Value;
								if (flag4)
								{
									current2.Expand();
									break;
								}
							}
						}
					}
				}
			}
			else
			{
				List<TreeNode> list = new List<TreeNode>();
				foreach (TreeNode current3 in allNodes)
				{
					bool flag5 = current3.Parent == null;
					if (flag5)
					{
						list.Add(current3);
					}
				}
				foreach (TreeNode current4 in list)
				{
					current4.Expand();
				}
			}
		}
		private XElement Convert2Xml(System.Windows.Forms.Form f)
