				{
					XElement xElement2 = new XElement("positionX", f.Location.X);
					XElement xElement3 = new XElement("positionY", f.Location.Y);
					xElement.Add(new object[]
					{
						xElement2,
						xElement3
					});
				}
				bool flag3 = f.FormBorderStyle == FormBorderStyle.Sizable;
				if (flag3)
