			if (flag)
			{
				selected = new List<ValueTuple<object, string>>();
			}
			this.InitializeComponent();
			this.Text = formTitle;
			this.lblLeft.Text = left;
			this.lblRight.Text = right;
			this.FillSelectTable(selected);
			this.FillTable(this.dgvSource, this._fullList);
			this._state = new FormExt_State(this, parentXpath, 684, 542);
			this._state.ConfigRead();
		}
		private void FillSelectTable(List<ValueTuple<object, string>> dataList)
		{
			foreach (ValueTuple<object, string> current in dataList)
			{
				int index = this.dgvSelected.Rows.Add();
				DataGridViewRow dataGridViewRow = this.dgvSelected.Rows[index];
				dataGridViewRow.Cells[this.colItem.Index].Value = current.Item1;
				dataGridViewRow.Cells[this.colComment.Index].Value = current.Item2;
			}
			this.dgvSelected.Sort(this.dgvSelected.Columns[1], ListSortDirection.Ascending);
		}
		private void FillTable(DataGridView dgv, List<ValueTuple<object, string>> dataList)
		{
			List<object> list = (
				from DataGridViewRow r in this.dgvSelected.Rows
				select r.Cells[this.colItem.Index].Value).ToList<object>();
			foreach (ValueTuple<object, string> current in dataList)
			{
				bool flag = list.Contains(current.Item1);
				if (!flag)
				{
					int index = dgv.Rows.Add();
					DataGridViewRow dataGridViewRow = dgv.Rows[index];
					dataGridViewRow.Cells[this.colItem.Index].Value = current.Item1;
					dataGridViewRow.Cells[this.colComment.Index].Value = current.Item2;
				}
			}
			dgv.Sort(dgv.Columns[1], ListSortDirection.Ascending);
		}
		private void MoveOneItem(DataGridViewRow row, DataGridView destDgv)
		{
			bool flag = row == null;
			if (!flag)
			{
				object value = row.Cells[this.colItem.Index].Value;
				string text = (string)row.Cells[this.colComment.Index].Value;
				foreach (DataGridViewRow dataGridViewRow in (IEnumerable)destDgv.Rows)
				{
					string a = (string)dataGridViewRow.Cells[this.colComment.Index].Value;
					bool flag2 = a == text;
					if (flag2)
					{
						return;
					}
				}
				int index = destDgv.Rows.Add();
				DataGridViewRow dataGridViewRow2 = destDgv.Rows[index];
				dataGridViewRow2.Cells[this.colItem.Index].Value = value;
				dataGridViewRow2.Cells[this.colComment.Index].Value = text;
			}
		}
		private void Deselect()
		{
			DataGridViewSelectedRowCollection selectedRows = this.dgvSelected.SelectedRows;
			bool flag = selectedRows == null;
			if (!flag)
			{
				foreach (DataGridViewRow row in selectedRows)
				{
					this.MoveOneItem(row, this.dgvSource);
				}
				foreach (DataGridViewRow dataGridViewRow in selectedRows)
				{
					this.dgvSelected.Rows.Remove(dataGridViewRow);
				}
				this.dgvSelected.Sort(this.dgvSelected.Columns[1], ListSortDirection.Ascending);
				this.dgvSource.Sort(this.dgvSource.Columns[1], ListSortDirection.Ascending);
			}
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			this.SubList.Clear();
			this.Comments.Clear();
			bool flag = this.dgvSelected.Rows.Count == 0;
			if (flag)
			{
				MessageBox.Show("Ничего не выбрано.");
			}
			else
			{
				foreach (DataGridViewRow dataGridViewRow in (IEnumerable)this.dgvSelected.Rows)
				{
					this.SubList.Add(dataGridViewRow.Cells[this.colItem.Index].Value);
					this.Comments.Add(dataGridViewRow.Cells[this.colComment.Index].Value.ToString());
				}
				base.DialogResult = DialogResult.OK;
				base.Close();
			}
		}
		private void txtFilter_TextChanged(object sender, EventArgs e)
		{
			List<ValueTuple<object, string>> list = new List<ValueTuple<object, string>>();
			list.AddRange(this._fullList);
			this.dgvSource.Rows.Clear();
			bool flag = !string.IsNullOrEmpty(this.txtFilter.Text);
			if (flag)
			{
				string sFilter = this.txtFilter.Text.ToLower();
				list = list.FindAll((ValueTuple<object, string> x) => x.Item2.Contains(sFilter, StringComparison.OrdinalIgnoreCase));
			}
			this.FillTable(this.dgvSource, list);
		}
		private void dgvSource_DoubleClick(object sender, EventArgs e)
		{
			DataGridViewRow currentRow = this.dgvSource.CurrentRow;
			this.MoveOneItem(currentRow, this.dgvSelected);
			this.dgvSource.Rows.Remove(currentRow);
		}
		private void btnSelectItem_Click(object sender, EventArgs e)
		{
			DataGridViewSelectedRowCollection selectedRows = this.dgvSource.SelectedRows;
			bool flag = selectedRows == null;
			if (!flag)
			{
				foreach (DataGridViewRow row in selectedRows)
				{
					this.MoveOneItem(row, this.dgvSelected);
				}
				foreach (DataGridViewRow dataGridViewRow in selectedRows)
				{
					this.dgvSource.Rows.Remove(dataGridViewRow);
				}
				this.dgvSelected.Sort(this.dgvSelected.Columns[1], ListSortDirection.Ascending);
			}
		}
		private void btnDeselectItem_Click(object sender, EventArgs e)
		{
			this.Deselect();
		}
		private void dgvSelected_KeyDown(object sender, KeyEventArgs e)
		{
			bool flag = e.KeyData == Keys.Delete;
			if (flag)
			{
				this.Deselect();
			}
		}
