	public class FrmSelectItem : System.Windows.Forms.Form
	{
		private readonly FormExt_State _state;
		private readonly List<ItemComment> _fullList;
		public const string IS_PROJECT_PARAM = "параметр проекта";
		private IContainer components = null;
		public DataGridView dgv;
		public Button btnOk;
		public Button btnCancel;
		private TableLayoutPanel tlpMain;
		private TableLayoutPanel tlpBottom;
		private System.Windows.Forms.Panel pnlFilter;
		private Label label3;
		private System.Windows.Forms.TextBox txtFilter;
		private Label lblTotal;
		private DataGridViewTextBoxColumn colItem;
		private DataGridViewTextBoxColumn colComment;
		public object Item
		{
			get;
			private set;
		}
		public FrmSelectItem(List<ItemComment> fullList, string parentXpath, string formTitle, object selected = null)
		{
			this._fullList = fullList;
			bool flag = this._fullList == null;
			if (flag)
			{
				this._fullList = new List<ItemComment>();
			}
			bool flag2 = selected == null;
			if (flag2)
			{
				selected = new List<ItemComment>();
			}
			this.InitializeComponent();
			this._state = new FormExt_State(this, parentXpath, 345, 380);
			this._state.ConfigRead();
			this.Text = formTitle;
			int num = this.FillTable(fullList, selected);
			bool flag3 = num != -1;
			if (flag3)
			{
				this.dgv.CurrentCell = this.dgv.Rows[num].Cells[this.colComment.Index];
			}
		}
		private int FillTable(List<ItemComment> dataList, object selected)
		{
			foreach (ItemComment current in dataList)
			{
				int index = this.dgv.Rows.Add();
				DataGridViewRow dataGridViewRow = this.dgv.Rows[index];
				dataGridViewRow.Cells[this.colItem.Index].Value = current.Item;
				dataGridViewRow.Cells[this.colComment.Index].Value = current.Comment;
			}
			this.dgv.Sort(this.dgv.Columns[this.colComment.Index], ListSortDirection.Ascending);
			this.lblTotal.Text = string.Format("Всего: {0}", this.dgv.Rows.Count);
			int result = -1;
			bool flag = selected != null;
			if (flag)
			{
				foreach (DataGridViewRow dataGridViewRow2 in (IEnumerable)this.dgv.Rows)
				{
					bool flag2 = selected.Equals(dataGridViewRow2.Cells[this.colItem.Index].Value);
					if (flag2)
					{
						result = dataGridViewRow2.Index;
						break;
					}
				}
			}
			return result;
		}
		private void btnOk_Click(object sender, EventArgs e)
		{
			bool flag = this.Check();
			if (flag)
			{
				this.SaveAndExit();
			}
		}
		private void dgv_DoubleClick(object sender, EventArgs e)
		{
			bool flag = this.Check();
			if (flag)
			{
				this.SaveAndExit();
			}
		}
		private bool Check()
		{
			bool flag = this.dgv.CurrentCell == null;
			bool result = false;
			if (flag)
			{
				MessageBox.Show("Ничего не выбрано.");
				result = false;
			}
			else
			{
				result = true;
			}
			return result;
		}
		private void SaveAndExit()
		{
			DataGridViewRow currentRow = this.dgv.CurrentRow;
			bool flag = currentRow == null;
			if (!flag)
			{
				this.Item = currentRow.Cells[this.colItem.Index].Value;
				base.DialogResult = DialogResult.OK;
				base.Close();
			}
		}
		private void txtFilter_TextChanged(object sender, EventArgs e)
		{
			DataGridViewRow currentRow = this.dgv.CurrentRow;
			bool flag = currentRow != null;
			object selected;
			if (flag)
			{
				selected = currentRow.Cells[this.colItem.Index].Value;
			}
			else
			{
				selected = null;
			}
			List<ItemComment> list = new List<ItemComment>();
			list.AddRange(this._fullList);
			this.dgv.Rows.Clear();
			bool flag2 = !string.IsNullOrEmpty(this.txtFilter.Text);
			if (flag2)
			{
				string sFilter = this.txtFilter.Text.ToLower();
				list = list.FindAll((ItemComment x) => x.Comment.Contains(sFilter, StringComparison.OrdinalIgnoreCase));
			}
			int num = this.FillTable(list, selected);
			bool flag3 = num != -1 && this.dgv.Rows.Count > 0;
			if (flag3)
			{
				this.dgv.CurrentCell = this.dgv.Rows[num].Cells[this.colComment.Index];
			}
		}
		protected override void Dispose(bool disposing)
		{
			bool flag = disposing && this.components != null;
			if (flag)
			{
				this.components.Dispose();
			}
			base.Dispose(disposing);
		}
