		private int FillTable(List<ParamId> parameters, ParamId selParam)
		{
			int result = -1;
			System.Drawing.Color lightGreen = System.Drawing.Color.LightGreen;
			System.Drawing.Color navajoWhite = System.Drawing.Color.NavajoWhite;
			foreach (ParamId current in parameters)
			{
				bool flag = current == null || current.ErrReport != "";
				if (!flag)
				{
					int num = this.dgv.Rows.Add();
					DataGridViewRow dataGridViewRow = this.dgv.Rows[num];
					dataGridViewRow.Cells[this.colFullParamData.Index].Value = current;
					dataGridViewRow.Cells[this.colName.Index].Value = current.Name;
					dataGridViewRow.Cells[this.colComment.Index].Value = current.Comment;
					bool flag2 = selParam != null;
					if (flag2)
					{
						bool flag3 = selParam.EqualsTo(current);
						if (flag3)
						{
							result = num;
						}
					}
					bool flag4 = current.BIP != BuiltInParameter.INVALID;
					if (flag4)
					{
						dataGridViewRow.DefaultCellStyle.BackColor = lightGreen;
					}
					else
					{
						bool flag5 = current.Comment == "параметр проекта";
						if (flag5)
						{
							dataGridViewRow.DefaultCellStyle.BackColor = navajoWhite;
						}
					}
				}
			}
			this.lblTotal.Text = string.Format("Всего: {0}", parameters.Count);
			return result;
		}
