		{
			bool flag = this.dgv.CurrentCell == null;
			bool result = false;
			if (flag)
			{
				MessageBox.Show("Не выбрано ни одного параметра.");
				result = false;
			}
			else
			{
				result = true;
			}
			return result;
		}
		private void SaveAndExit()
		{
			DataGridViewRow currentRow = this.dgv.CurrentRow;
			bool flag = currentRow == null;
			if (!flag)
			{
				this.SelectedParam = (currentRow.Cells[this.colFullParamData.Index].Value as ParamId);
				base.DialogResult = DialogResult.OK;
				base.Close();
			}
		}
		private void txtFilter_TextChanged(object sender, EventArgs e)
		{
			ParamId selParam = null;
			DataGridViewRow currentRow = this.dgv.CurrentRow;
			bool flag = currentRow != null;
			if (flag)
			{
				selParam = (currentRow.Cells[this.colFullParamData.Index].Value as ParamId);
			}
			List<ParamId> list = new List<ParamId>();
			list.AddRange(this._parameters);
			this.dgv.Rows.Clear();
			bool flag2 = !string.IsNullOrEmpty(this.txtFilter.Text);
			if (flag2)
			{
				string sFilter = this.txtFilter.Text.ToLower();
				list = list.FindAll((ParamId x) => x.Name.ToLower().Contains(sFilter) || x.Comment.ToLower().Contains(sFilter));
			}
			int num = this.FillTable(list, selParam);
			bool flag3 = num != -1;
			if (flag3)
			{
				this.dgv.CurrentCell = this.dgv.Rows[num].Cells[1];
			}
		}
