	public static class CylindricalFaceExt
	{
		public static Solid GetSolid(this CylindricalFace f)
		{
			bool flag = f == null;
			Solid result;
			if (flag)
			{
				result = null;
			}
			else
			{
				XYZ xYZ = f.get_Radius(0);
				XYZ xYZ2 = f.get_Radius(1);
				Arc curve = Arc.Create(f.Origin, xYZ.GetLength(), 0.0, 3.1415926535897931, xYZ.Normalize(), xYZ2.Normalize());
				Arc curve2 = Arc.Create(f.Origin, xYZ.GetLength(), 3.1415926535897931, 6.2831853071795862, xYZ.Normalize(), xYZ2.Normalize());
				CurveLoop curveLoop = new CurveLoop();
				curveLoop.Append(curve);
				curveLoop.Append(curve2);
				List<CurveLoop> profileLoops = new List<CurveLoop>
				{
					curveLoop
				};
				Solid solid = GeometryCreationUtilities.CreateExtrusionGeometry(profileLoops, f.Axis.Normalize(), f.Axis.GetLength());
				result = solid;
			}
			return result;
		}
	}
	public static class CategorySetExt
	{
		public const string CATEGORY_SET = "categorySet";
		public static string ToString(this CategorySet cats, string format)
		{
			bool flag = cats == null || cats.Size == 0;
			string result;
			if (flag)
			{
				result = "";
			}
			else
			{
				StringBuilder stringBuilder = new StringBuilder();
				foreach (Category category in cats)
				{
					stringBuilder.Append(string.Format(format, category.Name));
				}
				result = stringBuilder.ToString();
			}
			return result;
		}
		public static XElement Convert2Xml(this CategorySet cats, string name = "categorySet")
		{
			XElement xElement = new XElement(name);
			bool flag = cats == null | cats.IsEmpty;
			XElement result;
			if (flag)
			{
				result = xElement;
			}
			else
			{
				foreach (Category category in cats)
				{
					XElement content = (category != null) ? category.Convert2Xml("category") : null;
					if (xElement != null)
					{
						xElement.Add(content);
					}
				}
				result = xElement;
			}
			return result;
		}
		public static CategorySet CreateFullCategorySet(Autodesk.Revit.DB.Document doc)
		{
			CategorySet categorySet = new CategorySet();
			foreach (Category category in doc.Settings.Categories)
			{
				bool allowsBoundParameters = category.AllowsBoundParameters;
				if (allowsBoundParameters)
				{
					categorySet.Insert(category);
					bool flag = !category.SubCategories.IsEmpty;
					if (flag)
					{
						foreach (object current in category.SubCategories)
						{
							Category category2 = current as Category;
							bool flag2 = category2 != null;
							if (flag2)
							{
								bool allowsBoundParameters2 = category2.AllowsBoundParameters;
								if (allowsBoundParameters2)
								{
									categorySet.Insert(category2);
								}
							}
						}
					}
				}
			}
			return categorySet;
		}
		public static CategorySet Create(Autodesk.Revit.DB.Document doc, XElement xe)
		{
			CategorySet categorySet = new CategorySet();
			foreach (XElement current in xe.Elements("category"))
			{
				Category category = CategoryExt.Find(doc, current);
				bool flag = category != null;
				if (flag)
				{
					categorySet.Insert(category);
				}
			}
			return categorySet;
		}
		public static CategorySet Create(Autodesk.Revit.DB.Document doc, string str, string splitString)
		{
			string[] catsArray = str.Split(new string[]
			{
				splitString
			}, StringSplitOptions.RemoveEmptyEntries);
			return CategorySetExt.Create(doc, catsArray);
		}
		public static CategorySet Create(Autodesk.Revit.DB.Document doc, string[] catsArray)
		{
			CategorySet categorySet = new CategorySet();
			Categories categories = doc.Settings.Categories;
			for (int i = 0; i < catsArray.Length; i++)
			{
				string key = catsArray[i];
				bool flag = categories.Contains(key);
				if (flag)
				{
					categorySet.Insert(categories.get_Item(key));
				}
			}
			return categorySet;
		}
