	public static class ColorExt
	{
		public static System.Drawing.Color HSVToRGB(double hue, double saturation, double value)
		{
			int num = Convert.ToInt32(Math.Floor(hue / 60.0)) % 6;
			double num2 = hue / 60.0 - Math.Floor(hue / 60.0);
			value *= 255.0;
			int num3 = Convert.ToInt32(value);
			int num4 = Convert.ToInt32(value * (1.0 - saturation));
			int num5 = Convert.ToInt32(value * (1.0 - num2 * saturation));
			int num6 = Convert.ToInt32(value * (1.0 - (1.0 - num2) * saturation));
			bool flag = num == 0;
			System.Drawing.Color result;
			if (flag)
			{
				result = System.Drawing.Color.FromArgb(255, num3, num6, num4);
			}
			else
			{
				bool flag2 = num == 1;
				if (flag2)
				{
					result = System.Drawing.Color.FromArgb(255, num5, num3, num4);
				}
				else
				{
					bool flag3 = num == 2;
					if (flag3)
					{
						result = System.Drawing.Color.FromArgb(255, num4, num3, num6);
					}
					else
					{
						bool flag4 = num == 3;
						if (flag4)
						{
							result = System.Drawing.Color.FromArgb(255, num4, num5, num3);
						}
						else
						{
							bool flag5 = num == 4;
							if (flag5)
							{
								result = System.Drawing.Color.FromArgb(255, num6, num4, num3);
							}
							else
							{
								result = System.Drawing.Color.FromArgb(255, num3, num4, num5);
							}
						}
					}
				}
			}
			return result;
		}
		public static void RGBToHSV(this System.Drawing.Color color, out double hue, out double saturation, out double value)
		{
			int num = (int)Math.Max(color.R, Math.Max(color.G, color.B));
			int num2 = (int)Math.Min(color.R, Math.Min(color.G, color.B));
			hue = (double)color.GetHue();
			saturation = ((num == 0) ? 0.0 : (1.0 - 1.0 * (double)num2 / (double)num));
			value = (double)num / 255.0;
		}
		public static System.Drawing.Color GetContrastingColor(this System.Drawing.Color color)
		{
			List<System.Drawing.Color> palette = ColorExt.GetPalette();
			float num = 0f;
			System.Drawing.Color result = color;
			int num2 = System.Drawing.Color.Black.ToArgb();
			int num3 = System.Drawing.Color.White.ToArgb();
			foreach (System.Drawing.Color current in palette)
			{
				bool flag = current.A == 0 || current.ToArgb() == num2 || current.ToArgb() == num3;
				if (!flag)
				{
					float num4 = ColorExt.BrightnessDifference(color, current);
					Debug.Print(string.Format("{0}\t\tRGB {1},{2},{3}\t\tdiff {4}", new object[]
					{
						current.Name,
						current.R,
						current.G,
						current.B,
						num4
					}));
					bool flag2 = num4 > num;
					if (flag2)
					{
						result = current;
						num = num4;
					}
				}
			}
			return result;
		}
		public static List<System.Drawing.Color> GetPalette()
		{
			List<System.Drawing.Color> list = new List<System.Drawing.Color>();
			IEnumerable<KnownColor> enumerable = Enum.GetValues(typeof(KnownColor)).Cast<KnownColor>();
			foreach (KnownColor current in enumerable)
			{
				list.Add(System.Drawing.Color.FromKnownColor(current));
			}
			return list;
		}
		public static System.Drawing.Color[] GetContrastingColors(System.Drawing.Color backgroundColor, System.Drawing.Color textColor, double ratio)
		{
			System.Drawing.Color[] array = new System.Drawing.Color[2];
			double num = backgroundColor.RelativeLuminance();
			double num2 = textColor.RelativeLuminance();
			bool flag = num2 > num;
			if (flag)
			{
				array[0] = textColor;
				array[1] = backgroundColor;
			}
			else
			{
				array[1] = textColor;
				array[0] = backgroundColor;
			}
			bool flag2 = ColorExt.ColorContrast(backgroundColor, textColor) >= ratio;
			System.Drawing.Color[] result;
			if (flag2)
			{
				result = array;
			}
			else
			{
				double hue = 0.0;
				double saturation = 0.0;
				double num3 = 0.0;
				array[0].RGBToHSV(out hue, out saturation, out num3);
				double hue2 = 0.0;
				double saturation2 = 0.0;
				double num4 = 0.0;
				array[1].RGBToHSV(out hue2, out saturation2, out num4);
				bool flag3 = ColorExt.ColorContrast(ColorExt.HSVToRGB(hue2, saturation2, 0.0), ColorExt.HSVToRGB(hue, saturation, 1.0)) >= ratio;
				if (flag3)
				{
					double num5 = 1.0 - num3;
					double num6 = num4;
					float[] array2 = new float[]
					{
						0.12f,
						0.1f,
						0.08f,
						0.05f,
						0.04f,
						0.03f,
						0.02f,
						0.01f,
						0.005f
					};
					int num7 = 0;
					double num8 = num5 / (num5 + num6);
					double num9 = num6 / (num5 + num6);
					while (ColorExt.ColorContrast(ColorExt.HSVToRGB(hue, saturation, num3), ColorExt.HSVToRGB(hue2, saturation2, num4)) < ratio)
					{
						while (ColorExt.ColorContrast(ColorExt.HSVToRGB(hue, saturation, num3 + num8 * (double)array2[num7]), ColorExt.HSVToRGB(hue2, saturation2, num4 - num9 * (double)array2[num7])) > ratio && num7 < array2.Length - 1)
						{
							num7++;
						}
						num3 += num8 * (double)array2[num7];
						num4 -= num9 * (double)array2[num7];
					}
					array[0] = ColorExt.HSVToRGB(hue, saturation, num3);
					array[1] = ColorExt.HSVToRGB(hue2, saturation2, num4);
				}
				else
				{
					array[0] = System.Drawing.Color.White;
					while (ColorExt.ColorContrast(System.Drawing.Color.White, ColorExt.HSVToRGB(hue2, saturation2, num4)) < ratio)
					{
						num4 -= 0.0099999997764825821;
					}
					array[1] = ColorExt.HSVToRGB(hue2, saturation2, num4);
				}
				result = array;
			}
			return result;
		}
		public static double ColorContrast(System.Drawing.Color a, System.Drawing.Color b)
		{
			double val = a.RelativeLuminance() + 0.05000000074505806;
			double val2 = b.RelativeLuminance() + 0.05000000074505806;
			return Math.Max(val, val2) / Math.Min(val, val2);
		}
				private static double ColorPartValue(double val)
