		public static bool IsLieOnSameStraightLine(this Line line1, Line line2, double tolerance = 0.0001)
		{
			bool flag = !line1.IsParallelTo(line2, tolerance);
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				IList<XYZ> list = line1.Tessellate();
				IList<XYZ> list2 = line2.Tessellate();
				XYZ direction = line1.Direction;
				foreach (XYZ current in list)
				{
					foreach (XYZ current2 in list2)
					{
						bool flag2 = Math.Abs(current.DistanceTo(current2)) < tolerance;
						if (flag2)
						{
							result = true;
							return result;
						}
						XYZ q = (current2 - current).Normalize();
						bool flag3 = !direction.IsParallel(q, tolerance);
						if (flag3)
						{
							result = false;
							return result;
						}
					}
				}
				result = true;
			}
			return result;
		}
