		public static bool ShiftedFrom(this Line line, Line other, out XYZ dir, out double distance)
		{
			dir = null;
			distance = 1.7976931348623157E+308;
			bool flag = line == null | other == null;
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				bool flag2 = line.IsBound != other.IsBound;
				if (flag2)
				{
					result = false;
				}
				else
				{
					bool isBound = line.IsBound;
					if (isBound)
					{
						XYZ endPoint = line.GetEndPoint(0);
						XYZ endPoint2 = line.GetEndPoint(1);
						XYZ endPoint3 = other.GetEndPoint(0);
						XYZ endPoint4 = other.GetEndPoint(1);
						dir = (endPoint - endPoint3).Normalize();
						distance = endPoint.DistanceTo(endPoint3);
						XYZ xYZ = endPoint2 - endPoint4;
						bool flag3 = !xYZ.Normalize().IsAlmostEqualTo(dir);
						if (flag3)
						{
							result = false;
						}
						else
						{
							bool flag4 = !xYZ.GetLength().IsEqual(distance);
							result = !flag4;
						}
					}
					else
					{
						bool flag5 = !line.Direction.IsAlmostEqualTo(other.Direction);
						if (flag5)
						{
							result = false;
						}
						else
						{
							XYZ xYZ2 = line.Origin - other.Origin;
							dir = xYZ2.Normalize();
							distance = xYZ2.GetLength();
							result = true;
						}
					}
				}
			}
			return result;
		}
		public static bool Contains(this Line line, XYZ p, double tolerance = 1E-09)
		{
			bool flag = line == null || p == null;
			bool result = false;
			if (flag)
			{
				result = false;
			}
			else
			{
				XYZ endPoint = line.GetEndPoint(0);
				XYZ endPoint2 = line.GetEndPoint(1);
				double num = endPoint.DistanceTo(endPoint2);
				double num2 = endPoint.DistanceTo(p);
				double num3 = p.DistanceTo(endPoint2);
				result = ((num2 + num3 - num) / num < tolerance);
			}
			return result;
		}
	}
	public class LineComparer : IEqualityComparer<Line>
	{
		private readonly bool _reversedIsEqual = false;
		private readonly double _tolerance = 0.0;
		public LineComparer(bool reversedIsEqual = false, double tolerance = 1E-09)
		{
			this._reversedIsEqual = reversedIsEqual;
			this._tolerance = tolerance;
		}
		public bool Equals(Line line1, Line line2)
		{
			bool flag = line1.EqualsTo(line2, this._tolerance);
			bool flag2 = flag;
			bool result = false;
			if (flag2)
			{
				result = true;
			}
			else
			{
				bool reversedIsEqual = this._reversedIsEqual;
				if (reversedIsEqual)
				{
					bool isBound = line2.IsBound;
					if (isBound)
					{
						Line other = line2.CreateReversed() as Line;
						result = line1.EqualsTo(other, this._tolerance);
						return result;
					}
				}
				result = false;
			}
			return result;
		}
		public int GetHashCode(Line line)
		{
			bool flag = line == null;
			int result = 0;
			if (flag)
			{
				result = 0;
			}
			else
			{
				XYZ endPoint = line.GetEndPoint(0);
				XYZ endPoint2 = line.GetEndPoint(1);
				long val = (long)Math.Round(endPoint.X / this._tolerance);
				long val2 = (long)Math.Round(endPoint.Y / this._tolerance);
				long val3 = (long)Math.Round(endPoint.Z / this._tolerance);
				long val4 = (long)Math.Round(endPoint2.X / this._tolerance);
				long val5 = (long)Math.Round(endPoint2.Y / this._tolerance);
				long val6 = (long)Math.Round(endPoint2.Z / this._tolerance);
				bool reversedIsEqual = this._reversedIsEqual;
				int num7 = 0;
				if (reversedIsEqual)
				{
					long num = Math.Min(val, val4);
					long num2 = Math.Min(val2, val5);
					long num3 = Math.Min(val3, val6);
					long num4 = Math.Max(val, val4);
					long num5 = Math.Max(val2, val5);
					long num6 = Math.Max(val3, val6);
					num7 = (num.GetHashCode() ^ num2.GetHashCode() ^ num3.GetHashCode() ^ num4.GetHashCode() ^ num5.GetHashCode() ^ num6.GetHashCode());
				}
				else
				{
					num7 = (val.GetHashCode() ^ val2.GetHashCode() ^ val3.GetHashCode() ^ val4.GetHashCode() ^ val5.GetHashCode() ^ val6.GetHashCode());
				}
				result = num7;
			}
			return result;
		}
	}
	public class LineComparerByDistanceToPoint : IComparer<Line>
	{
		private readonly XYZ _basePoint;
		private readonly XYZ _dir;
		private readonly XYZ _dirOrto;
		public LineComparerByDistanceToPoint(XYZ basePoint, XYZ dir, XYZ dirOrto)
		{
			this._basePoint = basePoint;
			this._dir = dir;
			this._dirOrto = dirOrto;
		}
		public int Compare(Line a, Line b)
		{
			XYZ xYZ = this._basePoint.ProjectToStraight(a.Origin, this._dir) - this._basePoint;
			XYZ xYZ2 = this._basePoint.ProjectToStraight(b.Origin, this._dir) - this._basePoint;
			bool flag = xYZ.Normalize().IsAlmostEqualTo(this._dirOrto);
			int result = 0;
			if (flag)
			{
				bool flag2 = xYZ2.Normalize().IsAlmostEqualTo(this._dirOrto);
				if (flag2)
				{
					double length = xYZ.GetLength();
					double length2 = xYZ2.GetLength();
					double num = Math.Round(length - length2, 9);
					bool flag3 = num == 0.0;
					if (flag3)
					{
						result = 0;
					}
					else
					{
						bool flag4 = num < 0.0;
						if (flag4)
						{
							result = -1;
						}
						else
						{
							result = 1;
						}
					}
				}
				else
				{
					result = 1;
				}
			}
			else
			{
				bool flag5 = xYZ2.Normalize().IsAlmostEqualTo(this._dirOrto);
				if (flag5)
				{
					result = -1;
				}
				else
				{
					double length3 = xYZ.GetLength();
					double length4 = xYZ2.GetLength();
					double num2 = Math.Round(length3 - length4, 9);
					bool flag6 = num2 == 0.0;
					if (flag6)
					{
						result = 0;
					}
					else
					{
						bool flag7 = num2 < 0.0;
						if (flag7)
						{
							result = 1;
						}
						else
						{
							result = -1;
						}
					}
				}
			}
			return result;
		}
	}
