	public static class LineStyleExt
	{
		public static Category Create(Autodesk.Revit.DB.Document doc, string styleName, Autodesk.Revit.DB.Color color, int weight, string patternName = "")
		{
			LineStyleData lsd = new LineStyleData(styleName, color, weight);
			return LineStyleExt.Create(doc, lsd, patternName);
		}
		public static Category Create(Autodesk.Revit.DB.Document doc, LineStyleData lsd, string patternName = "")
		{
			Categories categories = doc.Settings.Categories;
			Category parentCategory = categories.get_Item(BuiltInCategory.OST_Lines);
			Category category = categories.NewSubcategory(parentCategory, lsd.Name);
			doc.Regenerate();
			category.SetLineWeight(lsd.Weight, GraphicsStyleType.Projection);
			category.LineColor = lsd.Color;
			bool flag = string.IsNullOrEmpty(patternName);
			ElementId linePatternId;
			Category result;
