							continue;
						}
						list.Add(curve);
					}
					curve = current;
				}
				if (isClosed)
				{
					Curve curve2 = list.First<Curve>();
					bool flag4 = curve2 != null && CurveLoopExt.IsSameType(curve2, curve) && CurveLoopExt.AreShouldBeJoined(curve2, curve, tol);
					if (flag4)
					{
						curve = CurveLoopExt.Join(curve, curve2);
						list.RemoveAt(0);
					}
				}
				list.Add(curve);
				result = list;
			}
			return result;
		}
