		public static XYZ GetMassCenter(this CurveLoop curveLoop, double tolerance = 1E-08)
		{
			List<XYZ> list = curveLoop.ToPoints();
			bool flag = list.Count == 0;
			XYZ result;
			if (flag)
			{
				result = null;
			}
			else
			{
				bool flag2 = list.Count == 1;
				if (flag2)
				{
					result = list[0];
				}
				else
				{
					bool flag3 = list.Count == 2;
					if (flag3)
					{
						result = XYZext.LineMiddle(list[0], list[1]);
					}
					else
					{
						double z = list[0].Z;
						list.Add(new XYZ(list[0].X, list[0].Y, z));
						XYZ[] array = list.ToArray();
						double num = 0.0;
						double num2 = 0.0;
						double num3 = 0.0;
						for (int i = 0; i < array.Length - 1; i++)
						{
							double num4 = array[i].X * array[i + 1].Y - array[i + 1].X * array[i].Y;
							num += (array[i].X + array[i + 1].X) * num4;
							num2 += (array[i].Y + array[i + 1].Y) * num4;
							num3 += num4 / 2.0;
						}
						bool flag4 = Math.Abs(num3) >= tolerance;
						XYZ xYZ;
						if (flag4)
						{
							num = num / 6.0 / num3;
							num2 = num2 / 6.0 / num3;
							xYZ = new XYZ(num, num2, z);
						}
						else
						{
							XYZ a;
							XYZ b;
							CurveLoopExt.GetLineEnds(list, out a, out b, tolerance);
							xYZ = XYZext.LineMiddle(a, b);
						}
						list.RemoveAt(list.Count - 1);
						result = xYZ;
					}
				}
			}
			return result;
		}
		private static void GetLineEnds(List<XYZ> points, out XYZ end0, out XYZ end1, double tolerance = 1E-08)
		{
