	public static class ListExt
	{
		public static void Move<T>(this List<T> list, int oldIndex, int newIndex)
		{
			bool flag = oldIndex == newIndex || oldIndex < 0 || oldIndex >= list.Count || newIndex < 0 || newIndex >= list.Count;
			if (!flag)
			{
				T value = list[oldIndex];
				bool flag2 = oldIndex < newIndex;
				if (flag2)
				{
					for (int i = oldIndex; i < newIndex; i++)
					{
						list[i] = list[i + 1];
					}
				}
				else
				{
					for (int j = oldIndex; j > newIndex; j--)
					{
						list[j] = list[j - 1];
					}
				}
				list[newIndex] = value;
			}
		}
		public static List<T> Shift<T>(this List<T> list, int startIndex)
		{
			bool flag = list.Count == 0;
			List<T> result;
			if (flag)
			{
				result = new List<T>();
			}
			else
			{
				List<T> list2 = new List<T>();
				for (int i = 0; i < list.Count; i++)
				{
					list2.Add(list[(startIndex + i) % list.Count]);
				}
				result = list2;
			}
			return result;
		}
	}
	public static class OutlineExt
	{
		public static Autodesk.Revit.DB.Outline Create(XYZ p1, XYZ p2)
