			Autodesk.Revit.DB.Outline result;
			if (flag)
			{
				result = null;
			}
			else
			{
				double x = Math.Min(p1.X, p2.X);
				double y = Math.Min(p1.Y, p2.Y);
				double z = Math.Min(p1.Z, p2.Z);
				double x2 = Math.Max(p1.X, p2.X);
				double y2 = Math.Max(p1.Y, p2.Y);
				double z2 = Math.Max(p1.Z, p2.Z);
				result = new Autodesk.Revit.DB.Outline(new XYZ(x, y, z), new XYZ(x2, y2, z2));
			}
			return result;
		}
	}
	public static class PlaneExt
	{
		public static double SignedDistanceTo(this Plane plane, XYZ p)
		{
			Debug.Assert(plane.Normal.GetLength().IsEqual(1.0), "expected normalised plane normal");
			XYZ source = p - plane.Origin;
			return plane.Normal.DotProduct(source);
		}
		public static XYZ ProjectOfPoint(this Plane plane, XYZ p)
		{
			double value = plane.SignedDistanceTo(p);
			XYZ xYZ = p + value * plane.Normal;
			Debug.Assert(plane.SignedDistanceTo(xYZ).IsZero(), "expected point on plane to have zero distance to plane");
			return xYZ;
		}
		public static UV ProjectOfPointUV(this Plane plane, XYZ p)
		{
			XYZ left = plane.ProjectOfPoint(p);
			XYZ origin = plane.Origin;
			XYZ xYZ = left - origin;
			double u = xYZ.DotProduct(plane.XVec);
			double v = xYZ.DotProduct(plane.YVec);
			return new UV(u, v);
		}
		public static string Description(this Plane plane)
		{
			bool flag = plane == null;
			string result;
			if (flag)
			{
				result = "plane is null";
			}
			else
			{
				bool flag2 = !plane.IsValidObject;
				if (flag2)
				{
					result = "plane not valid";
				}
				else
				{
					string text = "plane: ";
					text = text + " origin " + plane.Origin.Description();
					text = text + ", normal " + plane.Normal.Description();
					text = text + ", XVec " + plane.XVec.Description();
					text = text + ", YVec " + plane.YVec.Description();
					result = text;
				}
			}
			return result;
		}
	}
	public static class SolidExt
	{
		public static PlanarFace GetTopFace(this Solid solid)
		{
			PlanarFace planarFace = null;
			FaceArray faces = solid.Faces;
			foreach (Face face in faces)
			{
				PlanarFace planarFace2 = face as PlanarFace;
				bool flag = null != planarFace2 && planarFace2.IsHorizontal();
				if (flag)
				{
					bool flag2 = null == planarFace || planarFace.Origin.Z < planarFace2.Origin.Z;
					if (flag2)
					{
						planarFace = planarFace2;
					}
				}
			}
			return planarFace;
		}
		public static List<XYZ> GetAllPoints(this Solid solid, bool distinct = false)
		{
			List<XYZ> list = new List<XYZ>();
			foreach (Edge edge in solid.Edges)
			{
				list.AddRange(edge.Tessellate());
			}
			if (distinct)
			{
				list = list.Distinct(new PointComparer(1E-09)).ToList<XYZ>();
			}
			return list;
		}
		public static Solid Intersection(this Solid hostSolid, RevitLinkInstance rli, Solid linkedSolid)
		{
