		public static DirectShape CreateDirectShape(this Solid solid, Autodesk.Revit.DB.Document doc, BuiltInCategory bic = BuiltInCategory.OST_GenericModel, string dataId = "", string name = "DirectShape")
		{
			bool flag = doc == null || solid == null;
			DirectShape result;
			if (flag)
			{
				result = null;
			}
			else
			{
				ElementId categoryId = new ElementId(bic);
				bool flag2 = string.IsNullOrEmpty(dataId);
				if (flag2)
				{
					dataId = Guid.NewGuid().ToString();
				}
				DirectShape directShape = DirectShape.CreateElement(doc, categoryId);
				directShape.ApplicationId = Assembly.GetExecutingAssembly().GetType().GUID.ToString();
				directShape.ApplicationDataId = dataId;
				directShape.SetShape(new GeometryObject[]
				{
					solid
				});
				directShape.Name = name;
				result = directShape;
			}
			return result;
		}
		public static bool IsPointInside(this Solid solid, XYZ point, out double minDistance)
		{
			minDistance = 1.7976931348623157E+308;
			bool result = false;
			foreach (Face face in solid.Faces)
			{
				IntersectionResult intersectionResult = face.Project(point);
				bool flag = intersectionResult == null;
				if (!flag)
				{
					XYZ xYZ = face.ComputeNormal(intersectionResult.UVPoint);
					bool flag2 = solid.Volume < 0.0;
					if (flag2)
					{
						xYZ = xYZ.Negate();
					}
					XYZ xYZ2 = point - intersectionResult.XYZPoint;
					double length = xYZ2.GetLength();
					bool flag3 = length < minDistance;
					if (flag3)
					{
						minDistance = length;
					}
					bool flag4 = xYZ.DotProduct(xYZ2) > 0.0;
					if (flag4)
					{
						result = false;
						return result;
					}
				}
			}
			minDistance = -minDistance;
			result = true;
			return result;
		}
		public static double DistanceTo(this Solid solid1, Solid solid2, bool distinctPoints = true)
		{
			bool flag = solid1 == null && solid2 == null;
			double result = 0.0;
			if (flag)
			{
				result = double.NaN;
			}
			else
			{
				double num = 1.7976931348623157E+308;
				List<XYZ> allPoints = solid2.GetAllPoints(distinctPoints);
				foreach (XYZ current in allPoints)
				{
					double num2 = 0.0;
					bool flag2 = solid1.IsPointInside(current, out num2);
					bool flag3 = num2 < num;
					if (flag3)
					{
						num = num2;
					}
				}
				result = num;
			}
			return result;
		}
	}
	public static class BoundingBoxUVext
	{
		public static bool Contains(this BoundingBoxUV bb, UV p)
		{
			return 0 < bb.Min.Compare(p) && 0 < p.Compare(bb.Max);
		}
		public static BoundingBoxUV Extend(this BoundingBoxUV bb, UV p)
		{
			bool flag = p == null;
			BoundingBoxUV result;
			if (flag)
			{
				result = bb;
			}
			else
			{
				double u = bb.Min.U;
				double v = bb.Min.V;
				bool flag2 = p.U < u;
				if (flag2)
				{
					u = p.U;
				}
				bool flag3 = p.V < v;
				if (flag3)
				{
					v = p.V;
				}
				bb.Min = new UV(u, v);
				u = bb.Max.U;
				v = bb.Max.V;
				bool flag4 = p.U > u;
				if (flag4)
				{
					u = p.U;
				}
				bool flag5 = p.V > v;
				if (flag5)
				{
					v = p.V;
				}
				bb.Max = new UV(u, v);
				result = bb;
			}
			return result;
		}
		public static BoundingBoxUV Extend(this BoundingBoxUV bb, XYZ p)
		{
			bool flag = p == null;
			BoundingBoxUV result;
			if (flag)
			{
				result = bb;
			}
			else
			{
				double num = bb.Min.U;
				double num2 = bb.Min.V;
				bool flag2 = p.X < num;
				if (flag2)
				{
					num = p.X;
				}
				bool flag3 = p.Y < num2;
				if (flag3)
				{
					num2 = p.Y;
				}
				bb.Min = new UV(num, num2);
				num = bb.Max.U;
				num2 = bb.Max.V;
				bool flag4 = p.X > num;
				if (flag4)
				{
					num = p.X;
				}
				bool flag5 = p.Y > num2;
				if (flag5)
				{
					num2 = p.Y;
				}
				bb.Max = new UV(num, num2);
				result = bb;
			}
			return result;
		}
		public static BoundingBoxUV Extend(this BoundingBoxUV bb, Curve curve)
		{
			bool flag = curve == null;
			BoundingBoxUV result;
			if (flag)
			{
				result = bb;
			}
			else
			{
				IList<XYZ> list = curve.Tessellate();
				foreach (XYZ current in list)
				{
					bb.Extend(current);
				}
				result = bb;
			}
			return result;
		}
		public static BoundingBoxUV Create(UV[] points, Transform2D trans2D)
		{
			bool flag = !points.Any<UV>();
			BoundingBoxUV result;
			if (flag)
			{
				result = new BoundingBoxUV();
			}
			else
			{
				UV uV = trans2D.OfPoint(points[0]);
				BoundingBoxUV boundingBoxUV = new BoundingBoxUV(uV.U, uV.V, uV.U, uV.V);
				for (int i = 1; i < points.Length; i++)
				{
					UV p = trans2D.OfPoint(points[i]);
					boundingBoxUV = boundingBoxUV.Extend(p);
				}
				result = boundingBoxUV;
			}
			return result;
		}
	}
	public static class BoundingBoxXYZext
	{
		public static bool Contains(this BoundingBoxXYZ bb, XYZ p)
		{
			return 0 < bb.Min.Compare(p) && 0 < p.Compare(bb.Max);
		}
		public static XYZ Middle(this BoundingBoxXYZ bb)
		{
			Transform transform = bb.Transform;
			XYZ xYZ = transform.OfPoint(bb.Min);
			XYZ left = transform.OfPoint(bb.Max);
			return xYZ + (left - xYZ) / 2.0;
		}
		public static BoundingBoxXYZ Extend(this BoundingBoxXYZ bb, XYZ p)
		{
			bool flag = p == null;
			BoundingBoxXYZ result;
			if (flag)
			{
				result = bb;
			}
			else
			{
				double x = bb.Min.X;
				double y = bb.Min.Y;
				double z = bb.Min.Z;
				bool flag2 = p.X < x;
				if (flag2)
				{
					x = p.X;
				}
				bool flag3 = p.Y < y;
				if (flag3)
				{
					y = p.Y;
				}
				bool flag4 = p.Y < z;
				if (flag4)
				{
					z = p.Z;
				}
				bb.Min = new XYZ(x, y, z);
				x = bb.Max.X;
				y = bb.Max.Y;
				z = bb.Max.Z;
				bool flag5 = p.X > x;
				if (flag5)
				{
					x = p.X;
				}
				bool flag6 = p.Y > y;
				if (flag6)
				{
					y = p.Y;
				}
				bool flag7 = p.Y > z;
				if (flag7)
				{
					z = p.Z;
				}
				bb.Max = new XYZ(x, y, z);
				result = bb;
			}
			return result;
		}
		public static BoundingBoxXYZ Extend(this BoundingBoxXYZ bb, Curve curve)
		{
			bool flag = curve == null;
			BoundingBoxXYZ result;
			if (flag)
			{
				result = bb;
			}
			else
			{
				IList<XYZ> list = curve.Tessellate();
				foreach (XYZ current in list)
				{
					bb.Extend(current);
				}
				result = bb;
			}
			return result;
		}
		public static Solid CreateSolid(this BoundingBoxXYZ bb)
		{
			XYZ xYZ = new XYZ(bb.Min.X, bb.Min.Y, bb.Min.Z);
			XYZ xYZ2 = new XYZ(bb.Max.X, bb.Min.Y, bb.Min.Z);
			XYZ xYZ3 = new XYZ(bb.Max.X, bb.Max.Y, bb.Min.Z);
			XYZ xYZ4 = new XYZ(bb.Min.X, bb.Max.Y, bb.Min.Z);
			Line item = Line.CreateBound(xYZ, xYZ2);
			Line item2 = Line.CreateBound(xYZ2, xYZ3);
			Line item3 = Line.CreateBound(xYZ3, xYZ4);
			Line item4 = Line.CreateBound(xYZ4, xYZ);
			List<Curve> curves = new List<Curve>
			{
				item,
				item2,
				item3,
				item4
			};
			double extrusionDist = bb.Max.Z - bb.Min.Z;
			CurveLoop item5 = CurveLoop.Create(curves);
			List<CurveLoop> profileLoops = new List<CurveLoop>
			{
				item5
			};
			Solid solid = GeometryCreationUtilities.CreateExtrusionGeometry(profileLoops, XYZ.BasisZ, extrusionDist);
			return SolidUtils.CreateTransformed(solid, bb.Transform);
		}
		public static string Description(this BoundingBoxXYZ bb)
		{
			return string.Concat(new string[]
			{
				"(",
				bb.Min.Description(),
				",",
				bb.Max.Description(),
				")"
			});
		}
		public static BoundingBoxXYZ CalcGeneral(IEnumerable<Element> elems)
		{
			bool flag = elems == null || !elems.Any<Element>();
			BoundingBoxXYZ result;
			if (flag)
			{
				result = null;
			}
			else
			{
				Element element = elems.FirstOrDefault<Element>();
				bool flag2 = element == null || !element.IsValidObject;
				if (flag2)
				{
					result = null;
				}
				else
				{
					BoundingBoxXYZ boundingBoxXYZ = element.get_BoundingBox(null);
					bool flag3 = boundingBoxXYZ == null;
					if (flag3)
					{
						result = null;
					}
					else
					{
						foreach (Element current in elems)
						{
							BoundingBoxXYZ boundingBoxXYZ2 = current.get_BoundingBox(null);
							double x = boundingBoxXYZ.Min.X;
							double y = boundingBoxXYZ.Min.Y;
							double z = boundingBoxXYZ.Min.Z;
							bool flag4 = boundingBoxXYZ2.Min.X < boundingBoxXYZ.Min.X;
							if (flag4)
							{
								x = boundingBoxXYZ2.Min.X;
							}
							bool flag5 = boundingBoxXYZ2.Min.Y < boundingBoxXYZ.Min.Y;
							if (flag5)
							{
								y = boundingBoxXYZ2.Min.Y;
							}
							bool flag6 = boundingBoxXYZ2.Min.Z < boundingBoxXYZ.Min.Z;
							if (flag6)
							{
								z = boundingBoxXYZ2.Min.Z;
							}
							boundingBoxXYZ.Min = new XYZ(x, y, z);
							x = boundingBoxXYZ.Max.X;
							y = boundingBoxXYZ.Max.Y;
							z = boundingBoxXYZ.Max.Z;
							bool flag7 = boundingBoxXYZ2.Max.X > boundingBoxXYZ.Max.X;
							if (flag7)
							{
								x = boundingBoxXYZ2.Max.X;
							}
							bool flag8 = boundingBoxXYZ2.Max.Y > boundingBoxXYZ.Max.Y;
							if (flag8)
							{
								y = boundingBoxXYZ2.Max.Y;
							}
							bool flag9 = boundingBoxXYZ2.Max.Z > boundingBoxXYZ.Max.Z;
							if (flag9)
							{
								z = boundingBoxXYZ2.Max.Z;
							}
							boundingBoxXYZ.Max = new XYZ(x, y, z);
						}
						result = boundingBoxXYZ;
					}
				}
			}
			return result;
		}
	}
	public static class CategoryExt
	{
