		public static Element GetFirstElement(this BuiltInCategory bic, Autodesk.Revit.DB.Document doc, bool isElementType)
		{
			FilteredElementCollector filteredElementCollector = new FilteredElementCollector(doc);
			Element result;
			if (isElementType)
			{
				result = filteredElementCollector.WhereElementIsElementType().OfCategory(bic).FirstElement();
			}
			else
			{
				result = filteredElementCollector.WhereElementIsNotElementType().OfCategory(bic).FirstElement();
			}
