	public static class PlanarFaceExt
	{
		public static bool IsHorizontal(this PlanarFace f)
		{
			return f.FaceNormal.IsVertical();
		}
		public static bool IsVertical(this PlanarFace f)
		{
			return f.FaceNormal.IsHorizontal();
		}
		public static List<Line> GetLineBounds(this PlanarFace f)
		{
			List<Line> list = new List<Line>();
			IList<CurveLoop> edgesAsCurveLoops = f.GetEdgesAsCurveLoops();
			for (int i = 0; i < edgesAsCurveLoops.Count; i++)
			{
				List<Line> collection = edgesAsCurveLoops[i].ToLines();
				list.AddRange(collection);
			}
			return list;
		}
		public static List<Tuple<int, Reference, XYZ, XYZ>> GetHatchGridsInfo(this PlanarFace pf, Autodesk.Revit.DB.Document doc, Reference faceRef, int gridCount)
		{
			List<Tuple<int, Reference, XYZ, XYZ>> list = new List<Tuple<int, Reference, XYZ, XYZ>>();
			bool flag = pf == null || doc == null || faceRef == null || gridCount < 1;
			List<Tuple<int, Reference, XYZ, XYZ>> result;
			if (flag)
			{
				result = list;
			}
			else
			{
				string str = faceRef.ConvertToStableRepresentation(doc);
				for (int i = 0; i < gridCount; i++)
				{
					ReferenceArray referenceArray = new ReferenceArray();
					for (int j = 0; j < 2; j++)
					{
						int num = i + 1 + j * gridCount * 2;
						string representation = str + string.Format("/{0}", num);
						Reference reference = null;
						try
						{
							reference = Reference.ParseFromStableRepresentation(doc, representation);
						}
						catch
						{
						}
						bool flag2 = reference == null;
						if (!flag2)
						{
							referenceArray.Append(reference);
						}
					}
					bool flag3 = referenceArray.Size > 1;
					if (flag3)
					{
						using (SubTransaction subTransaction = new SubTransaction(doc))
						{
							subTransaction.Start();
							Autodesk.Revit.DB.Dimension dimension = doc.Create.NewDimension(doc.ActiveView, Line.CreateBound(XYZ.Zero, new XYZ(10.0, 0.0, 0.0)), referenceArray);
							ElementTransformUtils.MoveElement(doc, dimension.Id, new XYZ(0.1, 0.0, 0.0));
							Reference item = dimension.References.get_Item(0);
							XYZ direction = (dimension.Curve as Line).Direction;
							XYZ item2 = direction.CrossProduct(pf.FaceNormal).Normalize();
							double num2 = dimension.Value.Value;
							XYZ item3 = dimension.Origin.Subtract(direction.Multiply(num2 / 2.0));
							list.Add(new Tuple<int, Reference, XYZ, XYZ>(i, item, item3, item2));
							subTransaction.RollBack();
						}
					}
				}
				result = list;
			}
			return result;
		}
		public static string Description(this PlanarFace f, bool addEdgesDescription = true)
		{
			bool flag = f == null;
			string result;
			if (flag)
			{
				result = "planar face is null";
			}
			else
			{
				StringBuilder stringBuilder = new StringBuilder("PlanarFace\r\n");
				stringBuilder.AppendLine("normal: " + f.FaceNormal.Description());
