				Func<Definition, bool> __9__0 = null;
				foreach (DefinitionGroup current in localFOP.Groups)
				{
					IEnumerable<Definition> arg_8D_0 = current.Definitions;
					Func<Definition, bool> arg_8D_1 = null;
					if ((arg_8D_1 = __9__0) == null)
					{
