					bool flag2 = ParamGroupService.BindingMapInsert(parameterBindings, definition, binding, group);
					bool flag3 = !flag2;
					if (flag3)
					{
						flag2 = ParamGroupService.BindingMapReInsert(parameterBindings, definition, binding, group);
					}
					bool flag4 = !flag2;
					if (flag4)
					{
						errReport = text;
						Debug.Print(errReport);
						result = false;
					}
					else
					{
						result = true;
					}
				}
				catch (Exception ex)
				{
					errReport = text + "\r\n" + ex.Message;
					Log.Write(errReport);
					Log.Write(ex);
					result = false;
				}
			}
			return result;
		}
