		public bool ProvideParams<TEnum>(RevitParameterManager rpm, XElement defDtoSet, ParamDtoSet<TEnum> dtoSet) where TEnum : struct
		{
			string sharedParametersFilename;
			DefinitionFile fOP = this.GetFOP(out sharedParametersFilename);
			bool flag = fOP == null;
			bool result = false;
			if (flag)
			{
				this._doc.Application.SharedParametersFilename = sharedParametersFilename;
				result = false;
			}
			else
			{
				ParamsProvider<TEnum> paramsProvider = new ParamsProvider<TEnum>(this._doc, rpm, defDtoSet, dtoSet, fOP);
				bool flag2 = !this.IsProviderReady(paramsProvider);
				if (flag2)
				{
					result = false;
				}
				else
				{
					bool flag3 = !paramsProvider.Process();
					if (flag3)
					{
						this.ShowErrorDialog(paramsProvider.ErrReport, paramsProvider.Report);
						this._doc.Application.SharedParametersFilename = sharedParametersFilename;
						result = false;
					}
					else
					{
						this._doc.Application.SharedParametersFilename = sharedParametersFilename;
