		public bool ProvideParam(RevitParameterManager rpm, XElement defDto, ParamDto dto)
		{
			ParamDtoSet<SingleParam> paramDtoSet = new ParamDtoSet<SingleParam>(dto, SingleParam.Nick.ToString());
			paramDtoSet.SetDescriptions();
			return this.ProvideParams<SingleParam>(rpm, defDto, paramDtoSet);
		}
