	internal class Utils
	{
		public static string MakeReport(List<string> successful, List<ValueTuple<string, string>> unsuccessful, string dataTypeName)
		{
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = successful.Any<string>();
			if (flag)
			{
				foreach (string current in successful)
				{
					stringBuilder.Append(dataTypeName);
					stringBuilder.Append(" ");
					stringBuilder.Append(current);
					stringBuilder.Append(".");
					stringBuilder.AppendLine();
				}
			}
			bool flag2 = unsuccessful.Any<ValueTuple<string, string>>();
			if (flag2)
			{
				foreach (ValueTuple<string, string> current2 in unsuccessful)
				{
					stringBuilder.Append(dataTypeName);
					stringBuilder.Append(" ");
					stringBuilder.Append(current2.Item1);
					stringBuilder.Append(". Причина: ");
					stringBuilder.AppendLine(current2.Item2);
					stringBuilder.AppendLine();
				}
			}
			return stringBuilder.ToString();
		}
	}
